/// Unsaved edits to one animation's header, applied as a single undo step.
#[derive(Default, PartialEq, Debug)]
struct AnimationDraft {
    /// Animation name and session revision the fields were read at.
    source: (String, u64),
    length: i64,
    lead_in: i64,
    lead_out: i64,
    additive: bool,
    weight: f64,
    framerate: f64,
    /// Stored timestep, sent back untouched unless the framerate field is edited.
    timestep: f64,
    loop_editing: bool,
    original: Option<Value>,
}

impl AnimationDraft {
    fn read(source: (String, u64), animation: &Value) -> Self {
        let timestep = animation["timestep"].as_f64().filter(|step| *step > 0.0);
        let mut draft = Self {
            source,
            length: animation["length"].as_i64().unwrap_or(1),
            lead_in: animation["leadIn"].as_i64().unwrap_or(-1),
            lead_out: animation["leadOut"].as_i64().unwrap_or(-1),
            additive: animation["additive"].as_bool().unwrap_or(false),
            weight: animation["animationWeight"].as_f64().unwrap_or(1.0),
            framerate: timestep.map_or(60.0, Self::shown_framerate),
            timestep: timestep.unwrap_or(1.0 / 60.0),
            loop_editing: animation["loopEditing"].as_bool().unwrap_or(false),
            original: None,
        };
        draft.original = Some(draft.request());
        draft
    }

    fn has_draft(&self) -> bool {
        self.original.as_ref().is_some_and(|original| original != &self.request())
    }

    fn shown_framerate(timestep: f64) -> f64 {
        (1.0 / timestep * 1000.0).round() / 1000.0
    }

    fn request(&self) -> Value {
        json!({
            "op": "animation.set",
            "name": self.source.0,
            "length": self.length,
            "timestep": if self.framerate == Self::shown_framerate(self.timestep) {
                self.timestep
            } else {
                1.0 / self.framerate
            },
            "leadIn": self.lead_in,
            "leadOut": self.lead_out,
            "additive": self.additive,
            "animationWeight": self.weight,
            "loopEditing": self.loop_editing,
        })
    }
}

/// The window size of the last session, read without side effects (before the editor loads its settings).
pub fn stored_window_geometry() -> WindowGeometry {
    let stored = app_settings::app_config_dir()
        .ok()
        .and_then(|dir| std::fs::read(app_settings::settings_path(&dir)).ok())
        .and_then(|bytes| app_settings::Settings::parse(&bytes).ok());
    stored.as_ref().map_or_else(|| WindowGeometry::load(&app_settings::Settings::empty()), WindowGeometry::load)
}

/// A document replacement waiting for the unsaved-changes dialog.
enum PendingAction {
    /// A session request that replaces the document (`new`, `open ... as`, `import.*`).
    Request(Value),
    /// Open a path (may raise the autosave restore prompt).
    Open(String),
    /// Import the layered file in the tools import draft.
    ImportLayers,
    /// Close the window.
    Close,
}

struct UnsavedState {
    action: PendingAction,
    dialog: crate::editor_shell::UnsavedDialog,
}

/// What the agent panel sends with the first prompt of an ACP session, as a second text block: the MCP server
/// is already offered in `session/new`, the operating skill is served as resources, and the selection is a
/// snapshot the agent must re-read. The log shows it as "Soul2D".
fn agent_briefing(controller: &EditorController) -> String {
    use soul2d_core::mcp_guides::{SKILL_FAMILIES, SKILL_FAMILY_PREFIX, SKILL_URI};
    let snapshot = controller.snapshot();
    let path = controller.project_path().map_or("no path yet".to_owned(), |path| format!("path {}", path.display()));
    format!(
        "Soul2D briefing, sent once per session by the editor. This session has the Soul2D MCP server: use it and skip \
         the operating skill's host setup. The operating skill is served as MCP resources: {SKILL_URI} is its SKILL.md \
         and {SKILL_FAMILY_PREFIX}<family> one of its {} family maps (resources/list names them). Read \
         resource://soul2d/editor/state before acting; at this prompt: format {}, {path}, revision {}, selected nodes {:?}.",
        SKILL_FAMILIES.len(),
        snapshot["documentFormat"].as_str().unwrap_or("none"),
        snapshot["revision"],
        controller.selected_nodes(),
    )
}

/// What the unsaved-changes dialog will do once answered, for the state resource.
fn pending_action_kind(action: &PendingAction) -> &'static str {
    match action {
        PendingAction::Request(request) => match request["op"].as_str() {
            Some("new") => "new",
            Some("open") => "open",
            Some(op) if op.starts_with("import") => "import",
            _ => "replace",
        },
        PendingAction::Open(_) => "open",
        PendingAction::ImportLayers => "import",
        PendingAction::Close => "close",
    }
}

