/// Cubism's lightweight playback: while the window plays an animation or a motion, the parameter panels keep
/// the values they showed before it started. Session only, like Loop.
#[derive(Default)]
struct LightweightPlayback {
    on: bool,
    /// The runtime values the panels show next while frozen.
    shown: Value,
}

impl LightweightPlayback {
    /// Once a frame, after playback ticks: the shown values follow the session unless they are frozen.
    fn follow(&mut self, playing: bool, live: &Value) {
        if !(self.on && playing) {
            self.shown = live.clone();
        }
    }

    /// The values the parameter panels show in place of the session's, while frozen.
    fn frozen(&self, playing: bool) -> Option<&Value> {
        (self.on && playing).then_some(&self.shown)
    }

    fn checkbox(&mut self, ui: &mut egui::Ui) {
        ui.checkbox(&mut self.on, "Lightweight playback")
            .on_hover_text("Parameter sliders and values are not updated while playback runs");
    }
}

const QUIT_REPLY_TIMEOUT: Duration = Duration::from_secs(5);
const ACP_QUIT_TURN_TIMEOUT: Duration = Duration::from_secs(120);

enum QuitOrigin {
    External,
    Acp { target: crate::editor_agent::AcpQuitTarget, admitted_at: Instant, turn_deadline: Instant },
}

#[derive(Default)]
enum RemoteQuit {
    #[default]
    Idle,
    Reviewing { attempt: u64, revision: Value, path: Option<PathBuf>, target: crate::editor_agent::AcpQuitTarget },
    Waiting { attempt: u64, revision: Value, path: Option<PathBuf>, receipt: Receiver<Result<(), String>>, deadline: Instant,
        origin: QuitOrigin, delivered: bool },
    Cancelled { attempt: u64, reason: String, invalid: Option<crate::editor_agent::AcpQuitTarget> },
    Closing(u64),
}

impl RemoteQuit {
    fn attempt(&self) -> u64 {
        match self { Self::Idle => 0, Self::Reviewing { attempt, .. } | Self::Waiting { attempt, .. } | Self::Cancelled { attempt, .. } | Self::Closing(attempt) => *attempt }
    }

    fn target(&self) -> Option<&crate::editor_agent::AcpQuitTarget> {
        match self {
            Self::Reviewing { target, .. } | Self::Waiting { origin: QuitOrigin::Acp { target, .. }, .. } => Some(target),
            Self::Cancelled { invalid, .. } => invalid.as_ref(),
            _ => None,
        }
    }

    fn active(&self) -> bool { matches!(self, Self::Reviewing { .. } | Self::Waiting { .. }) }

    fn cancel(&mut self, reason: impl Into<String>) {
        if self.active() {
            *self = Self::Cancelled { attempt: self.attempt(), reason: reason.into(), invalid: self.target().cloned() };
        }
    }

    fn state(&self) -> Value {
        match self {
            Self::Idle => json!({"state":"idle"}),
            Self::Reviewing { attempt, .. } => json!({"state":"awaiting_human","attempt":attempt,"origin":"acp"}),
            Self::Waiting { attempt, origin: QuitOrigin::Acp { .. }, delivered, .. } => json!({"state":
                if *delivered { "waiting_for_turn" } else { "waiting_for_reply_and_turn" },"attempt":attempt,"origin":"acp"}),
            Self::Waiting { attempt, .. } => json!({"state":"waiting_for_reply","attempt":attempt}),
            Self::Cancelled { attempt, reason, .. } => json!({"state":"cancelled","attempt":attempt,"reason":reason}),
            Self::Closing(attempt) => json!({"state":"closing","attempt":attempt}),
        }
    }
}

/// The editor state MCP reads and sets (`resource://soul2d/editor/state`, the `editor_*` tools), borrowed
/// apart from the controller, the listener and the agent panel so every MCP entry point can hold those too.
/// All of it is view state: nothing here reaches the document, its history or its revision.
struct EditorView<'a> {
    remote_quit: &'a mut RemoteQuit,
    animation_draft: &'a mut AnimationDraft,
    timeline_value_draft: &'a mut Option<(TimelineSelection, f64)>,
    timeline_tension_draft: &'a mut Option<(TimelineSelection, f64)>,
    timeline_weight_draft: &'a mut Option<(String, f64)>,
    form_time_draft: &'a mut Option<f64>,
    sequence_panel: &'a mut crate::editor_sequence::SequencePanel,
    marker_at: &'a mut Option<(String, i64)>,
    marker_text: &'a mut String,
    marker_to: &'a mut i64,
    agent_owner: Option<u64>,
    agent_state: crate::editor_agent::PanelState,
    psd_depth_open: bool,
    /// The unsaved-changes dialog, while it waits for an answer.
    unsaved: &'a Option<UnsavedState>,
    /// The user confirmed closing: the exit releases the adopted snapshot and deletes it.
    closing: &'a bool,
    viewport: &'a mut crate::editor_viewport::ViewportState,
    parameters: &'a mut ParameterPanelState,
    parameter_filter: &'a mut String,
    animation_name: &'a mut String,
    seek_frame: &'a mut f64,
    mesh_tools: &'a mut crate::editor_mesh_tools::MeshTools,
    depth_tools: &'a mut crate::editor_depth::DepthTools,
    /// The settings store and what the Settings window and the recovery offer hold.
    tools: &'a mut ToolsState,
    windows: &'a mut crate::editor_windows::Windows,
    recovery_offer: &'a mut Vec<PathBuf>,
    /// The toolbar's path field.
    file_path: &'a mut String,
    /// `None` while a fit to the scene bounds is pending (`render_preview`).
    preview_bounds: &'a mut Option<(u64, Value)>,
    // What else `after_document_replaced` resets, besides `parameters`, `tools` and `preview_bounds`.
    notice: &'a mut String,
    preview_dirty: &'a mut bool,
    preview_warnings: &'a mut Vec<String>,
    native_scene_guid: &'a mut String,
    can3_scene_draft: &'a mut Can3SceneDraft,
    can3_delete: &'a mut Option<Can3DeleteConfirmation>,
    can3_track_draft: &'a mut Option<Can3TrackDraft>,
    can3_curve_draft: &'a mut Option<Can3CurveDraft>,
    can3_key_draft: &'a mut Option<Can3KeyDraft>,
    can3_curve_track_guid: &'a mut String,
    can3_part_choices: &'a mut Can3PartChoices,
    native_resource_guid: &'a mut String,
    native_asset_path: &'a mut String,
    expression_name: &'a mut String,
    motion3: &'a mut crate::editor_motion3::Motion3Panel,
    part_split_review: &'a mut crate::editor_part_split::PartSplitReview,
    forms: &'a mut crate::editor_live2d_forms::FormEditor,
    objects: &'a mut crate::editor_live2d_objects::ObjectEditor,
    physics_groups: &'a mut crate::editor_physics_groups::PhysicsGroups,
    lightweight: &'a mut LightweightPlayback,
    snap_to_framerate: &'a mut bool,
    timeline_zoom: &'a mut f32,
    /// The Timeline panel's selected keyframe, read by the state resource.
    timeline_selection: &'a mut Option<TimelineSelection>,
    form_read: &'a mut Value,
    controller_places: &'a mut (Value, Value),
    form_places: &'a mut (Value, Vec<[f64; 2]>),
    /// Holds the panel sizes a workspace saves and restores.
    ctx: &'a egui::Context,
}

