fn mesh_tool_id(tool: crate::editor_mesh_tools::Tool) -> &'static str {
    use crate::editor_mesh_tools::Tool;
    match tool {
        Tool::Point => "point",
        Tool::Connect => "connect",
        Tool::Grid => "grid",
        Tool::Lasso => "lasso",
        Tool::EdgeCutter => "edge_cutter",
        Tool::Brush => "brush",
        Tool::PathDeform => "path_deform",
        Tool::Bezier => "bezier",
    }
}

fn depth_tool_id(tool: crate::editor_depth::Tool) -> &'static str {
    use crate::editor_depth::Tool;
    match tool {
        Tool::DirectDepth => "direct_depth",
        Tool::Ring => "ring",
        Tool::AttachedPoint => "attached_point",
        Tool::Plane => "plane",
    }
}

enum McpOrigin<'a> {
    Client,
    Internal,
    Agent(&'a mut crate::editor_agent::HostApproval),
}

fn recovery_snapshots(config_dir: Option<&Path>, own: Option<&Path>) -> Result<Vec<PathBuf>, String> {
    let dir = config_dir.ok_or("recovery snapshots are unavailable: no settings directory")?;
    let mut files = autosave::list_recovery(dir)?;
    files.retain(|path| Some(path.as_path()) != own && path.file_name().is_some_and(|name| name.to_str().is_some()));
    Ok(files)
}

impl EditorView<'_> {
    /// One MCP message: the controller answers it and asks this view for the `editor.*` requests.
    fn mcp(&mut self, controller: &mut EditorController, message: &Value, mut origin: McpOrigin<'_>) -> RpcReply {
        let reply_capable = matches!(origin, McpOrigin::Client);
        let acp_quit = match &origin { McpOrigin::Agent(approval) => approval.quit_target().ok(), _ => None };
        let is_quit = message["method"] == "tools/call" && message["params"]["name"] == "editor_quit";
        let read_only = matches!(message["method"].as_str(), Some("tools/list" | "resources/list" | "resources/templates/list" | "resources/read" | "ping" | "initialize"))
            || (message["method"] == "tools/call" && message["params"]["name"].as_str()
                .is_some_and(|name| soul2d_core::manifest::effect_of(name) == Some("-")));
        if !is_quit && !read_only { self.remote_quit.cancel("new_operation"); }
        if self.remote_quit.active() {
            let changed = match &*self.remote_quit {
                RemoteQuit::Reviewing { revision, path, .. } | RemoteQuit::Waiting { revision, path, .. } =>
                    revision != &controller.snapshot()["revision"] || path.as_deref() != controller.project_path(),
                _ => false,
            };
            if changed { self.remote_quit.cancel("document_changed"); }
            else if let Some(reason) = self.quit_work_refusal(controller) { self.remote_quit.cancel(reason); }
        }
        let quit_target = acp_quit.as_ref().ok_or_else(|| "ACP Quit needs its original authenticated active prompt".to_owned())
            .and_then(|target| {
                if let Some(reason) = self.quit_work_refusal(controller) { return Err(reason); }
                if self.agent_owner != Some(target.owner()) { return Err("ACP client ownership changed".into()); }
                match &*self.remote_quit {
                    RemoteQuit::Reviewing { target: expected, .. } if expected == target => Ok(target.clone()),
                    RemoteQuit::Reviewing { .. } | RemoteQuit::Waiting { .. } | RemoteQuit::Closing(_) => Err("Quit already pending; read editor state".into()),
                    RemoteQuit::Cancelled { invalid: Some(invalid), .. } if invalid == target => Err("This original Quit request was invalidated; make a fresh request".into()),
                    _ => Ok(target.clone()),
                }
            });
        let mut quit_receipt = None;
        self.viewport.reconcile_views(controller.snapshot());
        self.parameters.reconcile(controller.snapshot(), self.animation_name, self.seek_frame);
        controller.replacement_refusal = self.replacement_refusal(controller.snapshot());
        let settings_path = self.tools.store_path.clone();
        let settings_locales = self.tools.locales.clone();
        let recovery_directory = self.tools.config_dir.clone();
        let own_recovery = self.tools.recovery.as_ref().and_then(autosave::Recovery::current).map(Path::to_owned);
        let replacement_refusal = controller.replacement_refusal.clone();
        let approval_snapshot = matches!(&origin, McpOrigin::Agent(_)).then(|| controller.snapshot().clone());
        let modified = controller.snapshot()["modified"].as_bool() == Some(true);
        let dirty = controller.draft_dirty() || controller.panel_drafts;
        let approval_document = controller.snapshot()["revision"].as_u64().map(|revision|
            crate::editor_agent::ApprovalDocument { revision,
                draft_dirty: controller.draft_dirty() || controller.panel_drafts,
                path: controller.project_path().map(Path::to_owned) });
        let mut attachment_request = false;
        let response = controller.mcp_request_with_prepared(message, matches!(&origin, McpOrigin::Agent(_)), &mut |call, prepared| {
            attachment_request |= matches!(call["op"].as_str(), Some("live2d.model.attach" | "live2d.animation.attach"));
            if let McpOrigin::Agent(approval) = &mut origin {
                if call["op"] == "editor.quit" {
                    if message["jsonrpc"] != "2.0" || !message.get("id").is_some_and(|id|
                        id.is_string() || id.as_i64().is_some() || id.as_u64().is_some()) {
                        return Err("ACP Quit requires an identified request with a reply writer".into());
                    }
                    let target = quit_target.clone()?;
                    return approval.guard(call, Ok(crate::editor_agent::ApprovalTarget::Quit(target)), approval_document.clone());
                }
                if call["op"] == "split.apply" {
                    return Err("Split application needs human review. Use Apply reviewed split in Part split review.".to_owned());
                }
                if call["op"] == "editor.settings.set" {
                    crate::editor_windows::validate_setting(&settings_locales,
                        call["key"].as_str().unwrap_or_default(), &call["value"])?;
                }
                if call["op"] == "editor.shortcut.set" {
                    crate::editor_windows::validate_shortcut(call["command"].as_str().unwrap_or_default(), &call["shortcut"])?;
                }
                // The link in meta.psdSource comes from the document, so an agent names the file it merges.
                if matches!(call["op"].as_str(), Some("merge.psd.plan" | "merge.psd.apply"))
                    && call["path"].as_str().is_none() {
                    return Err("An agent merge names the PSD path; read meta.psdSource and pass it as path".into());
                }
                if !crate::editor_agent::HostApproval::covers(call) { return Ok(()) }
                if call["op"] == "export.gltf" && matches!(&prepared, Ok(Some(export::ExportConsent::GltfReport))) {
                    return Ok(());
                }
                if message.get("id").is_none_or(Value::is_null) {
                    return Err("ACP protected operations require a request id; notifications cannot authorize changes".into());
                }
                let target = (|| {
                    use crate::editor_agent::ApprovalTarget;
                    soul2d_core::editor_controller::file_op_gate(dirty, modified, call)?;
                    if soul2d_core::editor_controller::replaces_document(call) || call["op"] == "editor.recovery.restore" {
                        if let Some(refusal) = &replacement_refusal { return Err(refusal.clone()) }
                    }
                    Ok(match call["op"].as_str() {
                        Some("new") => ApprovalTarget::NewDocument,
                        Some("open" | "import.psd" | "import.kra" | "import.inp" | "import.folder") => {
                            let path = std::fs::canonicalize(call["path"].as_str().ok_or("The operation needs an input path")?)
                                .map_err(|error| format!("could not resolve input path: {error}"))?;
                            if call["op"] == "import.folder" {
                                if !path.is_dir() { return Err("The input path must be a directory".into()) }
                                ApprovalTarget::SourceDirectory(path)
                            } else {
                                if !path.is_file() { return Err("The input path must be a regular file".into()) }
                                ApprovalTarget::SourceFile(path)
                            }
                        }
                        Some("editor.recovery.restore") => {
                            let snapshots = recovery_snapshots(recovery_directory.as_deref(), own_recovery.as_deref())?;
                            let path = autosave::recovery_named(&snapshots, call["id"].as_str().unwrap_or_default())?;
                            ApprovalTarget::Recovery(path.canonicalize().map_err(|error| format!("could not resolve recovery snapshot: {error}"))?)
                        }
                        Some("export.video.start") => match prepared? {
                            Some(export::ExportConsent::Video(video)) => ApprovalTarget::ExternalProcess(video.clone()),
                            _ => return Err("Video launch was not prepared".into()),
                        },
                        Some("export.collect") => match prepared? {
                            Some(export::ExportConsent::Collection(plan)) => ApprovalTarget::Collection(plan.clone()),
                            _ => return Err("Collection was not prepared".into()),
                        },
                        Some("export.gltf") => match prepared? {
                            Some(export::ExportConsent::Gltf(plan)) => ApprovalTarget::Gltf(plan.clone()),
                            _ => return Err("glTF write was not prepared".into()),
                        },
                        Some("depth.draw.export_png") => match prepared? {
                            Some(export::ExportConsent::DepthPng(plan)) => ApprovalTarget::DepthPng(plan.clone()),
                            _ => return Err("Depth PNG export needs a prepared output plan".into()),
                        },
                        Some("automesh.preset.save" | "automesh.preset.delete" | "physics.preset.save" | "physics.preset.delete"
                            | "live2d.physics3.preset.save" | "live2d.physics3.preset.delete"
                            | "animation.template.save" | "animation.template.delete") => match prepared? {
                            Some(export::ExportConsent::Store(plan)) => ApprovalTarget::Store(plan.clone()),
                            _ => return Err("Preset write needs a prepared store plan".into()),
                        },
                        Some("export.frames") => {
                            let raw = call["path"].as_str().ok_or("File writes need an output path")?;
                            let target = soul2d_core::normalized_export_target(raw, Path::new(raw),
                                approval_document.as_ref().and_then(|document| document.path.as_deref()), "export.frames")?;
                            let options = export::VideoExportOptions::from_request(call)?;
                            let paths = export::frame_sequence_paths(approval_snapshot.as_ref().unwrap(), &options, &target)?;
                            if let Some(open) = approval_document.as_ref().and_then(|document| document.path.as_deref()) {
                                let open = soul2d_core::normalize_target_path(open)?;
                                if paths.contains(&open) { return Err("export.frames would overwrite the open document".into()) }
                            }
                            ApprovalTarget::Outputs(paths)
                        }
                        Some("save") => ApprovalTarget::Output(soul2d_core::normalize_target_path(
                            Path::new(call["path"].as_str().ok_or("File writes need an output path")?))?),
                        Some(op @ ("render" | "export.inp" | "export.image" | "export.gif" | "view.screenshot" |
                            "object.export_csv" | "model.template.export" | "motion3.export" | "animation.onion" |
                            "live2d.cdi3.export" |
                            "live2d.physics3.export" | "live2d.userdata3.export")) => {
                            let raw = call["path"].as_str().ok_or("File writes need an output path")?;
                            let path = Path::new(raw);
                            let named = match op {
                                "export.inp" => path.with_extension("inp"),
                                "export.gif" => path.with_extension("gif"),
                                "view.screenshot" => path.with_extension("png"),
                                "export.image" => {
                                    let options = soul2d_core::export::ImageExportOptions::from_request(call)?;
                                    options.validate()?;
                                    path.with_extension(options.format.extension())
                                }
                                _ => path.to_owned(),
                            };
                            ApprovalTarget::Output(soul2d_core::normalized_export_target(raw, &named,
                                approval_document.as_ref().and_then(|document| document.path.as_deref()), op)?)
                        }
                        Some("texture.export") => {
                            let raw = call["directory"].as_str().ok_or("texture.export needs a directory")?;
                            let path = std::fs::canonicalize(raw)
                                .map_err(|error| format!("could not resolve directory: {error}"))?;
                            if !path.is_dir() {
                                return Err("texture.export needs a directory".into());
                            }
                            ApprovalTarget::Output(path)
                        }
                        _ => ApprovalTarget::Settings(settings_path.clone()),
                    })
                })();
                return approval.guard(call, target, approval_document.clone());
            }
            Ok(())
        }, &mut |controller, call| {
            if call["op"] == "editor.quit" {
                if (!reply_capable && acp_quit.is_none()) || message.get("id").is_none_or(Value::is_null) {
                    return Err("Quit requires an identified external request with a reply writer".into());
                }
                if matches!(self.remote_quit, RemoteQuit::Waiting { .. }) {
                    return Err("Quit already pending; read editor state".into());
                }
                let origin = if let Some(target) = acp_quit.as_ref() {
                    if !matches!(&*self.remote_quit, RemoteQuit::Reviewing { target: reviewed, .. } if reviewed == target) {
                        return Err("The original lifecycle review is no longer valid".into());
                    }
                    if let Some(reason) = self.quit_work_refusal(controller) { return Err(reason); }
                    QuitOrigin::Acp { target: target.clone(), admitted_at: Instant::now(), turn_deadline: Instant::now() + ACP_QUIT_TURN_TIMEOUT }
                } else {
                    if self.remote_quit.active() { return Err("Quit already pending; read editor state".into()); }
                    if let Some(reason) = self.quit_refusal(controller) { return Err(reason); }
                    QuitOrigin::External
                };
                let attempt = if matches!(origin, QuitOrigin::Acp { .. }) { self.remote_quit.attempt() }
                    else { self.remote_quit.attempt().checked_add(1).ok_or("Quit identity exhausted")? };
                let (sender, receipt) = sync_channel(1);
                *self.remote_quit = RemoteQuit::Waiting { attempt, revision: controller.snapshot()["revision"].clone(),
                    path: controller.project_path().map(Path::to_owned), receipt, deadline: Instant::now() + QUIT_REPLY_TIMEOUT, origin, delivered: false };
                let accepted = json!({"quit":{"state":"accepted","attempt":attempt,
                    "policy": if acp_quit.is_some() { "close_after_reply_successful_turn_owned_release_and_final_safety_check" }
                        else { "close_after_reply_flush_and_final_safety_check" }}});
                quit_receipt = Some((sender, accepted.clone()));
                return Ok(accepted);
            }
            self.handle(controller, call)
        });
        if let McpOrigin::Agent(approval) = &origin {
            if let Some(target) = approval.quit_review() {
                if !self.remote_quit.active() && !matches!(&*self.remote_quit,
                    RemoteQuit::Cancelled { invalid: Some(invalid), .. } if invalid == &target) {
                    if let Some(attempt) = self.remote_quit.attempt().checked_add(1) {
                        *self.remote_quit = RemoteQuit::Reviewing { attempt, target,
                            revision: controller.snapshot()["revision"].clone(), path: controller.project_path().map(Path::to_owned) };
                    }
                }
            }
        }
        if attachment_request && response.as_ref().is_none_or(|reply| reply["result"]["isError"] == false) {
            *self.can3_part_choices = Can3PartChoices::default();
        }
        if controller.take_document_replaced() {
            // What the menu entries do after a replacement: nothing may still describe the old document (the
            // armed parameter id among it; the new document may use that id for another parameter). The toolbar
            // path is where Save As writes, so a stale one would put the new document over the old project.
            self.after_document_replaced();
            *self.file_path = controller.project_path().map(|path| path.display().to_string()).unwrap_or_default();
        }
        self.viewport.reconcile_views(controller.snapshot());
        self.parameters.reconcile(controller.snapshot(), self.animation_name, self.seek_frame);
        match quit_receipt {
            Some((receipt, accepted)) => {
                if response.as_ref().is_some_and(|reply| reply["result"]["isError"] == false
                    && reply["result"]["structuredContent"] == accepted) {
                    if let RemoteQuit::Waiting { origin: QuitOrigin::Acp { admitted_at, turn_deadline, .. }, deadline, .. } = self.remote_quit {
                        *admitted_at = Instant::now();
                        *turn_deadline = *admitted_at + ACP_QUIT_TURN_TIMEOUT;
                        *deadline = *admitted_at + QUIT_REPLY_TIMEOUT;
                    }
                    RpcReply::tracked(message, response, receipt)
                } else {
                    self.remote_quit.cancel("accepted_reply_missing");
                    RpcReply::plain(response)
                }
            }
            None => RpcReply::plain(response),
        }
    }

    fn quit_refusal(&self, controller: &EditorController) -> Option<String> {
        self.quit_work_refusal(controller).or_else(|| self.agent_owner.is_some().then(|| "Quit refused: stop the ACP session first".into()))
    }

    fn quit_work_refusal(&self, controller: &EditorController) -> Option<String> {
        let reason = if *self.closing { "The editor is closing" }
        else if self.dialog_waits() || self.windows.quit_pending(&self.tools.store) { DIALOG_PENDING_MESSAGE }
        else if !controller.can_close() { "Quit refused: save the document and apply or cancel its drafts first" }
        else if self.mesh_tools.editing() || self.depth_tools.editing() || self.tool_edits()
            || self.viewport.editing() || self.parameters.values.editing_trs() {
            "Quit refused: finish the active mesh or depth editor first"
        } else if self.retained_document_edits(controller.snapshot()) {
            "Quit refused: unapplied animation, parameter, object, physics or merge edits remain"
        }
        else if controller.snapshot()["partSplit"]["open"] == true && controller.snapshot()["partSplit"]["applied"] != true {
            "Quit refused: an unapplied split plan remains"
        } else if self.psd_depth_open { "Quit refused: finish the depth import editor first" }
        else if controller.playing() || controller.has_background_work() || self.tools.video_job.is_some()
            || self.tools.probe["state"] == "running" || controller.snapshot()["deformPending"] == true {
            "Quit refused: stop playback or wait for active work to finish"
        } else { return None };
        Some(reason.to_owned())
    }

    fn retained_document_edits(&self, snapshot: &Value) -> bool {
        self.animation_draft.has_draft() || self.timeline_value_draft.is_some()
            || self.timeline_tension_draft.is_some() || self.timeline_weight_draft.is_some() || self.form_time_draft.is_some()
            || self.sequence_panel.has_draft() || self.parameters.has_draft()
            || self.objects.has_draft() || self.physics_groups.has_draft() || self.windows.has_document_draft()
            || self.tools.merge.planned.is_some() || !self.tools.merge.rows.is_empty()
            || self.viewport.editing() || self.parameters.values.editing_trs()
            || self.marker_at.as_ref().is_some_and(|(name, frame)| {
                let markers = timeline_markers(snapshot, name);
                *self.marker_to != *frame || self.marker_text.as_str() != markers.iter()
                    .find(|marker| marker.frame == *frame).map_or("", |marker| marker.text.as_str())
            })
    }

    fn replacement_refusal(&self, snapshot: &Value) -> Option<String> {
        self.refuse_under_a_dialog().err()
            .or_else(|| self.windows.quit_pending(&self.tools.store).then(|| DIALOG_PENDING_MESSAGE.to_owned()))
            .or_else(|| self.retained_document_edits(snapshot).then(|| DRAFT_BLOCKS_MESSAGE.to_owned()))
    }

    /// Runs one `editor.*` request (arguments already checked for shape by `mcp.rs`) and answers with the
    /// state after it.
    fn handle(&mut self, controller: &mut EditorController, call: &Value) -> Result<Value, String> {
        let ids = |value: &Value| value.as_array().into_iter().flatten().filter_map(Value::as_u64).collect::<Vec<u64>>();
        match call["op"].as_str().unwrap_or_default() {
            "editor.state" => {}
            "editor.native_parameters.set" => {
                if !matches!(controller.snapshot()["documentFormat"].as_str(), Some("live2d.cmo3" | "live2d.can3")) {
                    return Err("the native parameter panel is available only for CMO3 and CAN3 documents".into());
                }
                *self.parameter_filter = call["filter"].as_str().unwrap().to_owned();
            }
            "editor.parameters.set" => {
                if controller.snapshot()["documentFormat"] != "inx" {
                    return Err("the Parameters panel is available only for INX documents".into());
                }
                let name = call["animation"].as_str().unwrap_or(self.animation_name).to_owned();
                if call.get("animation").is_some() && !controller.snapshot()["model"]["animations"][&name].is_object() {
                    return Err(format!("animation {name:?} was not found"));
                }
                let bookmark = match call.get("bookmark") {
                    Some(value) if value.is_null() => Some(None),
                    Some(selector) => Some(Some(parameter_bookmark(controller, &name, selector)?)),
                    None => None,
                };
                if name != *self.animation_name {
                    controller.pause();
                    *self.animation_name = name;
                    *self.seek_frame = 0.0;
                    self.parameters.bookmark = None;
                }
                if let Some(filter) = call["filter"].as_str() {
                    self.parameters.filter = filter.to_owned();
                }
                if let Some(bookmark) = bookmark {
                    self.parameters.bookmark = bookmark;
                }
            }
            "editor.selection.set" => {
                self.refuse_over_unapplied_edits()?;
                // Everything is checked before anything changes, so a refused call leaves the selection as it was.
                let nodes = call.get("nodes").map(ids);
                let bindings = match call["bindings"].as_array() {
                    Some(list) => {
                        let snapshot = controller.snapshot();
                        let param_list = &snapshot["model"]["param"];
                        let armed = self.parameters.armed.ok_or("bindings need an armed parameter (editor_armed_set)")?;
                        let parameter =
                            find_plain(param_list, armed).ok_or_else(|| format!("parameter {armed} was not found"))?;
                        let (key, _) = closest_keypoint(parameter, value_pair(snapshot, armed))
                            .ok_or("the armed parameter has no keypoint")?;
                        let rows = binding_rows(parameter, key, &snapshot["model"]["nodes"], param_list);
                        let mut chosen: Vec<(u32, String)> = Vec::new();
                        for binding in list {
                            let node = binding["node"].as_u64().and_then(|node| u32::try_from(node).ok())
                                .ok_or("bindings entries need an integer node")?;
                            let channel = binding["channel"].as_str().ok_or("bindings entries need a string channel")?;
                            if !rows.iter().any(|row| row.node == node && row.channel == channel) {
                                return Err(format!("node {node} has no {channel} binding on parameter {armed}"));
                            }
                            if !chosen.iter().any(|(n, c)| *n == node && c == channel) {
                                chosen.push((node, channel.to_owned()));
                            }
                        }
                        Some(chosen)
                    }
                    None => None,
                };
                let vertices = match call["vertices"].as_array() {
                    Some(list) => {
                        let indices = list.iter()
                            .map(|index| index.as_u64().map(|index| index as usize).ok_or("vertices entries must be integers"))
                            .collect::<Result<Vec<_>, _>>()?;
                        // The edit follows the primary node only at the next frame, so the indices would address the
                        // old mesh and be dropped when the target changes.
                        if nodes.as_ref().is_some_and(|nodes| nodes.first().copied() != self.mesh_tools.target_node().map(u64::from)) {
                            return Err("vertices address the active mesh edit's node; select the node first, then its \
                                        vertices in a later call".into());
                        }
                        Some(self.mesh_tools.checked_selection(&indices)?)
                    }
                    None => None,
                };
                if let Some(nodes) = nodes {
                    controller.select_nodes(&nodes)?;
                }
                if let Some(bindings) = bindings {
                    self.parameters.selected_bindings = bindings;
                }
                if let Some(vertices) = vertices {
                    self.mesh_tools.select(&vertices)?;
                }
            }
            "editor.armed.set" => {
                self.refuse_over_unapplied_edits()?;
                let id = call["parameter"].as_u64().and_then(|id| u32::try_from(id).ok());
                if let Some(id) = id.filter(|id| find_plain(&controller.snapshot()["model"]["param"], *id).is_none()) {
                    return Err(format!("parameter {id} was not found"));
                }
                // Like the node tree's "Arm": the value stays where it is, so nothing in the session moves.
                self.parameters.armed = id;
            }
            "editor.camera.set" => {
                use crate::editor_viewport::{ZOOM_MAX, ZOOM_MIN};
                let mut camera = self.viewport.camera;
                if let Some(zoom) = call["zoom"].as_f64() {
                    if !(ZOOM_MIN..=ZOOM_MAX).contains(&zoom) {
                        return Err(format!("zoom must be within {ZOOM_MIN} and {ZOOM_MAX}"));
                    }
                    camera.zoom = zoom;
                }
                if let Some(centre) = pair_of(&call["centre"]) {
                    camera.centre = centre;
                }
                self.viewport.set_view(camera);
                if let Some(mirror) = call["mirror"].as_bool() {
                    self.viewport.camera.mirror = mirror;
                }
                if call.get("centre").is_some() || call.get("zoom").is_some() {
                    self.keep_camera(controller);
                }
            }
            "editor.camera.sync" => {
                if !matches!(controller.snapshot()["documentFormat"].as_str(), Some("inx" | "live2d.cmo3")) {
                    return Err("view camera synchronization is available only for INX and CMO3 documents".into());
                }
                self.viewport.sync_cameras(controller.snapshot());
                self.keep_camera(controller);
            }
            "editor.camera.fit" => {
                if let Some(nodes) = call.get("nodes") {
                    let ids = ids(nodes);
                    // Owned, because the scene reads below borrow the controller.
                    let tree = controller.snapshot()["model"]["nodes"].clone();
                    if let Some(missing) = ids.iter().find(|id| find_node(&tree, **id).is_none()) {
                        return Err(format!("node {missing} was not found"));
                    }
                    self.viewport.focus_nodes(&mut |request| controller.core_request(request), &tree, &ids)?;
                } else {
                    let response = controller.core_request(&json!({"op": "bounds"}));
                    if response["succeeded"] != true {
                        return Err(response["message"].as_str().unwrap_or("the model bounds could not be read").to_owned());
                    }
                    let bounds: Option<Vec<f64>> =
                        response["result"]["bounds"].as_array().and_then(|list| list.iter().map(Value::as_f64).collect());
                    let camera = bounds
                        .filter(|bounds| bounds.len() == 4)
                        .and_then(|b| crate::editor_viewport::fit_camera([b[0], b[1], b[2], b[3]], self.viewport.size()));
                    self.viewport.set_view(camera.ok_or("the model has nothing to fit")?);
                }
                self.keep_camera(controller);
            }
            "editor.tool.set" => self.set_tool(call["tool"].as_str().unwrap_or_default())?,
            "editor.recovery.list" => return Ok(json!({"snapshots": self.recovery_entries()?})),
            "editor.recovery.keep" => self.recovery_offer.clear(),
            "editor.recovery.restore" => {
                self.refuse_under_a_dialog()?;
                self.restore_recovery(controller, call["id"].as_str().unwrap_or_default())?;
            }
            "editor.settings.get" => return Ok(self.settings()),
            "editor.settings.set" => {
                return self.set_setting(controller, call["key"].as_str().unwrap_or_default(), &call["value"]);
            }
            "editor.shortcut.set" => return self.set_shortcut(call),
            "editor.guides.set" => {
                self.viewport.guides.apply(call);
                if let Some(open) = call["open"].as_bool() {
                    self.viewport.guides_open = open;
                }
            }
            "editor.physics.preview.set" => {
                let enabled = call["enabled"].as_bool().unwrap();
                if enabled && controller.snapshot()["documentFormat"] != "inx" {
                    return Err("physics preview is available only for INX documents".into());
                }
                self.viewport.physics = enabled;
            }
            "editor.solo.set" => {
                let solo = &mut self.viewport.solo;
                solo.show = call["show"].as_bool().unwrap_or(solo.show);
                if let Some(colour) = call["colour"].as_array() {
                    for (channel, value) in solo.colour.iter_mut().zip(colour) {
                        *channel = value.as_u64().and_then(|value| u8::try_from(value).ok()).unwrap_or(*channel);
                    }
                }
            }
            "editor.playback.set" => {
                self.lightweight.on = call["lightweight"].as_bool().unwrap_or(self.lightweight.on);
                *self.snap_to_framerate = call["snapToFramerate"].as_bool().unwrap_or(*self.snap_to_framerate);
            }
            "editor.timeline.zoom.set" => {
                timeline_zoom_set(self.timeline_zoom, call["zoom"].as_f64().unwrap() as f32);
            }
            "editor.onion.set" => {
                self.viewport.set_onion(call["onion"].as_bool().unwrap_or(self.viewport.onion));
                self.viewport.trajectories = call["trajectories"].as_bool().unwrap_or(self.viewport.trajectories);
            }
            "editor.panel.set" => {
                let (_, key) = crate::editor_windows::PANELS.iter()
                    .find(|(label, _)| label.to_lowercase() == call["panel"].as_str().unwrap())
                    .ok_or("panel must be outline or timeline")?;
                self.tools.store.set(key, call["visible"].as_bool().unwrap())?;
                if let Some(path) = &self.tools.store_path {
                    self.tools.store.save(path).map_err(|_| {
                        "panel visibility changed for this session, but the settings file could not be written".to_owned()
                    })?;
                }
            }
            "editor.layout.reset" => {
                let mut stored_visibility = false;
                for (_, key) in crate::editor_windows::PANELS {
                    if self.tools.store.contains(key) {
                        self.tools.store.set(key, true)?;
                        stored_visibility = true;
                    }
                }
                reset_layout(self.ctx);
                if let Some(path) = self.tools.store_path.as_deref().filter(|_| stored_visibility) {
                    self.tools.store.save(path).map_err(|_| {
                        "layout reset for this session, but the settings file could not be written".to_owned()
                    })?;
                }
            }
            "editor.workspace.save" => {
                let name = call["name"].as_str().unwrap_or_default();
                let mut saved = crate::editor_windows::saved_workspaces(&self.tools.store)?;
                if !saved.contains_key(name) && saved.len() >= MAX_WORKSPACES {
                    return Err(format!("at most {MAX_WORKSPACES} workspaces; delete one first"));
                }
                saved.insert(name.to_owned(), capture_workspace(self.ctx, &self.tools.store).to_string());
                self.store_workspaces(saved)?;
            }
            "editor.workspace.apply" => {
                let name = call["name"].as_str().unwrap_or_default();
                let saved = crate::editor_windows::saved_workspaces(&self.tools.store)?;
                let workspace = saved.get(name).ok_or_else(|| format!("workspace {name:?} was not found"))?;
                let workspace = serde_json::from_str::<Value>(workspace)
                    .ok()
                    .filter(Value::is_object)
                    .ok_or_else(|| format!("workspace {name:?} in the settings file is not a layout"))?;
                apply_workspace(self.ctx, &mut self.tools.store, &workspace)?;
                self.save_store()?;
            }
            "editor.workspace.delete" => {
                let name = call["name"].as_str().unwrap_or_default();
                let mut saved = crate::editor_windows::saved_workspaces(&self.tools.store)?;
                saved.remove(name).ok_or_else(|| format!("workspace {name:?} was not found"))?;
                self.store_workspaces(saved)?;
            }
            "editor.about.set" => self.windows.set_about_open(call["open"].as_bool().unwrap()),
            "editor.welcome.set" => self.windows.set_welcome_open(call["open"].as_bool().unwrap(), &self.tools.store),
            "editor.command.browser.set" => self.windows.set_command_browser_open(call["open"].as_bool().unwrap()),
            "editor.texture.viewer.set" => self.windows.set_texture_viewer_open(call["open"].as_bool().unwrap()),
            "editor.address.dialog" => {
                let operation = soul2d_core::window_shell::AddressDialogOperation::from_fields(
                    call["action"].as_str().unwrap_or_default(), call["target"].as_str(),
                )?;
                self.windows.apply_address_dialog(operation, self.tools.store_path.as_deref(), self.ctx, &tr)?;
            }
            "editor.viewport.set" => {
                if let Some(by_size) = call["partSortBySize"].as_bool() {
                    if controller.snapshot()["documentFormat"] != "inx" {
                        return Err("Part menu sorting is available only for INX documents".into());
                    }
                    self.viewport.menu_by_size = by_size;
                }
                for (key, field) in [
                    ("vertices", &mut self.viewport.show_vertices),
                    ("bounds", &mut self.viewport.show_bounds),
                    ("orientation", &mut self.viewport.show_orientation),
                ] {
                    if let Some(value) = call[key].as_bool() {
                        *field = value;
                    }
                }
                if let Some(background) = call["background"].as_array() {
                    self.viewport.background = std::array::from_fn(|i| background[i].as_u64().unwrap() as u8);
                }
            }
            "editor.grid.set" => {
                use crate::editor_viewport::{GRID_SPACING_MAX, GRID_SPACING_MIN};
                let mut grid = self.viewport.grid;
                if let Some(spacing) = call["spacing"].as_f64() {
                    if !(GRID_SPACING_MIN..=GRID_SPACING_MAX).contains(&spacing) {
                        return Err(format!("spacing must be within {GRID_SPACING_MIN} and {GRID_SPACING_MAX}"));
                    }
                    grid.spacing = spacing;
                }
                if let Some(show) = call["show"].as_bool() {
                    grid.show = show;
                }
                if let Some(colour) = call["colour"].as_array() {
                    for (channel, value) in grid.colour.iter_mut().zip(colour) {
                        *channel = value.as_u64().and_then(|value| u8::try_from(value).ok()).unwrap_or(*channel);
                    }
                }
                self.viewport.grid = grid;
            }
            _ => return Err("unknown editor request".into()),
        }
        Ok(controller.editor_state(self.state(controller)))
    }

    /// The unsaved-changes dialog or the restore prompt waits for an answer, and the recovery offer hides
    /// behind either (`draw_recovery_offer`). What the user answers there decides about the document and the
    /// snapshots: "Don't save" discards the document the dialog was raised for, so a remote caller must not
    /// put another one in its place meanwhile. Once the user has answered Save or Don't
    /// save to the close dialog, `closing` ends the session the same way: a snapshot adopted now is released
    /// and deleted on exit.
    fn refuse_under_a_dialog(&self) -> Result<(), String> {
        if self.dialog_waits() {
            Err(DIALOG_PENDING_MESSAGE.to_owned())
        } else if *self.closing {
            Err(CLOSING_MESSAGE.to_owned())
        } else {
            Ok(())
        }
    }

    fn dialog_waits(&self) -> bool {
        self.unsaved.is_some() || self.tools.prompt.is_some() || self.can3_delete.is_some()
    }

    /// What every document replacement resets in the window. It releases this session's recovery snapshot,
    /// so a restored snapshot is adopted after it, not before.
    fn after_document_replaced(&mut self) {
        self.remote_quit.cancel("document_replaced");
        self.notice.clear();
        self.viewport.forget_views();
        self.parameters.armed = None;
        self.parameters.bookmark = None;
        self.parameters.edit = None;
        self.parameters.split = None;
        self.parameters.values = Default::default();
        *self.animation_draft = AnimationDraft::default();
        *self.timeline_value_draft = None;
        *self.timeline_tension_draft = None;
        *self.timeline_weight_draft = None;
        *self.form_time_draft = None;
        *self.timeline_selection = None;
        *self.form_read = Value::Null;
        *self.controller_places = (Value::Null, Value::Null);
        *self.form_places = (Value::Null, Vec::new());
        *self.sequence_panel = Default::default();
        *self.marker_at = None;
        self.marker_text.clear();
        *self.marker_to = 0;
        self.tools.merge.clear_plan();
        self.windows.forget_document();
        *self.preview_dirty = true;
        self.native_scene_guid.clear();
        *self.can3_scene_draft = Can3SceneDraft::default();
        *self.can3_delete = None;
        *self.can3_track_draft = None;
        *self.can3_curve_draft = None;
        *self.can3_key_draft = None;
        self.can3_curve_track_guid.clear();
        *self.can3_part_choices = Can3PartChoices::default();
        self.native_resource_guid.clear();
        self.native_asset_path.clear();
        self.motion3.reset();
        self.part_split_review.reset();
        self.forms.reset();
        self.objects.reset();
        self.physics_groups.reset();
        self.expression_name.clear();
        let now = clock_now(self.tools.started);
        if let Some(recovery) = self.tools.recovery.as_mut() {
            recovery.release(now);
        }
        *self.preview_bounds = None;
        self.preview_warnings.clear();
    }

    /// The snapshots earlier sessions left, newest first. This session's own snapshot is not one of them.
    fn recovery_snapshots(&self) -> Result<Vec<PathBuf>, String> {
        recovery_snapshots(self.tools.config_dir.as_deref(), self.tools.recovery.as_ref().and_then(autosave::Recovery::current))
    }

    /// What the offer window shows for each snapshot is its file name, which is also its id.
    fn recovery_entries(&self) -> Result<Vec<Value>, String> {
        let entry = |path: &PathBuf| {
            let name = path.file_name().and_then(|name| name.to_str()).unwrap_or_default();
            json!({"id": name, "format": path.extension().and_then(|ext| ext.to_str())})
        };
        Ok(self.recovery_snapshots()?.iter().map(entry).collect())
    }

    /// The Restore button: open the snapshot as an untitled, modified document, then take it over as this
    /// session's snapshot. The document gate is the one `open` has, not the window's dialog.
    fn restore_recovery(&mut self, controller: &mut EditorController, id: &str) -> Result<(), String> {
        if let Some(reason) = self.replacement_refusal(controller.snapshot()) { return Err(reason); }
        let snapshots = self.recovery_snapshots()?;
        let path = autosave::recovery_named(&snapshots, id)?.to_path_buf();
        // The session names the file in some of its errors; the caller only knows the id.
        let named = path.to_string_lossy().into_owned();
        controller
            .replace_document(&autosave::recovery_open_request(&path)?)
            .map_err(|message| message.replace(&named, id))?;
        self.after_document_replaced();
        *self.file_path = String::new();
        adopt_recovery(self.recovery_offer, self.tools.recovery.as_mut(), path);
        Ok(())
    }

    /// Listed editor preferences and the shortcut bindings of the Settings window's Shortcuts pane.
    fn settings(&mut self) -> Value {
        let tools = &mut *self.tools;
        json!({
            "settings": crate::editor_windows::settings_list(&mut tools.store, &tools.lang, &tools.locales),
            "shortcuts": crate::editor_windows::shortcut_list(&tools.store, &tools.shortcuts),
        })
    }

    /// Writes one setting and follows it up as `apply_window_request` does for the Settings window.
    fn set_setting(&mut self, controller: &mut EditorController, key: &str, value: &Value) -> Result<Value, String> {
        use crate::editor_windows::Request;
        let tools = &mut *self.tools;
        let request = crate::editor_windows::set_setting(&mut tools.store, &tools.locales, key, value)?;
        // The change is applied before the file is written, so a failed write is not a refusal. The error
        // of the write names the settings file; the caller gets no path.
        let not_saved = |_| format!("{key} changed for this session, but the settings file could not be written");
        if let Some(Request::SetLanguage(code)) = request {
            // Swaps the catalogue, then stores and saves `lang` itself.
            tools.set_language(&code).map_err(not_saved)?;
        } else {
            match request {
                Some(Request::ImportDefaultsChanged) => tools.import_defaults_changed(),
                Some(Request::Core(request)) => {
                    controller.core_request(&request);
                }
                _ => {}
            }
            if let Some(path) = &tools.store_path {
                tools.store.save(path).map_err(not_saved)?;
            }
        }
        let setting = crate::editor_windows::setting_listed(&mut tools.store, &tools.lang, &tools.locales, key);
        Ok(json!({"setting": setting, "saved": tools.store_path.is_some()}))
    }

    /// Rebinds or unbinds one command's shortcut as the Shortcuts pane does, then saves the settings file. The
    /// binding is applied before the file is written, so a failed write is not a refusal.
    fn set_shortcut(&mut self, call: &Value) -> Result<Value, String> {
        let command = call["command"].as_str().unwrap_or_default();
        let chord = crate::editor_windows::validate_shortcut(command, &call["shortcut"])?;
        let tools = &mut *self.tools;
        let displaced = crate::editor_windows::set_shortcut(&mut tools.shortcuts, command, chord, call["repeat"].as_bool());
        let not_saved =
            |_| format!("the shortcut of {command} changed for this session, but the settings file could not be written");
        tools.shortcuts.save_to(&mut tools.store, soul2d_core::settings::Platform::current()).map_err(not_saved)?;
        if let Some(path) = &tools.store_path {
            tools.store.save(path).map_err(not_saved)?;
        }
        let binding = crate::editor_windows::shortcut_listed(&tools.store, &tools.shortcuts, command);
        Ok(json!({"binding": binding, "displaced": displaced, "saved": tools.store_path.is_some()}))
    }

    fn store_workspaces(&mut self, saved: std::collections::BTreeMap<String, String>) -> Result<(), String> {
        self.tools.store.set(crate::editor_windows::KEY_WORKSPACES, saved)?;
        self.save_store()
    }

    /// The settings file follows each workspace change. The change holds for this run when the file cannot be
    /// written, as a menu setting does.
    fn save_store(&self) -> Result<(), String> {
        if let Some(path) = self.tools.store_path.as_deref() {
            self.tools.store.save(path).map_err(|_| {
                "workspace changed for this session, but the settings file could not be written".to_owned()
            })?;
        }
        Ok(())
    }

    /// The caller placed the camera, so a pending fit to the scene bounds (new document, "Fit preview") must
    /// not move it again at the next render.
    fn keep_camera(&mut self, controller: &EditorController) {
        self.preview_bounds.get_or_insert_with(|| (controller.snapshot()["revision"].as_u64().unwrap_or(0), Value::Null));
    }

    /// The mesh or depth tool holds edits that Apply has not committed.
    fn tool_edits(&self) -> bool {
        self.mesh_tools.can_undo_edit() || self.depth_tools.can_undo_edit()
    }

    /// A new selection or armed parameter makes the tools drop their unapplied edits and the binding value
    /// editor reload over its unapplied list. A click in the window is the user's own choice; a remote caller
    /// is refused instead.
    fn refuse_over_unapplied_edits(&self) -> Result<(), String> {
        if self.tool_edits() {
            Err(TOOL_EDITS_MESSAGE.to_owned())
        } else if self.parameters.values.has_draft() {
            Err(VALUE_DRAFT_MESSAGE.to_owned())
        } else {
            Ok(())
        }
    }

    fn set_tool(&mut self, name: &str) -> Result<(), String> {
        if self.depth_tools.captures() {
            if let Some(tool) = crate::editor_depth::Tool::ALL.into_iter().find(|tool| depth_tool_id(*tool) == name) {
                self.depth_tools.set_tool(tool);
                return Ok(());
            }
        } else if let Some(tool) = self.mesh_tools.tool_offered().into_iter().find(|tool| mesh_tool_id(*tool) == name) {
            self.mesh_tools.set_tool(tool);
            return Ok(());
        }
        let state = self.tool_state();
        Err(format!("tool {name:?} is not offered in {} mode; offered: {}", state["mode"], state["offered"]))
    }

    /// Edit mode and tool as of the last drawn frame: the frame derives the mode from the selection and the
    /// armed parameter.
    fn tool_state(&self) -> Value {
        use crate::editor_mesh_tools::Mode;
        if self.depth_tools.captures() {
            let offered = crate::editor_depth::Tool::ALL.map(depth_tool_id);
            return json!({"mode": "depth", "tool": depth_tool_id(self.depth_tools.tool), "offered": offered});
        }
        let Some(mode) = self.mesh_tools.mode() else {
            return json!({"mode": "model", "tool": null, "offered": []});
        };
        let offered: Vec<&str> = self.mesh_tools.tool_offered().into_iter().map(mesh_tool_id).collect();
        json!({
            "mode": match mode { Mode::Vertex => "vertex", Mode::Deform => "deform" },
            "tool": mesh_tool_id(self.mesh_tools.tool),
            "offered": offered,
        })
    }

    fn recovery_offer_draw_eligible(&self) -> bool {
        !self.recovery_offer.is_empty() && self.unsaved.is_none() && self.tools.prompt.is_none()
    }

    /// The fields of the editor state resource that only the window holds.
    fn state(&mut self, controller: &EditorController) -> Value {
        let snapshot = controller.snapshot();
        self.viewport.reconcile_views(snapshot);
        self.parameters.reconcile(snapshot, self.animation_name, self.seek_frame);
        let armed = self.parameters.armed.and_then(|id| {
            let parameter = find_plain(&snapshot["model"]["param"], id)?;
            let mut armed = json!({"parameter": id});
            if let Some((key, value)) = closest_keypoint(parameter, value_pair(snapshot, id)) {
                armed["key"] = json!(key);
                armed["keyValue"] = json!(value);
            }
            Some(armed)
        });
        let camera = self.viewport.camera;
        let grid = self.viewport.grid;
        let panels: serde_json::Map<String, Value> = crate::editor_windows::PANELS
            .iter()
            .map(|(label, key)| (label.to_lowercase(), json!(crate::editor_windows::panel_visible(&self.tools.store, key))))
            .collect();
        json!({
            "quit": self.remote_quit.state(),
            "codingAgent": {
                "enabled": self.agent_state.enabled,
                "has_client": self.agent_state.has_client,
                "closed": self.agent_state.closed,
                "ready": self.agent_state.ready,
                "turn_active": self.agent_state.turn_active,
                "cancelling": self.agent_state.cancelling,
                "awaiting_permission": self.agent_state.awaiting_permission,
            },
            "selection": {
                "nodes": controller.selected_nodes(),
                "bindings": self.parameters.selected_bindings.iter()
                    .map(|(node, channel)| json!({"node": node, "channel": channel})).collect::<Vec<_>>(),
                "vertices": self.mesh_tools.target_node()
                    .map(|node| json!({"node": node, "indices": self.mesh_tools.selection()})),
                "timeline": self.timeline_selection.as_ref().map(|selection| json!({
                    "animation": selection.animation, "parameter": selection.parameter,
                    "axis": selection.axis, "frame": selection.frame})),
            },
            "armed": armed,
            "tool": self.tool_state(),
            "camera": {"centre": camera.centre, "zoom": camera.zoom, "mirror": camera.mirror, "viewSize": self.viewport.size()},
            "viewCameras": self.viewport.view_cameras(snapshot),
            "nativeParameterPanel": matches!(snapshot["documentFormat"].as_str(), Some("live2d.cmo3" | "live2d.can3"))
                .then(|| json!({"filter":self.parameter_filter})),
            "parameterPanel": (snapshot["documentFormat"] == "inx").then(|| json!({
                "filter": self.parameters.filter,
                "animation": snapshot["model"]["animations"][&*self.animation_name].is_object().then_some(&*self.animation_name),
                "bookmark": self.parameters.bookmark,
            })),
            "viewport": {"vertices": self.viewport.show_vertices, "bounds": self.viewport.show_bounds,
                "orientation": self.viewport.show_orientation, "background": self.viewport.background,
                "partSort": (snapshot["documentFormat"] == "inx").then_some(
                    if self.viewport.menu_by_size { "size_sort" } else { "z_sort" })},
            "grid": {"show": grid.show, "spacing": grid.spacing, "colour": grid.colour},
            "guides": self.viewport.guides.state(),
            "solo": {"show": self.viewport.solo.show, "colour": self.viewport.solo.colour},
            "animationOverlays": {"onion": self.viewport.onion, "trajectories": self.viewport.trajectories},
            "playback": {"lightweight": self.lightweight.on, "snapToFramerate": *self.snap_to_framerate},
            "timeline": {"zoom": f64::from(*self.timeline_zoom)},
            "panels": panels,
            "windows": {"nerdStats": crate::editor_windows::nerd_stats(&self.tools.store),
                "guideSettings": self.viewport.guides_open, "addressDialog": self.windows.address_dialog_state(),
                "about": self.windows.about_open(),
                "welcome": self.windows.welcome_open(),
                "commandBrowser": self.windows.command_browser_open(),
                "textureViewer": self.windows.texture_viewer_open(),
                "recoveryOffer": {"pending": !self.recovery_offer.is_empty(),
                    "drawEligible": self.recovery_offer_draw_eligible()},
                // The dialogs that wait for the user's answer; while one is open, document-replacing calls are
                // refused (`dialog_waits`). Paths stay out: the caller learns whether, not where.
                "unsaved": self.unsaved.as_ref().map(|state| json!({
                    "action": pending_action_kind(&state.action),
                    "hasPath": controller.project_path().is_some(),
                    "saveFailed": !state.dialog.message.is_empty()})),
                "restorePrompt": self.tools.prompt.as_ref().map(|prompt| json!({"backups": prompt.backups})),
                "can3Delete": self.can3_delete.as_ref().map(|confirmation| json!({"kind": match confirmation {
                    Can3DeleteConfirmation::Scene(_) => "scene",
                    Can3DeleteConfirmation::Track(_) => "track",
                    Can3DeleteConfirmation::Curve(_) => "curve",
                }}))},
            "physicsPreview": {"enabled": self.viewport.physics, "available": snapshot["documentFormat"] == "inx"},
            "workspaces": crate::editor_windows::workspace_names(&self.tools.store),
            "drafts": {"panels": controller.draft_dirty() || controller.panel_drafts, "tools": self.tool_edits()},
        })
    }
}

/// A restored crash snapshot leaves the offer and becomes this session's snapshot, so the next one replaces
/// it and a save deletes it.
fn adopt_recovery(offer: &mut Vec<PathBuf>, recovery: Option<&mut autosave::Recovery>, path: PathBuf) {
    offer.retain(|offered| *offered != path);
    if autosave::is_recovery_path(&path) {
        if let Some(recovery) = recovery {
            recovery.adopt(path);
        }
    }
}

pub struct EditorApp {
    remote_quit: RemoteQuit,
    #[cfg(test)]
    hold_quit_receipt_for_test: bool,
    #[cfg(test)]
    after_quit_release_for_test: Option<fn(&mut EditorApp)>,
    controller: EditorController,
    host_rx: Option<Receiver<HostMessage>>,
    stdin_closed: bool,
    close_blocked: bool,
    /// The user confirmed closing (Save, Don't save, or the setting): the next close request passes.
    closing: bool,
    close_sent: bool,
    /// The unsaved-changes dialog and what it will do once answered.
    unsaved: Option<UnsavedState>,
    /// "Don't save" was chosen: the document replacement under way may discard unsaved changes.
    discarding: bool,
    window: WindowGeometry,
    last_title: String,
    mcp_server: Option<McpServer>,
    mcp_error: Option<String>,
    motion3: crate::editor_motion3::Motion3Panel,
    part_split_review: crate::editor_part_split::PartSplitReview,
    forms: crate::editor_live2d_forms::FormEditor,
    objects: crate::editor_live2d_objects::ObjectEditor,
    physics_groups: crate::editor_physics_groups::PhysicsGroups,
    /// Snapshots an earlier session left for untitled documents, offered once at startup.
    recovery_offer: Vec<PathBuf>,
    file_path: String,
    draft_name: String,
    draft_value: f64,
    preview_dirty: bool,
    preview: Option<egui::TextureHandle>,
    /// The preview is an Onion Slice picture, not the plain render.
    onion_drawn: bool,
    /// Neither playback nor physics moved the pose when the preview was last asked for.
    was_still: bool,
    /// The nodes and the inactive colour of the last Solo render, `None` when the preview is not a Solo view.
    solo_rendered: Option<(Vec<u64>, [u8; 4])>,
    preview_error: Option<String>,
    notice: String,
    animation_name: String,
    new_animation_name: String,
    animation_draft: AnimationDraft,
    key_parameter: Option<u32>,
    seek_frame: f64,
    looping: bool,
    lightweight: LightweightPlayback,
    /// D `player.snapToFramerate`: playback moves in whole frames of the animation. `frame_carry` holds the time
    /// that has not made a whole frame yet.
    snap_to_framerate: bool,
    frame_carry: f64,
    last_tick: Option<Instant>,
    preview_bounds: Option<(u64, Value)>,
    native_asset_path: String,
    pose_path: String,
    native_resource_guid: String,
    native_scene_guid: String,
    can3_scene_draft: Can3SceneDraft,
    can3_delete: Option<Can3DeleteConfirmation>,
    can3_track_draft: Option<Can3TrackDraft>,
    can3_curve_draft: Option<Can3CurveDraft>,
    can3_key_draft: Option<Can3KeyDraft>,
    can3_curve_track_guid: String,
    can3_part_choices: Can3PartChoices,
    expression_path: String,
    expression_name: String,
    native_physics_path: String,
    parameter_filter: String,
    preview_warnings: Vec<String>,
    create_class: String,
    new_node_name: String,
    move_parent: Option<u64>,
    insert_class: String,
    insert_suffix: String,
    convert_class: Option<String>,
    node_options: NodeTreeOptions,
    timeline_zoom: f32,
    /// The text typed for the marker on the playhead and the frame it would move to.
    timeline_marker_text: String,
    timeline_marker_to: i64,
    /// The clip and frame those two were last filled in for.
    timeline_marker_at: Option<(String, i64)>,
    timeline_selection: Option<TimelineSelection>,
    timeline_value_draft: Option<(TimelineSelection, f64)>,
    timeline_tension_draft: Option<(TimelineSelection, f64)>,
    timeline_templates: TimelineTemplates,
    /// The weight typed for a controller in the timeline's Controllers menu, written when the field is let go.
    timeline_weight_draft: Option<(String, f64)>,
    /// The `animation.controller.read` answer the viewport draws, and the revision, parameter values, clip and frame
    /// it was read for.
    controller_places: (Value, Value),
    /// Form edits: whether dragging a vertex of the selected node in the viewport keys its form, and the Adjustment
    /// Mode it keys in.
    form_edit: bool,
    form_mode: u8,
    /// The `animation.form.read` answer the timeline's Form edits menu shows, read on each frame the menu is open.
    form_read: Value,
    /// The form frame typed for the playhead's frame in the Form edits menu, written when the field is let go.
    form_time_draft: Option<f64>,
    sequence_panel: crate::editor_sequence::SequencePanel,
    motion_sync_panel: crate::editor_motion_sync::MotionSyncPanel,
    /// The drawn vertices of the node whose form is edited, and the revision, parameter values, clip, frame and node
    /// they were read for.
    form_places: (Value, Vec<[f64; 2]>),
    parameters: ParameterPanelState,
    tools: ToolsState,
    agent: crate::editor_agent::AgentPanel,
    windows: crate::editor_windows::Windows,
    psd_depth: crate::editor_psd_depth::PsdDepthWindow,
    viewport: crate::editor_viewport::ViewportState,
    mesh_tools: crate::editor_mesh_tools::MeshTools,
    depth_tools: crate::editor_depth::DepthTools,
}

impl EditorApp {
    pub fn new(
        cc: &eframe::CreationContext<'_>,
        open: Option<String>,
        mcp: bool,
    ) -> Self {
        let app = Self::build(mcp.then(|| editor_stdio::spawn_stdin(&cc.egui_ctx)), open, app_settings::app_config_dir());
        cc.egui_ctx.set_fonts(fonts(crate::editor_windows::use_open_dyslexic(&app.tools.store)));
        app
    }

    /// The editor without a window: settings come from `config_dir`, `host_rx` carries stdin MCP messages.
    fn build(host_rx: Option<Receiver<HostMessage>>, open: Option<String>, config_dir: Result<PathBuf, String>) -> Self {
        let (tools, problems) = ToolsState::load(config_dir);
        let mut app = Self {
            remote_quit: RemoteQuit::Idle,
            #[cfg(test)]
            hold_quit_receipt_for_test: false,
            #[cfg(test)]
            after_quit_release_for_test: None,
            controller: EditorController::new(),
            host_rx,
            stdin_closed: false,
            close_blocked: false,
            closing: false,
            close_sent: false,
            unsaved: None,
            discarding: false,
            window: WindowGeometry::load(&tools.store),
            last_title: String::new(),
            mcp_server: None,
            mcp_error: None,
            motion3: crate::editor_motion3::Motion3Panel::new(),
            part_split_review: crate::editor_part_split::PartSplitReview::default(),
            forms: crate::editor_live2d_forms::FormEditor::new(),
            objects: crate::editor_live2d_objects::ObjectEditor::new(),
            physics_groups: crate::editor_physics_groups::PhysicsGroups::default(),
            recovery_offer: tools.config_dir.as_deref().and_then(|dir| autosave::list_recovery(dir).ok()).unwrap_or_default(),
            file_path: String::new(),
            draft_name: String::new(),
            draft_value: 0.0,
            preview_dirty: true,
            preview: None,
            onion_drawn: false,
            was_still: true,
            solo_rendered: None,
            preview_error: None,
            notice: String::new(),
            animation_name: String::new(),
            new_animation_name: String::new(),
            animation_draft: AnimationDraft::default(),
            key_parameter: None,
            seek_frame: 0.0,
            looping: false,
            lightweight: LightweightPlayback::default(),
            snap_to_framerate: false,
            frame_carry: 0.0,
            last_tick: None,
            preview_bounds: None,
            native_asset_path: String::new(),
            pose_path: String::new(),
            native_resource_guid: String::new(),
            native_scene_guid: String::new(),
            can3_scene_draft: Can3SceneDraft::default(),
            can3_delete: None,
            can3_track_draft: None,
            can3_curve_draft: None,
            can3_key_draft: None,
            can3_curve_track_guid: String::new(),
            can3_part_choices: Can3PartChoices::default(),
            expression_path: String::new(),
            expression_name: String::new(),
            native_physics_path: String::new(),
            parameter_filter: String::new(),
            preview_warnings: Vec::new(),
            create_class: "Node".to_owned(),
            new_node_name: String::new(),
            move_parent: None,
            insert_class: "Node".to_owned(),
            insert_suffix: String::new(),
            convert_class: None,
            node_options: NodeTreeOptions::default(),
            timeline_zoom: 1.0,
            timeline_marker_text: String::new(),
            timeline_marker_to: 0,
            timeline_marker_at: None,
            timeline_selection: None,
            timeline_value_draft: None,
            timeline_tension_draft: None,
            timeline_templates: TimelineTemplates::default(),
            timeline_weight_draft: None,
            controller_places: (Value::Null, Value::Null),
            form_edit: false,
            form_mode: 1,
            form_read: Value::Null,
            form_time_draft: None,
            sequence_panel: crate::editor_sequence::SequencePanel::default(),
            motion_sync_panel: crate::editor_motion_sync::MotionSyncPanel::default(),
            form_places: (Value::Null, Vec::new()),
            parameters: ParameterPanelState::default(),
            tools,
            agent: crate::editor_agent::AgentPanel::new(),
            windows: crate::editor_windows::Windows::new(),
            psd_depth: crate::editor_psd_depth::PsdDepthWindow::new(),
            viewport: crate::editor_viewport::ViewportState::new(),
            mesh_tools: crate::editor_mesh_tools::MeshTools::new(),
            depth_tools: crate::editor_depth::DepthTools::new(),
        };
        app.notice = problems.join("; ");
        if let Some(dir) = app.tools.config_dir.clone() {
            app.controller.with_session(|session| session.set_config_dir(dir));
        }
        app.controller.core_request(&crate::editor_windows::history_limit_request(&app.tools.store));
        app.apply_mcp();
        if let Some(path) = &open {
            app.request_open(path);
        }
        app
    }

    /// Runs a session request for the UI. A request that would replace the document first goes through the
    /// unsaved-changes flow (`guard_replace`).
    fn command(&mut self, request: Value) {
        if soul2d_core::editor_controller::replaces_document(&request) {
            self.guard_replace(PendingAction::Request(request));
        } else {
            self.run_command(request);
        }
    }

    fn run_command(&mut self, request: Value) {
        if !request["op"].as_str().is_some_and(|op| soul2d_core::manifest::effect_of(&op.replace('.', "_")) == Some("-")) {
            self.remote_quit.cancel("native_operation");
        }
        self.viewport.reconcile_views(self.controller.snapshot());
        self.parameters.reconcile(self.controller.snapshot(), &mut self.animation_name, &mut self.seek_frame);
        let replaces = soul2d_core::editor_controller::replaces_document(&request);
        if replaces {
            self.controller.allow_replace_unsaved(self.discarding);
        }
        if request["op"] == "save" {
            if self.can3_key_draft.is_some() {
                self.notice = CAN3_KEY_DRAFT_MESSAGE.to_owned();
                return;
            }
            if self.can3_curve_draft.as_ref().is_some_and(Can3CurveDraft::is_dirty) {
                self.notice = CAN3_CURVE_DRAFT_MESSAGE.to_owned();
                return;
            }
            if self.can3_track_draft.as_ref().is_some_and(Can3TrackDraft::is_dirty) {
                self.notice = CAN3_TRACK_DRAFT_MESSAGE.to_owned();
                return;
            }
            if self.can3_scene_draft.is_dirty() {
                self.notice = CAN3_SCENE_DRAFT_MESSAGE.to_owned();
                return;
            }
            let target = request["path"].as_str().unwrap_or_default();
            if autosave::is_recovery_path(Path::new(target)) {
                self.notice = RECOVERY_PATH_MESSAGE.to_owned();
                return;
            }
            if self.motion3.has_draft() {
                self.notice = MOTION3_DRAFT_MESSAGE.to_owned();
                return;
            }
            if self.forms.has_draft() {
                self.notice = FORM_DRAFT_MESSAGE.to_owned();
                return;
            }
        }
        let response = self.controller.core_request(&request);
        if response["succeeded"].as_bool() == Some(true) {
            self.notice.clear();
            self.preview_dirty = true;
            crate::editor_windows::note_saved(&request, self.controller.project_path(), &mut self.tools.store, self.tools.store_path.as_deref());
            if matches!(request["op"].as_str(), Some("live2d.model.attach" | "live2d.animation.attach")) {
                self.preview_bounds = None;
                self.can3_part_choices = Can3PartChoices::default();
            }
            if replaces {
                self.after_document_replaced();
                self.file_path = self.controller.project_path().map(|path| path.display().to_string()).unwrap_or_default();
                if request["untitled"] == true {
                    self.adopt_recovery(request["path"].as_str().unwrap_or_default());
                }
            }
        } else if replaces {
            self.notice = response["message"].as_str().unwrap_or("request failed").to_owned();
        }
        self.viewport.reconcile_views(self.controller.snapshot());
        self.parameters.reconcile(self.controller.snapshot(), &mut self.animation_name, &mut self.seek_frame);
    }

    /// A restored crash snapshot becomes this session's snapshot, so the next one replaces it and a save
    /// deletes it.
    fn adopt_recovery(&mut self, path: &str) {
        adopt_recovery(&mut self.recovery_offer, self.tools.recovery.as_mut(), PathBuf::from(path));
    }

    // Only a successful open becomes the document path; a failed path must not
    // turn into the next Save As destination.
    fn open_at(&mut self, path: &str) {
        self.controller.allow_replace_unsaved(self.discarding);
        let response = self.controller.core_request(&json!({"op":"open", "path":path}));
        if response["succeeded"].as_bool() == Some(true) {
            self.file_path = path.to_owned();
            crate::editor_windows::note_opened(path, &mut self.tools.store, self.tools.store_path.as_deref());
            self.after_document_replaced();
        } else {
            self.notice = format!(
                "Open failed: {}",
                response["message"].as_str().unwrap_or("open failed")
            );
        }
    }

    fn after_document_replaced(&mut self) {
        // ponytail: the reset never reads the context; a throwaway one keeps one reset for every caller.
        editor_view!(self, &egui::Context::default()).after_document_replaced();
    }

    fn select_node_draft(&mut self, id: u64) {
        match self.controller.select_node(id) {
            Ok(()) => {
                self.notice.clear();
                if let Some(DraftView::NodeName { value, .. }) = self.controller.draft_view() {
                    self.draft_name = value.to_owned();
                }
            }
            Err(message) => self.notice = message,
        }
    }

    fn select_anchor_draft(&mut self, scene: &str, track: &str, curve: &str, frame: i64, map_key: Option<&str>) {
        match self.controller.select_can3_anchor(scene, track, curve, frame, map_key) {
            Ok(()) => {
                self.notice.clear();
                if let Some(DraftView::Can3Anchor { value, .. }) = self.controller.draft_view() {
                    self.draft_value = value;
                }
            }
            Err(message) => self.notice = message,
        }
    }

    fn drain_host(&mut self, ctx: &egui::Context) {
        let mut drained = Vec::new();
        let mut disconnected = false;
        let mut eof = false;
        if let Some(rx) = &self.host_rx {
            loop {
                match rx.try_recv() {
                    Ok(message) => drained.push(message),
                    Err(TryRecvError::Empty) => break,
                    Err(TryRecvError::Disconnected) => {
                        disconnected = true;
                        break;
                    }
                }
            }
        }
        for message in drained {
            match message {
                HostMessage::Rpc { request, reply } => {
                    let revision = self.controller.snapshot()["revision"].clone();
                    let model_path = self.controller.snapshot()["nativePlayback"]["modelPath"].clone();
                    self.sync_panel_drafts();
                    let response = editor_view!(self, ctx).mcp(&mut self.controller, &request, McpOrigin::Client);
                    if self.controller.snapshot()["revision"] != revision {
                        self.notice.clear();
                    }
                    if self.controller.snapshot()["nativePlayback"]["modelPath"] != model_path {
                        self.preview_bounds = None;
                    }
                    let _ = reply.try_send(response);
                    self.preview_dirty = true;
                }
                HostMessage::StdinClosed => { disconnected = true; eof = true; }
                HostMessage::Failed => {
                    disconnected = true;
                    self.notice = "The stdin MCP transport failed; the editor remains open".into();
                }
            }
        }
        if disconnected {
            self.stdin_closed = true;
            self.host_rx = None;
            self.sync_panel_drafts();
            if eof && matches!(self.remote_quit, RemoteQuit::Idle)
                && editor_view!(self, ctx).quit_refusal(&self.controller).is_none() {
                ctx.send_viewport_cmd(egui::ViewportCommand::Close);
            } else {
                self.close_blocked = true;
            }
        }
    }

    fn observe_remote_quit(&mut self, ctx: &egui::Context) {
        if !self.remote_quit.active() {
            if let Some(target) = self.remote_quit.target() { self.agent.invalidate_quit(target); }
            return;
        }
        let (revision, path) = match &self.remote_quit {
            RemoteQuit::Reviewing { revision, path, .. } | RemoteQuit::Waiting { revision, path, .. } => (revision, path),
            _ => return,
        };
        let changed = revision != &self.controller.snapshot()["revision"] || path.as_deref() != self.controller.project_path();
        let acp = match &self.remote_quit {
            RemoteQuit::Reviewing { target, .. } => Some((target.clone(), None)),
            RemoteQuit::Waiting { origin: QuitOrigin::Acp { target, admitted_at, .. }, .. } => Some((target.clone(), Some(*admitted_at))),
            _ => None,
        };
        let reason = if changed { Some("document_changed".to_owned()) }
            else { acp.as_ref().and_then(|(target, admitted)| self.agent.quit_status(target, *admitted).err()) };
        self.sync_panel_drafts();
        let reason = reason.or_else(|| if acp.is_some() {
            editor_view!(self, ctx).quit_work_refusal(&self.controller)
        } else { editor_view!(self, ctx).quit_refusal(&self.controller) });
        if let Some(reason) = reason {
            self.notice = format!("Quit cancelled: {reason}");
            self.remote_quit.cancel(reason);
            if let Some(target) = self.remote_quit.target() { self.agent.invalidate_quit(target); }
        }
    }

    fn finish_remote_quit(&mut self, ctx: &egui::Context) {
        self.observe_remote_quit(ctx);
        let RemoteQuit::Waiting { receipt, deadline, origin, delivered, .. } = &mut self.remote_quit else { return };
        let mut reason = None;
        if !*delivered {
            reason = if Instant::now() >= *deadline { Some("reply_expired".to_owned()) } else {
                #[cfg(test)]
                let result = if self.hold_quit_receipt_for_test { Err(TryRecvError::Empty) } else { receipt.try_recv() };
                #[cfg(not(test))]
                let result = receipt.try_recv();
                match result {
                    Ok(Ok(())) => { *delivered = true; None },
                    Ok(Err(error)) => Some(format!("reply_failed: {error}")),
                    Err(TryRecvError::Disconnected) => Some("reply_lost".into()),
                    Err(TryRecvError::Empty) => None,
                }
            };
        }
        let acp = match origin {
            QuitOrigin::Acp { target, admitted_at, turn_deadline } => {
                if Instant::now() >= *turn_deadline { reason = Some("ACP turn expired".into()); }
                Some((target.clone(), *admitted_at))
            }
            QuitOrigin::External => None,
        };
        let ready = *delivered;
        if let Some(reason) = reason {
            self.notice = format!("Quit cancelled: {reason}");
            self.remote_quit.cancel(reason);
            if let Some(target) = self.remote_quit.target() { self.agent.invalidate_quit(target); }
            return;
        }
        ctx.request_repaint_after(Duration::from_millis(25));
        if !ready { return; }
        if let Some((target, admitted)) = acp {
            match self.agent.release_for_quit(&target, admitted) {
                crate::editor_agent::QuitRelease::Waiting => return,
                crate::editor_agent::QuitRelease::Invalid(reason) => {
                    self.notice = format!("Quit cancelled: {reason}");
                    self.remote_quit.cancel(reason);
                    return;
                }
                crate::editor_agent::QuitRelease::Released => {
                    #[cfg(test)]
                    if let Some(after_release) = self.after_quit_release_for_test.take() { after_release(self); }
                },
            }
        }
        self.sync_panel_drafts();
        if let Some(reason) = editor_view!(self, ctx).quit_refusal(&self.controller) {
            self.notice = format!("Quit cancelled: {reason}");
            self.remote_quit.cancel(reason);
            return;
        }
        self.remote_quit = RemoteQuit::Closing(self.remote_quit.attempt());
        self.closing = true;
        self.close_sent = true;
        ctx.send_viewport_cmd(egui::ViewportCommand::Close);
    }

    fn render_preview(&mut self, ctx: &egui::Context) {
        self.preview_warnings.clear();
        // Kept before any early return, so a failing render is not retried on every frame for the Solo view.
        self.solo_rendered = self.solo_key();
        self.viewport.solo_drawn = self.solo_rendered.as_ref().map(|(nodes, _)| {
            let model = &self.controller.snapshot()["model"]["nodes"];
            let mut drawn = nodes.clone();
            for node in nodes.iter().filter_map(|id| find_node(model, *id)) {
                descendant_ids(node, &mut drawn);
            }
            drawn.into_iter().collect()
        });
        // Mark first so a failing render is not retried on every frame.
        self.viewport.mark_rendered();
        let revision = self.controller.snapshot()["revision"].as_u64().unwrap_or(0);
        // The scene bounds only fit the camera when no fit is pending (document opened, "Fit preview");
        // edits keep the user's camera.
        if self.preview_bounds.is_none() {
            let bounds_response = self.controller.core_request(&json!({"op":"bounds"}));
            if bounds_response["succeeded"].as_bool() != Some(true) {
                self.preview_error = Some(format!(
                    "bounds failed: {}",
                    bounds_response["message"]
                        .as_str()
                        .unwrap_or("unknown error")
                ));
                return;
            }
            let bounds = bounds_response["result"]["bounds"].clone();
            if !bounds.is_array() {
                self.preview_error = Some("bounds response lacked a bounds array".into());
                return;
            }
            if let Some(rect) = bounds.as_array().filter(|rect| rect.len() == 4) {
                let numbers: Option<Vec<f64>> = rect.iter().map(Value::as_f64).collect();
                if let Some(rect) = numbers {
                    self.viewport.fit([rect[0], rect[1], rect[2], rect[3]]);
                }
            }
            self.preview_bounds = Some((revision, bounds));
            self.viewport.mark_rendered();
        }
        let bounds = self.viewport.view_bounds();
        let (width, height) = self.viewport.render_size();
        let mut request = json!({"op":"render", "width":width, "height":height, "bounds":bounds});
        if let Some((nodes, cover)) = &self.solo_rendered {
            request["solo"] = json!(nodes);
            request["solo_cover"] = json!(cover);
        }
        // Onion Slice: the picture of the previewed animation frame with its neighbours behind it. It has no Solo
        // view, costs several renders so it waits while the pose moves every frame (playback, physics), and a
        // document or frame it cannot draw keeps the plain picture.
        let still = !self.controller.playing() && !self.viewport.physics;
        let snapshot = self.controller.snapshot();
        let previewed = snapshot["animation"]["name"].as_str().zip(snapshot["animation"]["frame"].as_f64());
        let sequence_preview = previewed.filter(|(name, _)| {
            self.solo_rendered.is_none() && snapshot["model"]["animations"][*name]["images"]
                .as_array().into_iter().flatten().any(|track| track["sequence"].is_object())
        }).map(|(name, frame)| (name.to_owned(), frame));
        let onion = previewed.filter(|_| self.viewport.onion && still && self.solo_rendered.is_none()).map(|(name, frame)| {
            json!({"op":"animation.onion", "name":name, "frame":frame, "width":width, "height":height, "bounds":bounds})
        });
        let mut response = onion.map_or(Value::Null, |onion| self.controller.core_request(&onion));
        self.onion_drawn = response["succeeded"].as_bool() == Some(true);
        if !self.onion_drawn {
            if let Some((name, at)) = sequence_preview {
                let frame = soul2d_core::export::CameraFrame { name: name.clone(), width, height, bounds };
                let rendered = self.controller.with_session(|session| {
                    soul2d_core::export::render_clip_frame(session, &frame, &name, at, true)
                });
                self.viewport.invalidate_scene();
                match rendered {
                    Ok((rgba, warnings)) => {
                        self.preview_warnings = warnings;
                        self.preview_error = None;
                        let image = egui::ColorImage::from_rgba_unmultiplied(
                            [rgba.width() as usize, rgba.height() as usize], rgba.as_raw());
                        self.preview = Some(ctx.load_texture("model-preview", image, egui::TextureOptions::LINEAR));
                    }
                    Err(error) => self.preview_error = Some(error),
                }
                return;
            }
        }
        if !self.onion_drawn {
            response = self.controller.core_request(&request);
        }
        self.viewport.invalidate_scene();
        if response["succeeded"].as_bool() != Some(true) {
            self.preview_error = Some(format!(
                "render failed: {}",
                response["message"].as_str().unwrap_or("unknown error")
            ));
            return;
        }
        self.preview_warnings = response["result"]["warnings"]
            .as_array().into_iter().flatten().filter_map(Value::as_str).map(str::to_owned).collect();
        let Some(png) = response["result"]["png"].as_str() else {
            self.preview_error = Some("render response lacked PNG data".into());
            return;
        };
        let decoded = base64::engine::general_purpose::STANDARD
            .decode(png)
            .ok()
            .and_then(|bytes| {
                image::load_from_memory(&bytes)
                    .map(|image| image.to_rgba8())
                    .ok()
            });
        match decoded {
            None => self.preview_error = Some("render PNG could not be decoded".into()),
            Some(rgba) => {
                let size = [rgba.width() as usize, rgba.height() as usize];
                let image = egui::ColorImage::from_rgba_unmultiplied(size, rgba.as_raw());
                self.preview =
                    Some(ctx.load_texture("model-preview", image, egui::TextureOptions::LINEAR));
            }
        }
    }

    /// Onion Slice waits while playback or physics runs, so it is due again when they stop (a pause from any
    /// button, key or tool), and the plain picture is due again when they start.
    fn motion_changed(&mut self) -> bool {
        let still = !self.controller.playing() && !self.viewport.physics;
        std::mem::replace(&mut self.was_still, still) != still && self.viewport.onion
    }

    /// What the Solo view draws in front and its inactive colour: the selection, while Solo is on. Only an INX
    /// document has a selection.
    fn solo_key(&self) -> Option<(Vec<u64>, [u8; 4])> {
        let nodes = self.controller.selected_nodes();
        (self.viewport.solo.show && !nodes.is_empty()).then(|| (nodes.to_vec(), self.viewport.solo.colour))
    }

    fn node_tree(&mut self, ui: &mut egui::Ui) {
        let filter_label = ui.label("Node filter");
        ui.text_edit_singleline(&mut self.node_options.filter)
            .labelled_by(filter_label.id);
        ui.checkbox(&mut self.node_options.reverse, "Reverse node order");
        ui.checkbox(&mut self.node_options.follow, "Follow selection");
        let mut all = None;
        ui.horizontal(|ui| {
            if ui.button(tr("Show all")).clicked() {
                all = Some(true);
            }
            if ui.button(tr("Hide all")).clicked() {
                all = Some(false);
            }
        });
        let mut out = NodeTreeOutput::default();
        {
            let snapshot = self.controller.snapshot();
            out.commands.extend(all.and_then(|enabled| visibility_all_command(&snapshot["model"]["nodes"], enabled)));
            let selection = self.controller.selected_nodes();
            let scroll_to = self.node_options.pending_scroll(self.controller.selected_node());
            let needle = self.node_options.filter.to_lowercase();
            let mut visible = HashSet::new();
            visible_nodes(&snapshot["model"]["nodes"], &needle, &mut visible);
            if visible.is_empty() {
                ui.label("No nodes match the filter");
            } else {
                let view = NodeRowView {
                    model: &snapshot["model"],
                    visible: &visible,
                    reverse: self.node_options.reverse,
                    selection,
                    scroll_to,
                    clipboard_empty: snapshot["clipboard"].as_array().is_none_or(|list| list.is_empty()),
                    armed: self.parameters.armed.is_some(),
                    draft_dirty: self.controller.draft_dirty(),
                };
                draw_node_tree(ui, &view, &mut self.node_options, &mut out);
                if out.scrolled {
                    if let Some(id) = scroll_to {
                        self.node_options.completed_scroll(id);
                    }
                }
                if ui.ui_contains_pointer()
                    && !ui.ctx().wants_keyboard_input()
                    && !view.armed
                    && ui.input(|input| input.modifiers.command && input.key_pressed(egui::Key::A))
                {
                    out.select_all = true;
                }
            }
        }
        self.apply_node_tree(out);
        ui.separator();
        self.node_controls(ui);
    }

    /// Carries out what a frame of the node tree asked for: selection first, so the commands run
    /// on the selection the user sees after the click.
    fn apply_node_tree(&mut self, out: NodeTreeOutput) {
        let order: Vec<u64> = out.rows.iter().map(|row| row.id).collect();
        if let Err(message) = apply_row_clicks(&mut self.controller, &out.clicks, &order) {
            self.notice = message;
        }
        if out.select_all {
            if let Err(message) = self.controller.select_all_nodes() {
                self.notice = message;
            }
        } else if out.background_click && out.clicks.is_empty() {
            self.controller.clear_node_selection();
        }
        if let Some(id) = out.edit {
            self.select_node_draft(id);
        }
        for command in &out.commands {
            match command.action() {
                Some(action) => {
                    self.node_action(action);
                }
                None => {
                    if let Some(request) = command.request() {
                        self.node_options.request = Some(request);
                    }
                }
            }
        }
        if let Some(site) = out.drop {
            self.node_action(NodeAction::Drop { site });
        }
    }

    fn node_controls(&mut self, ui: &mut egui::Ui) {
        let dirty = self.controller.draft_dirty();
        let selected = self.controller.selected_node();
        let selection = self.controller.selected_nodes_in_tree_order();
        let common_type = self.controller.common_node_type(&selection);
        let usage = selected.map(|id| self.controller.parameter_usage(id)).unwrap_or_default();
        let (root_id, target_type, target_enabled, clipboard_empty, destinations) = {
            let snapshot = self.controller.snapshot();
            let root_id = snapshot["model"]["nodes"]["uuid"].as_u64().unwrap_or(0);
            let target = selected.unwrap_or(root_id);
            let target_node = find_node(&snapshot["model"]["nodes"], target);
            let target_type = target_node
                .and_then(|node| node["type"].as_str())
                .unwrap_or("Node")
                .to_owned();
            let target_enabled = target_node
                .and_then(|node| node["enabled"].as_bool())
                .unwrap_or(true);
            let clipboard_empty = snapshot["clipboard"]
                .as_array()
                .map(|clipboard| clipboard.is_empty())
                .unwrap_or(true);
            let mut destinations = Vec::new();
            collect_move_destinations(
                &snapshot["model"]["nodes"],
                &selection,
                root_id,
                &mut destinations,
            );
            (root_id, target_type, target_enabled, clipboard_empty, destinations)
        };
        let target = selected.unwrap_or(root_id);
        let target_is_root = target == root_id;
        let parent_accepts = target_is_root || target_type != "Mask";
        // Actions that rewrite the tree skip the root, so they need at least one other node.
        let non_root_selected = selection.iter().any(|id| *id != root_id);
        let convert_choices = if selection.contains(&root_id) {
            &[][..]
        } else {
            common_type.as_deref().map(node_convert_classes).unwrap_or(&[])
        };
        if self
            .move_parent
            .is_some_and(|id| !destinations.iter().any(|(dest_id, _)| *dest_id == id))
        {
            self.move_parent = None;
        }
        if self
            .convert_class
            .as_deref()
            .is_some_and(|class| !convert_choices.contains(&class))
        {
            self.convert_class = None;
        }

        ui.heading(tr("Nodes"));
        if selection.len() > 1 {
            ui.label(format!("{} nodes selected", selection.len()));
        }
        egui::ComboBox::from_label("Node class")
            .selected_text(self.create_class.as_str())
            .show_ui(ui, |ui| {
                for class_name in NODE_CREATE_CLASSES {
                    if ui
                        .selectable_value(
                            &mut self.create_class,
                            (*class_name).to_owned(),
                            *class_name,
                        )
                        .changed()
                    {
                        ui.close();
                    }
                }
            });
        ui.horizontal(|ui| {
            let name_label = ui.label("New node name");
            ui.text_edit_singleline(&mut self.new_node_name)
                .labelled_by(name_label.id);
        });

        let bone_parent = matches!(target_type.as_str(), "DepthRigRoot" | "DepthBone");
        let create_allowed = !dirty
            && parent_accepts
            && (self.create_class != "DepthBone" || bone_parent);
        if ui
            .add_enabled(create_allowed, egui::Button::new(tr("Create")))
            .clicked()
        {
            let name = if self.new_node_name.trim().is_empty() {
                None
            } else {
                Some(self.new_node_name.clone())
            };
            let class_name = self.create_class.clone();
            self.node_action(NodeAction::Create {
                class_name: &class_name,
                name: name.as_deref(),
            });
        }

        ui.horizontal(|ui| {
            let suffix_label = ui.label("Add suffix");
            ui.text_edit_singleline(&mut self.node_options.suffix)
                .labelled_by(suffix_label.id);
            let add_allowed = !dirty && parent_accepts && !self.node_options.suffix.is_empty();
            if ui.add_enabled(add_allowed, egui::Button::new("Add with suffix")).clicked() {
                let class_name = self.create_class.clone();
                let suffix = std::mem::take(&mut self.node_options.suffix);
                if !self.node_action(NodeAction::Add { class_name: &class_name, suffix: Some(&suffix) }) {
                    self.node_options.suffix = suffix;
                }
            }
        });

        let copy_allowed = non_root_selected;
        ui.horizontal(|ui| {
            if ui.add_enabled(copy_allowed, egui::Button::new(tr("Copy"))).clicked() {
                self.node_action(NodeAction::Copy);
            }
            let mutate_allowed = !dirty && copy_allowed;
            if ui.add_enabled(mutate_allowed, egui::Button::new(tr("Cut"))).clicked() {
                self.node_action(NodeAction::Cut);
            }
            let paste_allowed = !dirty && !clipboard_empty && parent_accepts;
            if ui.add_enabled(paste_allowed, egui::Button::new(tr("Paste"))).clicked() {
                self.node_action(NodeAction::Paste);
            }
            // Dropping dragged rows on the button deletes them, as in D.
            let delete = ui.add_enabled(mutate_allowed, egui::Button::new(tr("Delete")));
            if delete.clicked() || delete.dnd_release_payload::<NodeDrag>().is_some() {
                self.node_action(NodeAction::Delete);
            }
        });

        let many = selection.len() > 1;
        let visibility_label = match (selected.is_none(), target_enabled, many) {
            (true, _, _) => "Toggle visibility",
            (false, true, false) => "Hide node",
            (false, false, false) => "Show node",
            (false, true, true) => "Hide nodes",
            (false, false, true) => "Show nodes",
        };
        let visibility_allowed = !dirty && selected.is_some();
        ui.horizontal(|ui| {
            if ui
                .add_enabled(visibility_allowed, egui::Button::new(visibility_label))
                .clicked()
            {
                self.node_action(NodeAction::ToggleVisibility);
            }
            let subtree_label = if target_enabled { "Hide with children" } else { "Show with children" };
            if ui
                .add_enabled(visibility_allowed, egui::Button::new(subtree_label))
                .clicked()
            {
                self.node_action(NodeAction::SetVisibility {
                    nodes: &[],
                    enabled: Some(!target_enabled),
                    recursive: true,
                });
            }
        });

        if selected.is_some()
            && edit_mesh_offered(&target_type, self.parameters.armed.is_some())
            && ui.add_enabled(!dirty, egui::Button::new("Edit Mesh")).clicked()
        {
            self.node_options.request = u32::try_from(target).ok().map(NodeTreeRequest::EditMesh);
        }

        let move_allowed = !dirty && non_root_selected;
        let selected_label = self
            .move_parent
            .and_then(|id| {
                destinations
                    .iter()
                    .find(|(dest_id, _)| *dest_id == id)
                    .map(|(_, label)| label.clone())
            })
            .unwrap_or_else(|| "Move destination".to_owned());
        ui.horizontal(|ui| {
            egui::ComboBox::from_label("Move destination")
                .selected_text(selected_label)
                .show_ui(ui, |ui| {
                    for (id, label) in &destinations {
                        if ui
                            .selectable_value(&mut self.move_parent, Some(*id), label)
                            .changed()
                        {
                            ui.close();
                        }
                    }
                });
            if ui
                .add_enabled(
                    move_allowed && self.move_parent.is_some(),
                    egui::Button::new("Move"),
                )
                .clicked()
            {
                if let Some(parent) = self.move_parent {
                    self.node_action(NodeAction::Reparent { parent });
                }
            }
        });

        let insert_allowed = !dirty && non_root_selected;
        ui.horizontal(|ui| {
            egui::ComboBox::from_label("Insert class")
                .selected_text(self.insert_class.as_str())
                .show_ui(ui, |ui| {
                    for class_name in NODE_INSERT_CLASSES {
                        if ui
                            .selectable_value(
                                &mut self.insert_class,
                                (*class_name).to_owned(),
                                *class_name,
                            )
                            .changed()
                        {
                            ui.close();
                        }
                    }
                });
            if ui
                .add_enabled(insert_allowed, egui::Button::new("Insert"))
                .clicked()
            {
                let class_name = self.insert_class.clone();
                let suffix = if self.insert_suffix.is_empty() {
                    None
                } else {
                    Some(self.insert_suffix.clone())
                };
                if self.node_action(NodeAction::Insert {
                    class_name: &class_name,
                    suffix: suffix.as_deref(),
                }) {
                    self.insert_suffix.clear();
                }
            }
        });
        ui.horizontal(|ui| {
            let suffix_label = ui.label("Insert suffix");
            ui.text_edit_singleline(&mut self.insert_suffix)
                .labelled_by(suffix_label.id);
        });
        ui.horizontal(|ui| {
            egui::ComboBox::from_label("Convert to")
                .selected_text(self.convert_class.as_deref().unwrap_or("Convert to"))
                .show_ui(ui, |ui| {
                    for class_name in convert_choices {
                        if ui
                            .selectable_value(
                                &mut self.convert_class,
                                Some((*class_name).to_owned()),
                                *class_name,
                            )
                            .changed()
                        {
                            ui.close();
                        }
                    }
                });
            let convert_allowed = !dirty && non_root_selected && self.convert_class.is_some();
            if ui
                .add_enabled(convert_allowed, egui::Button::new("Convert"))
                .clicked()
            {
                if let Some(class_name) = self.convert_class.clone() {
                    self.node_action(NodeAction::Convert {
                        class_name: &class_name,
                    });
                }
            }
        });
        egui::CollapsingHeader::new("Parameter usage").show(ui, |ui| {
            if selected.is_none() {
                ui.label("Select a node to see its parameters");
            } else if usage.is_empty() {
                ui.label("No parameter uses this node");
            }
            for parameter in &usage {
                ui.label(format!("{} #{}", parameter.name, parameter.uuid));
            }
        });
    }

    fn node_action(&mut self, action: NodeAction<'_>) -> bool {
        let response = self.controller.node_action(action);
        if response["succeeded"].as_bool() == Some(true) {
            self.notice.clear();
            self.preview_dirty = true;
            true
        } else {
            self.notice = response["message"]
                .as_str()
                .unwrap_or("node action failed")
                .to_owned();
            false
        }
    }

    fn inx_preview_controls(&mut self, ui: &mut egui::Ui) {
        ui.heading("INX runtime preview");
        ui.label("Preview values and playback are not saved edits.");
        let snapshot = self.controller.snapshot().clone();
        let mut ambient = [0, 1, 2].map(|channel| {
            snapshot["scene"]["ambientLight"][channel].as_f64().unwrap_or(1.0) as f32
        });
        ui.horizontal(|ui| {
            ui.label("Ambient light");
            if ui.color_edit_button_rgb(&mut ambient).on_hover_text("Scene ambient light").changed() {
                self.command(json!({"op":"scene.ambient.set", "color":ambient.map(|c| f64::from(c).clamp(0.0, 1.0))}));
            }
        });
        fn collect<'a>(list: &'a Value, output: &mut Vec<&'a Value>) {
            for parameter in list.as_array().into_iter().flatten() {
                output.push(parameter);
                collect(&parameter["children"], output);
            }
        }
        let mut parameters = Vec::new();
        collect(&snapshot["model"]["param"], &mut parameters);
        self.lightweight.checkbox(ui);
        match self.lightweight.frozen(self.controller.playing()) {
            Some(values) => {
                let mut shown = snapshot.clone();
                shown["values"] = values.clone();
                self.parameters_section(ui, &shown);
            }
            None => self.parameters_section(ui, &snapshot),
        }
        ui.separator();
        let names: Vec<String> = snapshot["model"]["animations"]
            .as_object()
            .map(|animations| animations.keys().cloned().collect())
            .unwrap_or_default();
        if let Some(active) = snapshot["animation"]["name"].as_str() {
            ui.label(format!(
                "Session: {active}, frame {:.3}",
                snapshot["animation"]["frame"].as_f64().unwrap_or(0.0)
            ));
        } else {
            ui.label("Session: no animation preview");
        }
        ui.horizontal(|ui| {
            ui.label("Animation name");
            ui.text_edit_singleline(&mut self.new_animation_name);
            let name = self.new_animation_name.clone();
            if ui.button("Create animation").clicked() {
                self.command(json!({"op":"animation.create", "name":name}));
                self.animation_name = name.clone();
            }
            if !names.is_empty() && ui.button("Rename animation").clicked() {
                self.controller.pause();
                self.command(json!({"op":"animation.rename", "name":self.animation_name, "new_name":name}));
                self.animation_name = name;
            }
        });
        if names.is_empty() {
            ui.label("No authored INX animations.");
            return;
        }
        let mut selected = self.animation_name.clone();
        egui::ComboBox::from_id_salt("inx-animation")
            .selected_text(&self.animation_name)
            .show_ui(ui, |ui| {
                for name in names {
                    ui.selectable_value(&mut selected, name.clone(), name);
                }
            });
        if selected != self.animation_name {
            self.apply_window_request(ui.ctx(), crate::editor_windows::Request::Mcp(
                crate::editor_windows::McpTarget::ParameterPanel,
                crate::editor_windows::call_request("editor_parameters_set", json!({"animation":selected}))));
        }
        if ui.button("Delete animation").clicked() {
            self.controller.pause();
            self.command(json!({"op":"animation.delete", "name":self.animation_name}));
            return;
        }
        let source = (self.animation_name.clone(), snapshot["revision"].as_u64().unwrap_or(0));
        if self.animation_draft.source != source {
            let animation = &snapshot["model"]["animations"][&self.animation_name];
            self.animation_draft = AnimationDraft::read(source, animation);
        }
        let draft = &mut self.animation_draft;
        ui.horizontal(|ui| {
            ui.label(tr("Frames"));
            if ui.add(egui::DragValue::new(&mut draft.length).range(1..=i64::from(i32::MAX))).changed() {
                draft.lead_out = draft.length;
            }
            ui.label("Lead in");
            ui.add(egui::DragValue::new(&mut draft.lead_in).range(-1..=draft.length));
            ui.label("Lead out");
            ui.add(egui::DragValue::new(&mut draft.lead_out).range(-1..=draft.length));
        });
        ui.horizontal(|ui| {
            ui.checkbox(&mut draft.additive, tr("Additive"));
            ui.label(tr("Weight"));
            ui.add(egui::DragValue::new(&mut draft.weight).speed(0.01));
            ui.label(tr("Framerate"));
            ui.add(egui::DragValue::new(&mut draft.framerate).range(1.0..=1000.0));
            ui.label(format!("{:.3} s", draft.length as f64 / draft.framerate));
        });
        let full_span = (draft.lead_in == -1 || draft.lead_in == 0)
            && (draft.lead_out == -1 || draft.lead_out == draft.length);
        ui.add_enabled(
            draft.loop_editing || full_span,
            egui::Checkbox::new(&mut draft.loop_editing, "Loop editing support"),
        )
        .on_hover_text("Loop editing requires lead-in at the clip start and lead-out at the clip end");
        if ui.button("Apply animation settings").clicked() {
            let request = self.animation_draft.request();
            self.controller.pause();
            self.command(request);
        }
        ui.horizontal(|ui| {
            ui.label("Seek frame");
            ui.add(egui::DragValue::new(&mut self.seek_frame).speed(0.25));
            if ui.button("Seek").clicked() {
                self.command(json!({"op":"animation.seek", "name":self.animation_name, "frame":self.seek_frame}));
            }
        });
        ui.horizontal(|ui| {
            if ui
                .add_enabled(!self.controller.playing(), egui::Button::new("Play"))
                .clicked()
            {
                if self.snap_to_framerate {
                    // Whole steps from a fractional frame would never land on a frame.
                    let active = &self.controller.snapshot()["animation"];
                    let frame = active["frame"].as_f64().filter(|frame| {
                        active["name"].as_str() == Some(self.animation_name.as_str()) && frame.fract() != 0.0
                    });
                    if let Some(frame) = frame {
                        self.command(timeline_seek_request(&self.animation_name, frame.floor()));
                    }
                }
                let response = self.controller.play(&self.animation_name);
                if response["succeeded"].as_bool() == Some(true) {
                    self.frame_carry = 0.0;
                    self.last_tick = Some(Instant::now());
                    self.preview_dirty = true;
                }
            }
            if ui
                .add_enabled(self.controller.playing(), egui::Button::new("Pause"))
                .clicked()
            {
                self.controller.pause();
            }
            if ui.button("Reset preview").clicked() {
                self.command(json!({"op":"animation.reset"}));
            }
            ui.checkbox(&mut self.looping, "Loop");
            ui.checkbox(&mut self.snap_to_framerate, tr("Lock playback to animation framerate"));
        });
        ui.label(if self.controller.playing() {
            "Playing"
        } else {
            "Paused"
        });
        ui.separator();
        ui.label("Animation key edits are saved and share Undo/Redo.");
        let mut keyed = Vec::new();
        for parameter in &parameters {
            if parameter.get("groupUUID").is_some() {
                continue;
            }
            let Some(id) = parameter["uuid"]
                .as_u64()
                .and_then(|id| u32::try_from(id).ok())
                .filter(|id| *id != 0 && *id != u32::MAX)
            else {
                continue;
            };
            keyed.push((id, parameter["name"].as_str().unwrap_or("Parameter").to_owned()));
        }
        if keyed.is_empty() {
            ui.label("No parameters to key.");
            return;
        }
        if self
            .key_parameter
            .is_none_or(|selected| !keyed.iter().any(|(id, _)| *id == selected))
        {
            self.key_parameter = Some(keyed[0].0);
        }
        let frame_valid = snapshot["model"]["animations"][&self.animation_name]["length"]
            .as_i64()
            .is_some_and(|length| timeline_key_frame(self.seek_frame, length).is_some());
        let label = self
            .key_parameter
            .and_then(|id| {
                keyed
                    .iter()
                    .find(|(keyed_id, _)| *keyed_id == id)
                    .map(|(_, name)| format!("{name} #{id}"))
            })
            .unwrap_or_default();
        egui::ComboBox::from_id_salt("inx-key-parameter")
            .selected_text(label)
            .show_ui(ui, |ui| {
                for (id, name) in &keyed {
                    if ui
                        .selectable_value(
                            &mut self.key_parameter,
                            Some(*id),
                            format!("{name} #{id}"),
                        )
                        .changed()
                    {
                        ui.close();
                    }
                }
            });
        let Some(parameter_id) = self.key_parameter else {
            return;
        };
        let clipboard_empty = snapshot["animationClipboard"]
            .as_array()
            .map(Vec::is_empty)
            .unwrap_or(true);
        ui.horizontal(|ui| {
            for (label, op) in [
                ("Add key", "animation.key.add"),
                ("Copy key", "animation.key.copy"),
                ("Paste key", "animation.key.paste"),
            ] {
                let enabled = frame_valid && (op != "animation.key.paste" || !clipboard_empty);
                if ui.add_enabled(enabled, egui::Button::new(label)).clicked() {
                    self.command(json!({
                        "op": op,
                        "name": self.animation_name,
                        "parameter": parameter_id,
                        "frame": self.seek_frame as i64,
                    }));
                }
            }
        });
        if !frame_valid {
            ui.label("Choose an integer frame within the animation.");
        }
    }

    fn can3_track_form(&mut self, ui: &mut egui::Ui, enabled: bool) {
        let snapshot = self.controller.snapshot();
        let revision = snapshot["revision"].as_u64().unwrap_or_default();
        let model = json!({
            "resources":snapshot["model"]["resources"],
            "scenes":snapshot["model"]["scenes"].as_array().into_iter().flatten()
                .map(|scene| json!({"guid":scene["guid"], "name":scene["name"]})).collect::<Vec<_>>(),
        });
        let scenes = model["scenes"].as_array();
        if !scenes.into_iter().flatten().any(|scene| scene["guid"] == self.native_scene_guid) {
            self.native_scene_guid = scenes.and_then(|all| all.first())
                .and_then(|scene| scene["guid"].as_str()).unwrap_or_default().to_owned();
        }
        let editing = !self.closing && self.unsaved.is_none() && self.tools.prompt.is_none()
            && self.can3_delete.is_none();
        ui.add_enabled_ui(editing, |ui| {
            ui.strong("New CAN3 model track");
            let selected = scenes.into_iter().flatten().find(|scene| scene["guid"] == self.native_scene_guid);
            let label = ui.label("New track scene");
            let previous_scene = self.native_scene_guid.clone();
            egui::ComboBox::from_id_salt("can3-track-scene")
                .selected_text(selected.and_then(|scene| scene["name"].as_str()).unwrap_or("No CAN3 scene"))
                .show_ui(ui, |ui| {
                    for scene in scenes.into_iter().flatten() {
                        if let Some(guid) = scene["guid"].as_str() {
                            ui.selectable_value(&mut self.native_scene_guid, guid.to_owned(),
                                format!("{} ({guid})", scene["name"].as_str().unwrap_or("Scene")));
                        }
                    }
                }).response.labelled_by(label.id);
            if previous_scene != self.native_scene_guid {
                self.controller.pause();
                self.seek_frame = 0.0;
            }
            if !self.can3_track_draft.as_ref().is_some_and(Can3TrackDraft::is_dirty) {
                self.can3_track_draft = scenes.into_iter().flatten().find(|scene| scene["guid"] == self.native_scene_guid)
                    .map(|_| {
                        let resource = model["resources"].as_array().filter(|all| all.len() == 1)
                            .and_then(|all| all[0]["guid"].as_str()).unwrap_or_default().to_owned();
                        Can3TrackDraft { scene_guid:self.native_scene_guid.clone(), expected_revision:revision,
                            name:"Track".into(), resource_guid:resource.clone(), initial_resource_guid:resource }
                    });
            }
            let Some(draft) = self.can3_track_draft.as_mut() else {
                ui.label("Add a CAN3 scene before adding a track.");
                ui.add_enabled(false, egui::Button::new("Add CAN3 track"));
                return;
            };
            ui.label(format!("Target scene GUID: {}", draft.scene_guid));
            let label = ui.label("New track name");
            ui.add(egui::TextEdit::singleline(&mut draft.name)).labelled_by(label.id);
            let label = ui.label("New track resource");
            let resource = model["resources"].as_array().into_iter().flatten()
                .find(|resource| resource["guid"] == draft.resource_guid);
            egui::ComboBox::from_id_salt("can3-track-resource")
                .selected_text(resource.and_then(|resource| resource["name"].as_str()).unwrap_or("Choose existing resource"))
                .show_ui(ui, |ui| {
                    for resource in model["resources"].as_array().into_iter().flatten() {
                        if let Some(guid) = resource["guid"].as_str() {
                            ui.selectable_value(&mut draft.resource_guid, guid.to_owned(),
                                format!("{} ({guid}) — {}", resource["name"].as_str().unwrap_or("Model"),
                                    resource["sourceFile"].as_str().unwrap_or_default()));
                        }
                    }
                }).response.labelled_by(label.id);
            let stale = draft.expected_revision != revision || draft.scene_guid != self.native_scene_guid
                || !scenes.into_iter().flatten().any(|scene| scene["guid"] == draft.scene_guid);
            let has_resource = model["resources"].as_array().into_iter().flatten()
                .any(|resource| resource["guid"] == draft.resource_guid);
            if stale { ui.label("CAN3 or scene selection changed; discard and review the track form again."); }
            if !has_resource { ui.label("Choose an existing linked model resource. This form does not create resources."); }
            let mut request = None;
            let mut discard = false;
            ui.horizontal(|ui| {
                if ui.add_enabled(enabled && !stale && has_resource, egui::Button::new("Add CAN3 track")).clicked() {
                    request = Some(json!({"op":"live2d.animation.track.add", "sceneGuid":draft.scene_guid,
                        "resourceGuid":draft.resource_guid, "name":draft.name, "expectedRevision":draft.expected_revision}));
                }
                discard = ui.add_enabled(draft.is_dirty(), egui::Button::new("Discard new track")).clicked();
            });
            if let Some(request) = request {
                self.command(request);
                if self.controller.snapshot()["revision"].as_u64() != Some(revision) {
                    self.can3_track_draft = None;
                }
            } else if discard { self.can3_track_draft = None; }
        });
    }

    fn can3_curve_form(&mut self, ui: &mut egui::Ui, enabled: bool) {
        let snapshot = self.controller.snapshot();
        let revision = snapshot["revision"].as_u64().unwrap_or_default();
        let model_path = snapshot["nativePlayback"]["modelPath"].as_str().unwrap_or_default().to_owned();
        let resource_guid = snapshot["nativePlayback"]["resourceGuid"].as_str().unwrap_or_default().to_owned();
        let source = (resource_guid.clone(), model_path.clone());
        if self.can3_part_choices.source.as_ref().is_some_and(|old| old != &source) {
            self.can3_part_choices = Can3PartChoices::default();
        }
        let parameters = snapshot["nativePlayback"]["parameters"].as_array().into_iter().flatten()
            .filter_map(|parameter| Some((parameter["id"].as_str()?.to_owned(),
                format!("{} ({})", parameter["name"].as_str().filter(|name| !name.is_empty())
                    .unwrap_or(parameter["id"].as_str()?), parameter["id"].as_str()?))))
            .collect::<Vec<_>>();
        let scene = snapshot["model"]["scenes"].as_array().into_iter().flatten()
            .find(|scene| scene["guid"] == self.native_scene_guid);
        let tracks = scene.into_iter().flat_map(|scene| scene["tracks"].as_array().into_iter().flatten())
            .map(|track| json!({"guid":track["guid"],"name":track["name"],"resourceGuid":track["resourceGuid"]}))
            .collect::<Vec<_>>();
        if !tracks.iter().any(|track| track["guid"] == self.can3_curve_track_guid) {
            self.can3_curve_track_guid = tracks.first().and_then(|track| track["guid"].as_str()).unwrap_or_default().to_owned();
        }
        let editing = !self.closing && self.unsaved.is_none() && self.tools.prompt.is_none() && self.can3_delete.is_none();
        let (mut request, mut load_parts, mut discard) = (None, false, false);
        ui.add_enabled_ui(editing, |ui| {
            ui.strong("New CAN3 model curve");
            ui.label(format!("Curve scene GUID: {}", self.native_scene_guid));
            let label = ui.label("New curve track");
            egui::ComboBox::from_id_salt("can3-curve-track")
                .selected_text(tracks.iter().find(|track| track["guid"] == self.can3_curve_track_guid)
                    .and_then(|track| track["name"].as_str()).unwrap_or("No CAN3 track"))
                .show_ui(ui, |ui| {
                    for track in &tracks {
                        if let Some(guid) = track["guid"].as_str() {
                            ui.selectable_value(&mut self.can3_curve_track_guid, guid.to_owned(),
                                format!("{} ({guid})", track["name"].as_str().unwrap_or("Track")));
                        }
                    }
                }).response.labelled_by(label.id);
            if !self.can3_curve_draft.as_ref().is_some_and(Can3CurveDraft::is_dirty) {
                self.can3_curve_draft = tracks.iter().find(|track| track["guid"] == self.can3_curve_track_guid)
                    .map(|track| Can3CurveDraft { scene_guid:self.native_scene_guid.clone(),
                        track_guid:self.can3_curve_track_guid.clone(), expected_revision:revision,
                        resource_guid:track["resourceGuid"].as_str().unwrap_or_default().to_owned(), model_path:model_path.clone(),
                        kind:Can3CurveKind::Parameter, target_id:String::new() });
            }
            let Some(draft) = self.can3_curve_draft.as_mut() else {
                ui.label("Add a CAN3 track before adding a curve.");
                ui.add_enabled(false, egui::Button::new("Add CAN3 curve"));
                return;
            };
            ui.label(format!("Target: scene {}, track {}, resource {}", draft.scene_guid, draft.track_guid, draft.resource_guid));
            let stale = draft.expected_revision != revision || draft.scene_guid != self.native_scene_guid
                || draft.track_guid != self.can3_curve_track_guid || draft.model_path != model_path
                || !tracks.iter().any(|track| track["guid"] == draft.track_guid && track["resourceGuid"] == draft.resource_guid);
            let bound = !model_path.is_empty() && !resource_guid.is_empty() && draft.resource_guid == resource_guid;
            if !bound { ui.label("Explicitly attach a CMO3 to this track's linked resource before adding curves."); }
            if stale { ui.label("CAN3, selection or attachment changed; discard and review the curve form again."); }
            let old_kind = draft.kind;
            let label = ui.label("New curve kind");
            egui::ComboBox::from_id_salt("can3-curve-kind")
                .selected_text(match draft.kind { Can3CurveKind::Parameter => "Parameter", Can3CurveKind::PartOpacity => "PartOpacity" })
                .show_ui(ui, |ui| {
                    ui.selectable_value(&mut draft.kind, Can3CurveKind::Parameter, "Parameter");
                    ui.selectable_value(&mut draft.kind, Can3CurveKind::PartOpacity, "PartOpacity");
                }).response.labelled_by(label.id);
            if old_kind != draft.kind { draft.target_id.clear(); }
            if draft.kind == Can3CurveKind::PartOpacity {
                load_parts = ui.add_enabled(bound && !stale, egui::Button::new("Refresh Part choices")).clicked();
                if self.can3_part_choices.source.as_ref() != Some(&source) {
                    ui.label("Read Part IDs from the explicitly attached CMO3 with Refresh Part choices.");
                }
                ui.label("New PartOpacity curves require a nonempty Part ID without ':'.");
            }
            let choices = match draft.kind {
                Can3CurveKind::Parameter => &parameters,
                Can3CurveKind::PartOpacity => &self.can3_part_choices.parts,
            };
            let label = ui.label("New curve target");
            egui::ComboBox::from_id_salt("can3-curve-target")
                .selected_text(choices.iter().find(|(id,_)| id == &draft.target_id)
                    .map(|(_,label)| label.as_str()).unwrap_or("Choose existing target"))
                .show_ui(ui, |ui| {
                    for (id,label) in choices { ui.selectable_value(&mut draft.target_id, id.clone(), label); }
                }).response.labelled_by(label.id);
            if choices.is_empty() { ui.label("No target choices are available for this curve kind."); }
            ui.horizontal(|ui| {
                if ui.add_enabled(enabled && !stale && bound && choices.iter().any(|(id,_)| id == &draft.target_id),
                    egui::Button::new("Add CAN3 curve")).clicked()
                {
                    let mut add = json!({"op":"live2d.animation.curve.add", "sceneGuid":draft.scene_guid,
                        "trackGuid":draft.track_guid, "modelPath":draft.model_path,"expectedRevision":draft.expected_revision});
                    add[match draft.kind { Can3CurveKind::Parameter => "parameterId", Can3CurveKind::PartOpacity => "partId" }] = json!(draft.target_id);
                    request = Some(add);
                }
                discard = ui.add_enabled(draft.is_dirty(), egui::Button::new("Discard new curve")).clicked();
            });
        });
        if load_parts {
            self.can3_part_choices = Can3PartChoices::default();
            let result = self.controller.core_request(&json!({"op":"live2d.authoring.read", "path":model_path}));
            if result["succeeded"] == true {
                self.can3_part_choices.source = Some(source);
                self.can3_part_choices.parts = result["result"]["sources"].as_array().into_iter().flatten()
                    .filter(|part| part["data"]["type"] == "Part"
                        && part["id"].as_str().is_some_and(|id| !id.is_empty() && !id.contains(':')))
                    .filter_map(|part| Some((part["id"].as_str()?.to_owned(),
                        format!("{} ({})", part["id"].as_str()?, part["guid"].as_str()?))))
                    .collect();
            }
        } else if let Some(request) = request {
            self.command(request);
            if self.controller.snapshot()["revision"].as_u64() != Some(revision) { self.can3_curve_draft = None; }
        } else if discard { self.can3_curve_draft = None; }
    }

    fn can3_key_form(&mut self, ui: &mut egui::Ui, enabled: bool) {
        let Some(draft) = self.can3_key_draft.as_mut() else { return };
        let revision = self.controller.snapshot()["revision"].as_u64().unwrap_or_default();
        let stale = draft.expected_revision != revision;
        let (mut add, mut discard) = (false, false);
        ui.add_enabled_ui(!self.closing && self.unsaved.is_none() && self.tools.prompt.is_none() && self.can3_delete.is_none(), |ui| {
            ui.group(|ui| {
                ui.strong("New CAN3 key");
                ui.label(format!("Scene {}, track {}, curve {}", draft.scene_guid, draft.track_guid, draft.curve_id));
                if let Some(key) = &draft.map_key { ui.label(format!("Map key: {key}")); }
                if stale { ui.label("CAN3 changed; discard and review the key form again."); }
                let label = ui.label("New key frame");
                ui.add(egui::DragValue::new(&mut draft.frame).range(i32::MIN..=i32::MAX)).labelled_by(label.id);
                let label = ui.label("New key value");
                ui.add(egui::DragValue::new(&mut draft.value).speed(0.01)).labelled_by(label.id);
                let label = ui.label("New key type");
                egui::ComboBox::from_id_salt("can3-key-type").selected_text(draft.curve_type).show_ui(ui, |ui| {
                    for kind in ["LINEAR", "SMOOTH", "BEZIER", "STEP"] {
                        ui.selectable_value(&mut draft.curve_type, kind, kind);
                    }
                }).response.labelled_by(label.id);
                ui.horizontal(|ui| {
                    add = ui.add_enabled(enabled && !stale && draft.value.is_finite(), egui::Button::new("Add CAN3 key")).clicked();
                    discard = ui.button("Discard new key").clicked();
                });
            });
        });
        if add {
            let mut request = json!({"op":"live2d.animation.key.add", "sceneGuid":draft.scene_guid,
                "trackGuid":draft.track_guid, "curveId":draft.curve_id, "anchorFrame":draft.frame,
                "value":draft.value, "type":draft.curve_type, "expectedRevision":draft.expected_revision});
            if let Some(key) = &draft.map_key { request["partOpacityMapKey"] = json!(key); }
            self.command(request);
            if self.controller.snapshot()["revision"].as_u64() != Some(revision) { self.can3_key_draft = None; }
        } else if discard { self.can3_key_draft = None; }
    }

    fn can3_tree(&mut self, ui: &mut egui::Ui) {
        let mut picked = None;
        let mut delete = None;
        let mut delete_track = None;
        let mut delete_curve = None;
        let mut new_key = None;
        let mut delete_key = None;
        let revision = self.controller.snapshot()["revision"].as_u64().unwrap_or_default();
        let can_edit = !self.closing && !self.controller.draft_dirty() && self.can3_delete.is_none()
            && self.unsaved.is_none() && self.tools.prompt.is_none();
        ui.add_enabled_ui(!self.closing && self.unsaved.is_none() && self.tools.prompt.is_none() && self.can3_delete.is_none(), |ui| {
            ui.strong("New CAN3 scene");
            let label = ui.label("New scene name");
            ui.add(egui::TextEdit::singleline(&mut self.can3_scene_draft.name)).labelled_by(label.id);
            ui.horizontal(|ui| {
                let label = ui.label("New scene FPS");
                ui.add(egui::DragValue::new(&mut self.can3_scene_draft.fps).speed(0.1)).labelled_by(label.id);
                let label = ui.label("New scene duration (frames)");
                ui.add(egui::DragValue::new(&mut self.can3_scene_draft.duration_frames).range(0..=i32::MAX)).labelled_by(label.id);
            });
            ui.horizontal(|ui| {
                if ui.add_enabled(can_edit, egui::Button::new("Add CAN3 scene")).clicked() {
                    self.command(json!({"op":"live2d.animation.scene.add", "name":self.can3_scene_draft.name,
                        "fps":self.can3_scene_draft.fps, "durationFrames":self.can3_scene_draft.duration_frames,
                        "expectedRevision":revision}));
                    if self.controller.snapshot()["revision"].as_u64() != Some(revision) {
                        self.can3_scene_draft = Can3SceneDraft::default();
                        self.native_scene_guid = self.controller.snapshot()["model"]["scenes"].as_array()
                            .and_then(|scenes| scenes.last()).and_then(|scene| scene["guid"].as_str()).unwrap_or_default().to_owned();
                        self.seek_frame = 0.0;
                    }
                }
                if ui.add_enabled(self.can3_scene_draft.is_dirty(), egui::Button::new("Discard new scene")).clicked() {
                    self.can3_scene_draft = Can3SceneDraft::default();
                }
            });
        });
        self.can3_track_form(ui, can_edit);
        self.can3_curve_form(ui, can_edit);
        let revision = self.controller.snapshot()["revision"].as_u64().unwrap_or_default();
        let model = &self.controller.snapshot()["model"];
        ui.label(model["name"].as_str().unwrap_or("unnamed"));
        egui::CollapsingHeader::new("Linked model resources").show(ui, |ui| {
            for resource in model["resources"].as_array().into_iter().flatten() {
                ui.label(resource["name"].as_str().unwrap_or(""));
                ui.label(resource["sourceFile"].as_str().unwrap_or(""));
            }
        });
        if let Some(scenes) = model["scenes"].as_array() {
            for scene in scenes {
                let scene_guid = scene["guid"].as_str().unwrap_or("").to_owned();
                egui::CollapsingHeader::new(scene["name"].as_str().unwrap_or("scene"))
                    .id_salt(&scene_guid)
                    .show(ui, |ui| {
                        let name = scene["name"].as_str().unwrap_or("scene");
                        if ui.add_enabled(can_edit, egui::Button::new(format!("Delete scene \"{name}\"..."))).clicked() {
                            delete = Some(SceneDeleteConfirmation {
                                scene_guid:scene_guid.clone(), scene_name:name.to_owned(), expected_revision:revision,
                            });
                        }
                        ui.label(format!("FPS {}, duration {} frames", scene["fps"], scene["durationFrames"]));
                        for track in scene["imageTracks"].as_array().into_iter().flatten() {
                            let track_guid = track["guid"].as_str().unwrap_or_default();
                            let name = track["name"].as_str().unwrap_or(track_guid);
                            egui::CollapsingHeader::new(format!("Image: {name}"))
                                .id_salt((&scene_guid, "image", track_guid)).show(ui, |ui| {
                                    ui.label(format!("Track GUID: {track_guid}"));
                                    ui.label(format!("Image resource GUID: {}", track["resourceGuid"].as_str().unwrap_or_default()));
                                    if ui.add_enabled(can_edit, egui::Button::new(format!("Delete image track \"{name}\"..."))).clicked() {
                                        delete_track = Some(TrackDeleteConfirmation {
                                            scene_guid:scene_guid.clone(), track_guid:track_guid.to_owned(), track_name:name.to_owned(),
                                            resource_guid:track["resourceGuid"].as_str().unwrap_or_default().to_owned(),
                                            details:TrackDeleteDetails::Image, expected_revision:revision,
                                        });
                                    }
                                });
                        }
                        for track in scene["tracks"].as_array().into_iter().flatten() {
                            let track_guid =
                                track["guid"].as_str().unwrap_or("").to_owned();
                            egui::CollapsingHeader::new(
                                track["name"].as_str().unwrap_or(&track_guid),
                            )
                            .id_salt(&track_guid)
                            .show(ui, |ui| {
                                let name = track["name"].as_str().unwrap_or(&track_guid);
                                if ui.add_enabled(can_edit, egui::Button::new(format!("Delete track \"{name}\"..."))).clicked() {
                                    delete_track = Some(TrackDeleteConfirmation {
                                        scene_guid:scene_guid.clone(), track_guid:track_guid.clone(), track_name:name.to_owned(),
                                        resource_guid:track["resourceGuid"].as_str().unwrap_or_default().to_owned(), expected_revision:revision,
                                        details:TrackDeleteDetails::Model {
                                            curve_counts:["parameterCurves", "partOpacityCurves", "legacyPartOpacityCurves", "underscorePartOpacityCurves"]
                                                .map(|field| track[field].as_array().map_or(0, Vec::len)),
                                        },
                                    });
                                }
                                ui.label(format!(
                                    "Start {}, offset {}, duration {}",
                                    track["start"], track["internalOffset"], track["duration"]
                                ));
                                for (family,curve) in ["parameterCurves", "partOpacityCurves", "legacyPartOpacityCurves", "underscorePartOpacityCurves"].into_iter()
                                    .flat_map(|field| track[field].as_array().into_iter().flatten().map(move |curve| (field,curve)))
                                {
                                    let curve_id =
                                        curve["id"].as_str().unwrap_or("").to_owned();
                                    let map_key = curve["mapKey"].as_str();
                                    let curve_label = map_key.map(|key| format!("{curve_id} [{key}]")).unwrap_or_else(|| curve_id.clone());
                                    egui::CollapsingHeader::new(&curve_label)
                                        .id_salt((&track_guid, &curve_id, map_key))
                                        .show(ui, |ui| {
                                            if ui.add_enabled(can_edit && self.can3_key_draft.is_none(),
                                                egui::Button::new(format!("New key \"{curve_label}\"..."))).clicked()
                                            {
                                                new_key = Some(Can3KeyDraft { scene_guid:scene_guid.clone(), track_guid:track_guid.clone(),
                                                    curve_id:curve_id.clone(), map_key:map_key.map(str::to_owned), expected_revision:revision,
                                                    frame:0, value:0.0, curve_type:"LINEAR" });
                                            }
                                            if ui.add_enabled(can_edit, egui::Button::new(format!("Delete curve \"{curve_label}\"..."))).clicked() {
                                                delete_curve = Some(CurveDeleteConfirmation {
                                                    scene_guid:scene_guid.clone(), track_guid:track_guid.clone(), curve_id:curve_id.clone(),
                                                    map_key:map_key.map(str::to_owned), family, keys:curve["points"].as_array().map_or(0,Vec::len),
                                                    expected_revision:revision,
                                                });
                                            }
                                            ui.label(curve["partId"].as_str()
                                                .or_else(|| curve["legacyMapPartId"].as_str())
                                                .or(map_key)
                                                .or_else(|| curve["parameterGuid"].as_str()).unwrap_or(""));
                                            for point in curve["points"]
                                                .as_array()
                                                .into_iter()
                                                .flatten()
                                            {
                                                let frame = point["anchor"]["frame"]
                                                    .as_i64()
                                                    .unwrap_or(0);
                                                let value = point["anchor"]["value"]
                                                    .as_f64()
                                                    .unwrap_or(0.0);
                                                ui.horizontal(|ui| {
                                                    ui.label(format!(
                                                        "frame {frame} = {value}"
                                                    ));
                                                    if ui.small_button(tr("Edit")).clicked() {
                                                        picked = Some((
                                                            scene_guid.clone(),
                                                            track_guid.clone(),
                                                            curve_id.clone(),
                                                            frame,
                                                            map_key.map(str::to_owned),
                                                        ));
                                                    }
                                                    if ui.add_enabled(can_edit, egui::Button::new(format!("Delete key {frame} in \"{curve_label}\""))).clicked() {
                                                        let mut request = json!({"op":"live2d.animation.key.delete", "sceneGuid":scene_guid,
                                                            "trackGuid":track_guid, "curveId":curve_id, "anchorFrame":frame, "expectedRevision":revision});
                                                        if let Some(key) = map_key { request["partOpacityMapKey"] = json!(key); }
                                                        delete_key = Some(request);
                                                    }
                                                });
                                                for handle in ["previous", "next"] {
                                                    let control = &point[handle];
                                                    ui.label(format!(
                                                        "  {handle}: frame {} / {}, value {}",
                                                        control["frame"], control["integerFrame"], control["value"]
                                                    ));
                                                }
                                            }
                                        });
                                }
                            });
                        }
                    });
            }
        } else {
            ui.label("CAN3 model lacks scenes.");
        }
        if let Some((scene, track, curve, frame, map_key)) = picked {
            self.select_anchor_draft(&scene, &track, &curve, frame, map_key.as_deref());
        }
        if let Some(confirmation) = delete {
            self.can3_delete = Some(Can3DeleteConfirmation::Scene(confirmation));
        }
        if let Some(confirmation) = delete_track {
            self.can3_delete = Some(Can3DeleteConfirmation::Track(confirmation));
        }
        if let Some(confirmation) = delete_curve {
            self.can3_delete = Some(Can3DeleteConfirmation::Curve(confirmation));
        }
        if let Some(draft) = new_key { self.can3_key_draft = Some(draft); }
        if let Some(request) = delete_key { self.command(request); }
        self.can3_key_form(ui, can_edit);
    }

    fn can3_delete_dialog(&mut self, ctx: &egui::Context) {
        match self.can3_delete.as_ref() {
            Some(Can3DeleteConfirmation::Scene(_)) => self.can3_scene_delete_dialog(ctx),
            Some(Can3DeleteConfirmation::Track(_)) => self.can3_track_delete_dialog(ctx),
            Some(Can3DeleteConfirmation::Curve(_)) => self.can3_curve_delete_dialog(ctx),
            None => {},
        }
    }

    fn can3_scene_delete_dialog(&mut self, ctx: &egui::Context) {
        let Some(Can3DeleteConfirmation::Scene(pending)) = self.can3_delete.as_ref() else { return };
        let snapshot = self.controller.snapshot();
        let stale = snapshot["documentFormat"] != "live2d.can3"
            || snapshot["revision"].as_u64() != Some(pending.expected_revision);
        let scene = snapshot["model"]["scenes"].as_array()
            .and_then(|scenes| scenes.iter().find(|scene| scene["guid"] == pending.scene_guid));
        let tracks = scene.and_then(|scene| scene["tracks"].as_array());
        let curves: usize = tracks.into_iter().flatten().map(|track| {
            ["parameterCurves", "partOpacityCurves", "legacyPartOpacityCurves", "underscorePartOpacityCurves"]
                .into_iter().map(|field| track[field].as_array().map_or(0, Vec::len)).sum::<usize>()
        }).sum();
        let (mut open, mut cancel, mut confirm) = (true, false, false);
        egui::Window::new("Delete CAN3 scene?").id(egui::Id::new("can3_scene_delete"))
            .open(&mut open).collapsible(false).resizable(false).show(ctx, |ui| {
                ui.label(format!("Scene: {}", pending.scene_name));
                ui.label(format!("GUID: {}", pending.scene_guid));
                ui.label("Deletes this scene and all stored contents. Undo is available.");
                ui.label(format!("{} model tracks and {curves} known curve entries are listed below.", tracks.map_or(0, Vec::len)));
                ui.label(format!("{} image tracks; linked image resources are retained.",
                    scene.and_then(|scene| scene["imageTracks"].as_array()).map_or(0, Vec::len)));
                if stale || scene.is_none() {
                    ui.label("CAN3 changed; cancel and review the scene again before deleting.");
                }
                if self.controller.draft_dirty() {
                    ui.label("Apply or discard the open anchor draft before deleting.");
                }
                ui.horizontal(|ui| {
                    confirm = ui.add_enabled(!stale && scene.is_some() && !self.controller.draft_dirty(),
                        egui::Button::new("Confirm scene deletion")).clicked();
                    cancel = ui.button("Cancel scene deletion").clicked();
                });
            });
        let request = confirm.then(|| json!({"op":"live2d.animation.scene.delete",
            "sceneGuid":pending.scene_guid, "expectedRevision":pending.expected_revision}));
        if cancel || !open {
            self.can3_delete = None;
        } else if let Some(request) = request {
            self.command(request);
            self.can3_delete = None;
        }
    }

    fn can3_track_delete_dialog(&mut self, ctx: &egui::Context) {
        let Some(Can3DeleteConfirmation::Track(pending)) = self.can3_delete.as_ref() else { return };
        let snapshot = self.controller.snapshot();
        let stale = snapshot["documentFormat"] != "live2d.can3"
            || snapshot["revision"].as_u64() != Some(pending.expected_revision);
        let track = snapshot["model"]["scenes"].as_array()
            .and_then(|scenes| scenes.iter().find(|scene| scene["guid"] == pending.scene_guid))
            .and_then(|scene| scene[match pending.details { TrackDeleteDetails::Model { .. } => "tracks", TrackDeleteDetails::Image => "imageTracks" }].as_array())
            .and_then(|tracks| tracks.iter().find(|track| track["guid"] == pending.track_guid));
        let (mut open, mut cancel, mut confirm) = (true, false, false);
        egui::Window::new("Delete CAN3 track?").id(egui::Id::new("can3_track_delete"))
            .open(&mut open).collapsible(false).resizable(false).show(ctx, |ui| {
                ui.label(format!("Track: {}", pending.track_name));
                ui.label(format!("Scene GUID: {}", pending.scene_guid));
                ui.label(format!("Track GUID: {}", pending.track_guid));
                match pending.details {
                    TrackDeleteDetails::Model { curve_counts } => {
                        let curves: usize = curve_counts.iter().sum();
                        ui.label(format!("Resource GUID: {}", pending.resource_guid));
                        ui.label(format!("Deletes this track and all stored contents. {curves} known curve entries are listed below. Undo is available."));
                        ui.label(format!("Parameter: {}, PartOpacity: {}, legacy: {}, underscore: {}.",
                            curve_counts[0], curve_counts[1], curve_counts[2], curve_counts[3]));
                    }
                    TrackDeleteDetails::Image => {
                        ui.label(format!("Image resource GUID: {}", pending.resource_guid));
                        ui.label("Deletes this image track and its stored contents. The linked image resource is retained. Undo is available.");
                    }
                }
                if stale || track.is_none() { ui.label("CAN3 changed; cancel and review the track again before deleting."); }
                if self.controller.draft_dirty() { ui.label("Apply or discard the open anchor draft before deleting."); }
                ui.horizontal(|ui| {
                    confirm = ui.add_enabled(!stale && track.is_some() && !self.controller.draft_dirty(),
                        egui::Button::new("Confirm track deletion")).clicked();
                    cancel = ui.button("Cancel track deletion").clicked();
                });
            });
        let request = confirm.then(|| json!({"op":"live2d.animation.track.delete", "sceneGuid":pending.scene_guid,
            "trackGuid":pending.track_guid, "expectedRevision":pending.expected_revision}));
        if cancel || !open { self.can3_delete = None; }
        else if let Some(request) = request {
            self.command(request);
            self.can3_delete = None;
        }
    }

    fn can3_curve_delete_dialog(&mut self, ctx: &egui::Context) {
        let Some(Can3DeleteConfirmation::Curve(pending)) = self.can3_delete.as_ref() else { return };
        let snapshot = self.controller.snapshot();
        let stale = snapshot["documentFormat"] != "live2d.can3"
            || snapshot["revision"].as_u64() != Some(pending.expected_revision);
        let curve = snapshot["model"]["scenes"].as_array()
            .and_then(|scenes| scenes.iter().find(|scene| scene["guid"] == pending.scene_guid))
            .and_then(|scene| scene["tracks"].as_array())
            .and_then(|tracks| tracks.iter().find(|track| track["guid"] == pending.track_guid))
            .and_then(|track| track[pending.family].as_array())
            .and_then(|curves| curves.iter().find(|curve| curve["id"] == pending.curve_id
                && curve["mapKey"].as_str() == pending.map_key.as_deref()));
        let (mut open, mut cancel, mut confirm) = (true, false, false);
        egui::Window::new("Delete CAN3 curve?").id(egui::Id::new("can3_curve_delete"))
            .open(&mut open).collapsible(false).resizable(false).show(ctx, |ui| {
                ui.label(format!("Scene GUID: {}", pending.scene_guid));
                ui.label(format!("Track GUID: {}", pending.track_guid));
                ui.label(format!("Curve ID: {}", pending.curve_id));
                ui.label(format!("Curve family: {}", pending.family));
                if let Some(key) = &pending.map_key { ui.label(format!("Map key: {key}")); }
                ui.label(format!("Deletes this curve and all its {} keys. Undo is available.", pending.keys));
                if stale || curve.is_none() { ui.label("CAN3 changed; cancel and review the curve again before deleting."); }
                if self.controller.draft_dirty() { ui.label("Apply or discard the open anchor draft before deleting."); }
                ui.horizontal(|ui| {
                    confirm = ui.add_enabled(!stale && curve.is_some() && !self.controller.draft_dirty(),
                        egui::Button::new("Confirm curve deletion")).clicked();
                    cancel = ui.button("Cancel curve deletion").clicked();
                });
            });
        let request = confirm.then(|| {
            let mut request = json!({"op":"live2d.animation.curve.delete", "sceneGuid":pending.scene_guid,
                "trackGuid":pending.track_guid, "curveId":pending.curve_id, "expectedRevision":pending.expected_revision});
            if let Some(key) = &pending.map_key { request["partOpacityMapKey"] = json!(key); }
            request
        });
        if cancel || !open { self.can3_delete = None; }
        else if let Some(request) = request {
            self.command(request);
            self.can3_delete = None;
        }
    }

    fn native_preview_controls(&mut self, ui: &mut egui::Ui, is_animation: bool) {
        ui.heading("Live2D native preview");
        ui.label("Linked files, playback and expressions are session-only; Save writes the source document.");
        let preview = self.controller.snapshot()["nativePlayback"].clone();
        let values = self.lightweight.frozen(self.controller.playing())
            .unwrap_or(&self.controller.snapshot()["values"]).clone();
        ui.label(if is_animation { "CMO3 model path" } else { "CAN3 animation path" });
        ui.text_edit_singleline(&mut self.native_asset_path);
        ui.collapsing("Resource binding", |ui| {
            ui.label("Resource GUID (optional when the CAN3 contains one model)");
            ui.text_edit_singleline(&mut self.native_resource_guid);
            if is_animation {
                for resource in self.controller.snapshot()["model"]["resources"].as_array().into_iter().flatten() {
                    if let Some(guid) = resource["guid"].as_str() {
                        ui.selectable_value(&mut self.native_resource_guid, guid.to_owned(),
                            resource["name"].as_str().unwrap_or(guid));
                    }
                }
            }
        });
        if ui.add_enabled(!self.native_asset_path.trim().is_empty(), egui::Button::new("Attach linked file")).clicked() {
            let mut request = json!({
                "op":if is_animation { "live2d.model.attach" } else { "live2d.animation.attach" },
                "path":self.native_asset_path.trim(),
            });
            if !self.native_resource_guid.trim().is_empty() {
                request["resourceGuid"] = json!(self.native_resource_guid.trim());
            }
            self.command(request);
        }
        if let Some(name) = preview["modelName"].as_str() {
            ui.label(format!("Model: {name}"));
        }
        ui.separator();
        let scenes = preview["scenes"].as_array().cloned().unwrap_or_default();
        ui.collapsing("Pose3", |ui| {
            ui.label("Pose file path (.pose3.json)");
            ui.text_edit_singleline(&mut self.pose_path);
            if ui.add_enabled(!self.pose_path.trim().is_empty(), egui::Button::new("Attach Pose")).clicked() {
                self.command(json!({"op":"live2d.pose.attach","path":self.pose_path.trim()}));
            }
            let pose = self.controller.snapshot()["nativePose"].clone();
            if !pose.is_null() {
                if ui.button("Reset Pose").clicked() { self.command(json!({"op":"live2d.pose.reset"})); }
                for (id, value) in pose["signals"].as_object().into_iter().flatten() {
                    let mut signal = value.as_f64().unwrap_or(0.0);
                    if ui.add(egui::Slider::new(&mut signal, 0.0..=1.0).text(id)).changed() {
                        self.command(json!({"op":"live2d.pose.step","dt":0.5,
                            "signals":pose_slider_signals(&pose, id, signal)}));
                    }
                }
            }
        });
        ui.collapsing("Physics3", |ui| {
            ui.label("Physics file path (.physics3.json)");
            ui.text_edit_singleline(&mut self.native_physics_path);
            if ui.add_enabled(!self.native_physics_path.trim().is_empty(), egui::Button::new("Attach Physics3")).clicked() {
                self.command(json!({"op":"live2d.physics.attach","path":self.native_physics_path.trim()}));
            }
            let physics = self.controller.snapshot()["nativePhysics"].clone();
            if !physics.is_null() {
                if ui.button("Reset Physics3").clicked() {
                    self.command(json!({"op":"live2d.physics.reset"}));
                }
                ui.horizontal(|ui| {
                    ui.label("Step preview: 1/60 s");
                    if ui.button("Step Physics3").clicked() {
                        self.command(json!({"op":"live2d.physics.step","dt":1.0 / 60.0}));
                    }
                    if ui.button("Stabilize").clicked() {
                        self.command(json!({"op":"live2d.physics.stabilize"}));
                    }
                });
                let mut gravity_x = physics["options"]["gravity"]["x"].as_f64().unwrap_or(0.0);
                let mut gravity_y = physics["options"]["gravity"]["y"].as_f64().unwrap_or(-1.0);
                let mut wind_x = physics["options"]["wind"]["x"].as_f64().unwrap_or(0.0);
                let mut wind_y = physics["options"]["wind"]["y"].as_f64().unwrap_or(0.0);
                let mut options_changed = false;
                egui::Grid::new("native-physics-options").show(ui, |ui| {
                    ui.label("Gravity X");
                    options_changed |= ui
                        .add(egui::DragValue::new(&mut gravity_x).speed(0.01))
                        .changed();
                    ui.label("Gravity Y");
                    options_changed |= ui
                        .add(egui::DragValue::new(&mut gravity_y).speed(0.01))
                        .changed();
                    ui.end_row();
                    ui.label("Wind X");
                    options_changed |= ui
                        .add(egui::DragValue::new(&mut wind_x).speed(0.01))
                        .changed();
                    ui.label("Wind Y");
                    options_changed |= ui
                        .add(egui::DragValue::new(&mut wind_y).speed(0.01))
                        .changed();
                });
                if options_changed {
                    self.command(json!({
                        "op":"live2d.physics.options.set",
                        "gravity":{"x":gravity_x,"y":gravity_y},
                        "wind":{"x":wind_x,"y":wind_y}
                    }));
                }
                if let Some(fps) = physics["fps"].as_f64() {
                    ui.label(format!("FPS: {fps}"));
                }
                if let Some(groups) = physics["groups"].as_array() {
                    let ids = groups.iter().filter_map(Value::as_str).collect::<Vec<_>>().join(", ");
                    ui.label(format!("Groups: {ids}"));
                }
                for (id, value) in physics["parameterValues"].as_object().into_iter().flatten() {
                    if let Some(value) = value.as_f64() {
                        ui.label(format!("{id}: {value}"));
                    }
                }
            }
        });
        if !scenes.iter().any(|scene| scene["guid"].as_str() == Some(&self.native_scene_guid)) {
            self.native_scene_guid = scenes.first().and_then(|scene| scene["guid"].as_str()).unwrap_or("").to_owned();
            self.seek_frame = 0.0;
        }
        if !scenes.is_empty() {
            let old_guid = self.native_scene_guid.clone();
            let name = scenes.iter().find(|scene| scene["guid"].as_str() == Some(&self.native_scene_guid))
                .and_then(|scene| scene["name"].as_str()).unwrap_or("Select scene");
            egui::ComboBox::from_id_salt("native-scene").selected_text(name).show_ui(ui, |ui| {
                for scene in &scenes {
                    if let Some(guid) = scene["guid"].as_str() {
                        ui.selectable_value(&mut self.native_scene_guid, guid.to_owned(),
                            scene["name"].as_str().unwrap_or(guid));
                    }
                }
            });
            if self.native_scene_guid != old_guid {
                self.controller.pause();
                self.seek_frame = 0.0;
            }
            let scene = scenes.iter().find(|scene| scene["guid"].as_str() == Some(&self.native_scene_guid));
            let last = scene.and_then(|scene| scene["durationFrames"].as_f64()).unwrap_or(1.0).max(1.0) - 1.0;
            if preview["active"]["sceneGuid"].as_str() == Some(&self.native_scene_guid) {
                ui.label(format!("Frame {:.2} / {last:.0} at {} FPS",
                    preview["active"]["frame"].as_f64().unwrap_or(0.0), preview["active"]["fps"]));
            }
            ui.horizontal(|ui| {
                ui.label("Seek frame");
                ui.add(egui::DragValue::new(&mut self.seek_frame).range(0.0..=last).speed(0.25));
                if ui.button("Seek").clicked() {
                    self.command(json!({"op":"live2d.animation.seek", "sceneGuid":self.native_scene_guid, "frame":self.seek_frame}));
                }
            });
            ui.horizontal(|ui| {
                if ui.add_enabled(!self.controller.playing(), egui::Button::new("Play")).clicked() {
                    let response = self.controller.play_native(&self.native_scene_guid);
                    if response["succeeded"].as_bool() == Some(true) {
                        self.last_tick = Some(Instant::now());
                        self.preview_dirty = true;
                    }
                }
                if ui.add_enabled(self.controller.playing(), egui::Button::new("Pause")).clicked() {
                    self.controller.pause();
                }
                if ui.button("Reset motion").clicked() {
                    self.command(json!({"op":"live2d.animation.reset"}));
                }
                ui.checkbox(&mut self.looping, "Loop");
            });
            ui.label(if self.controller.playing() { "Playing" } else { "Paused" });
        } else {
            ui.label("Attach the matching CMO3/CAN3 to enable timeline playback.");
        }
        ui.separator();
        ui.collapsing("Expressions (.exp3.json)", |ui| {
            ui.label("Expression path");
            ui.text_edit_singleline(&mut self.expression_path);
            ui.horizontal(|ui| {
                ui.label(tr("Name"));
                ui.text_edit_singleline(&mut self.expression_name);
            });
            if ui.button("Import expression").clicked() {
                self.command(json!({"op":"live2d.expression.import", "name":self.expression_name.trim(),
                    "path":self.expression_path.trim()}));
            }
            for expression in preview["expressions"].as_array().into_iter().flatten() {
                if let Some(name) = expression["name"].as_str() {
                    let selected = preview["expressionName"].as_str() == Some(name);
                    if ui.selectable_label(selected, name).clicked() {
                        self.command(json!({"op":"live2d.expression.apply", "name":name}));
                    }
                }
            }
            if ui.button("Reset expression").clicked() {
                self.command(json!({"op":"live2d.expression.reset"}));
            }
        });
        if !is_animation {
            self.native_motion_controls(ui);
        }
        ui.collapsing("Model parameters / facial controls", |ui| {
            self.lightweight.checkbox(ui);
            let label = ui.label("Native parameter filter");
            let mut filter = self.parameter_filter.clone();
            if ui.add(egui::TextEdit::singleline(&mut filter).hint_text("Filter name or ID")).labelled_by(label.id).changed() {
                self.apply_window_request(ui.ctx(), crate::editor_windows::Request::Mcp(
                    crate::editor_windows::McpTarget::ParameterPanel,
                    crate::editor_windows::call_request("editor_native_parameters_set", json!({"filter":filter}))));
            }
            let filter = self.parameter_filter.to_lowercase();
            let parameters = preview["parameters"].as_array().cloned().unwrap_or_else(|| {
                self.controller.snapshot()["model"]["parameters"].as_array().cloned().unwrap_or_default()
            });
            for parameter in parameters {
                let Some(id) = parameter["id"].as_str() else { continue };
                let name = parameter["name"].as_str().filter(|name| !name.trim().is_empty()).unwrap_or(id);
                if !filter.is_empty() && !id.to_lowercase().contains(&filter) && !name.to_lowercase().contains(&filter) {
                    continue;
                }
                let min = parameter["minimum"].as_f64().unwrap_or(0.0);
                let max = parameter["maximum"].as_f64().unwrap_or(1.0);
                let mut value = values[id].as_f64().or_else(|| parameter["default"].as_f64()).unwrap_or(0.0);
                ui.push_id(id, |ui| {
                    if ui.add(egui::Slider::new(&mut value, min..=max).text(name)).on_hover_text(id).changed() {
                        self.command(json!({"op":"live2d.parameter.set", "parameterId":id, "value":value}));
                    }
                });
            }
        });
    }

    fn native_motion_controls(&mut self, ui: &mut egui::Ui) {
        ui.collapsing("Runtime motions (.motion3.json)", |ui| self.motion3_panel(ui));
    }

    /// The Motion3 panel (INX documents and native CMO3 clips).
    fn motion3_panel(&mut self, ui: &mut egui::Ui) {
        let outcome = self.motion3.show(ui, &mut self.controller, &mut self.looping);
        if outcome.changed {
            self.preview_dirty = true;
        }
        if outcome.play_started {
            self.last_tick = Some(Instant::now());
        }
    }

    fn cmo3_summary(&mut self, ui: &mut egui::Ui) {
        let model = &self.controller.snapshot()["model"];
        ui.label(format!(
            "Model: {}",
            model["name"].as_str().unwrap_or("unnamed")
        ));
        let parameters = model["parameters"].as_array().map_or(0, |list| list.len());
        let sources = model["sources"].as_array().map_or(0, |list| list.len());
        let forms: usize = model["sources"]
            .as_array()
            .into_iter()
            .flatten()
            .map(|source| source["forms"].as_array().map_or(0, |list| list.len()))
            .sum();
        ui.label(format!("Parameters: {parameters}"));
        ui.label(format!("Sources: {sources}"));
        ui.label(format!("Forms: {forms}"));
        ui.label("Native source summary; preview controls do not edit the saved model.");
    }

    fn draft_editor(
        &mut self,
        ui: &mut egui::Ui,
        draft: Option<OwnedDraft>,
        dirty: bool,
        stale: bool,
    ) {
        let Some(draft) = draft else {
            ui.label("No draft selected. Edit an INX node or a CAN3 anchor.");
            return;
        };
        match &draft {
            OwnedDraft::NodeName { id, original } => {
                ui.label(format!("Rename node {id} (was \"{original}\")"));
                if ui.text_edit_singleline(&mut self.draft_name).changed() {
                    self.remote_quit.cancel("node_name_draft_changed");
                    self.controller.set_draft_name(self.draft_name.clone());
                }
            }
            OwnedDraft::Can3Anchor {
                curve_id,
                map_key,
                frame,
                original,
            } => {
                ui.label(format!(
                    "Anchor value for {curve_id} at frame {frame} (was {original})"
                ));
                if let Some(key) = map_key { ui.label(format!("Part opacity map key: {key}")); }
                if ui
                    .add(egui::DragValue::new(&mut self.draft_value).speed(0.01))
                    .changed()
                {
                    self.remote_quit.cancel("anchor_value_draft_changed");
                    self.controller.set_draft_value(self.draft_value);
                }
            }
        }
        let finite = match &draft {
            OwnedDraft::Can3Anchor { .. } => self.draft_value.is_finite(),
            OwnedDraft::NodeName { .. } => true,
        };
        ui.horizontal(|ui| {
            if ui
                .add_enabled(dirty && !stale && finite, egui::Button::new(tr("Apply")))
                .clicked()
            {
                let response = self.controller.apply_draft();
                if response["succeeded"].as_bool() == Some(true) {
                    self.notice.clear();
                    self.preview_dirty = true;
                }
            }
            if ui.button(tr("Discard")).clicked() {
                self.remote_quit.cancel("draft_discarded");
                self.controller.discard_draft();
                self.notice.clear();
            }
        });
    }

    fn history_section(&mut self, ui: &mut egui::Ui) {
        let history = self.controller.snapshot()["history"].clone();
        let states = history["states"].as_array().cloned().unwrap_or_default();
        let position = history["position"].as_u64().unwrap_or(0);
        let limit = history["limit"].as_u64().unwrap_or(0);
        let revision = history["revision"].as_u64().unwrap_or(0);
        egui::CollapsingHeader::new("Undo history")
            .default_open(true)
            .show(ui, |ui| {
                ui.label(format!(
                    "{} of {limit} retained states, current {position}",
                    states.len()
                ));
                for state in states {
                    let Some(index) = state["index"].as_u64() else {
                        continue;
                    };
                    let label = match state["label"].as_str() {
                        Some(label) if !label.is_empty() => format!("{index}: {label}"),
                        _ if index == 0 => "Oldest retained state".to_owned(),
                        _ => format!("Retained state {index}"),
                    };
                    let current = state["current"].as_bool() == Some(true);
                    let applied = state["applied"].as_bool() == Some(true);
                    let text = if applied {
                        egui::RichText::new(label)
                    } else {
                        egui::RichText::new(label).weak()
                    };
                    if ui.selectable_label(current, text).clicked() {
                        self.command(json!({
                            "op": "history.goto",
                            "index": index,
                            "expectedRevision": revision,
                        }));
                    }
                }
                if ui.button("Clear history").clicked() {
                    self.command(json!({ "op": "history.clear" }));
                }
            });
    }
}

fn pose_slider_signals(pose: &Value, id: &str, signal: f64) -> Value {
    let mut signals = serde_json::Map::new();
    if signal > 0.001 {
        for group in pose["groups"].as_array().into_iter().flatten().filter_map(Value::as_array) {
            if group.iter().any(|part| part.as_str() == Some(id)) {
                for peer in group.iter().filter_map(Value::as_str) {
                    signals.insert(peer.to_owned(), json!(0));
                }
            }
        }
    }
    signals.insert(id.to_owned(), json!(signal));
    Value::Object(signals)
}

#[cfg(test)]
mod animation_draft_tests {
    use super::*;

    #[test]
    fn animation_draft_round_trips_through_the_session_as_one_undo() {
        let mut session = soul2d_core::Session::new();
        let run = |session: &mut soul2d_core::Session, request: Value| {
            let response = session.handle_request(&request);
            assert_eq!(response["succeeded"], true, "{response}");
            response["result"].clone()
        };
        let created = run(&mut session, json!({"op":"animation.create", "name":"Wave"}));
        let revision = created["revision"].as_u64().unwrap();
        let mut draft = AnimationDraft::read(
            ("Wave".into(), revision),
            &created["model"]["animations"]["Wave"],
        );
        assert_eq!(
            draft,
            AnimationDraft {
                source: ("Wave".into(), revision),
                length: 60,
                lead_in: -1,
                lead_out: -1,
                additive: false,
                weight: 1.0,
                framerate: 60.0,
                timestep: created["model"]["animations"]["Wave"]["timestep"].as_f64().unwrap(),
                loop_editing: false,
                original: draft.original.clone(),
            }
        );

        draft.length = 100;
        draft.lead_out = 100;
        draft.additive = true;
        draft.weight = 0.5;
        draft.framerate = 25.0;
        let saved = run(&mut session, draft.request());

        let animation = &saved["model"]["animations"]["Wave"];
        assert_eq!(animation["length"], 100);
        assert_eq!(animation["leadIn"], -1);
        assert_eq!(animation["leadOut"], 100);
        assert_eq!(animation["additive"], true);
        assert_eq!(animation["animationWeight"], 0.5);
        assert!((animation["timestep"].as_f64().unwrap() - 0.04).abs() < 1e-6);
        let undone = run(&mut session, json!({"op":"undo"}));
        assert_eq!(undone["model"]["animations"]["Wave"]["length"], 60);
    }

    #[test]
    fn loop_edit_draft_writes_and_undoes_the_flag() {
        let mut session = soul2d_core::Session::new();
        let run = |session: &mut soul2d_core::Session, request: Value| {
            let response = session.handle_request(&request);
            assert_eq!(response["succeeded"], true, "{response}");
            response["result"].clone()
        };
        let created = run(&mut session, json!({"op":"animation.create", "name":"Wave"}));
        let revision = created["revision"].as_u64().unwrap();
        let mut draft = AnimationDraft::read(
            ("Wave".into(), revision),
            &created["model"]["animations"]["Wave"],
        );
        assert!(!draft.loop_editing);
        draft.loop_editing = true;
        let saved = run(&mut session, draft.request());
        assert_eq!(saved["model"]["animations"]["Wave"]["loopEditing"], true);
        let undone = run(&mut session, json!({"op":"undo"}));
        assert!(undone["model"]["animations"]["Wave"].get("loopEditing").is_none());
    }
}

#[cfg(test)]
mod pose_slider_tests {
    use super::*;

    #[test]
    fn selecting_a_later_part_clears_only_its_group() {
        let pose = json!({"groups":[["A","B"],["C","D"]],"signals":{"A":1,"B":0,"C":1,"D":0}});
        assert_eq!(pose_slider_signals(&pose, "B", 1.0), json!({"A":0,"B":1.0}));
        assert_eq!(pose_slider_signals(&pose, "B", 0.0), json!({"B":0.0}));
        assert_eq!(pose_slider_signals(&pose, "linked", 1.0), json!({"linked":1.0}));
    }

}

