    #[test]
    fn export_options_are_built_from_the_draft_fields() {
        let image = ImageDraft {
            path: "out.png".into(),
            camera: "  Close ".into(),
            format: StillFormat::Tga,
            transparency: true,
            overwrite: true,
        };
        assert_eq!(
            image_options(&image),
            ImageExportOptions {
                camera: Some("Close".into()),
                format: StillFormat::Tga,
                transparency: true,
                overwrite: true,
                ..ImageExportOptions::default()
            }
        );
        assert_eq!(image_options(&ImageDraft::default()), ImageExportOptions::default(), "overwrite defaults off");

        let video = VideoDraft { loops: 0, framerate: -1, ..VideoDraft::default() };
        assert_eq!(
            video_options(&video),
            VideoExportOptions { loops: 1, framerate: None, ..VideoExportOptions::default() }
        );
        let video = VideoDraft {
            animation: "Idle".into(),
            loops: 3,
            framerate: 30,
            snap_to_framerate: true,
            overwrite: true,
            ..VideoDraft::default()
        };
        assert_eq!(
            video_options(&video),
            VideoExportOptions {
                animation: Some("Idle".into()),
                loops: 3,
                framerate: Some(30),
                snap_to_framerate: true,
                overwrite: true,
                ..VideoExportOptions::default()
            }
        );
        assert!(!VideoDraft::default().overwrite);
    }

    #[test]
    fn exporting_an_image_writes_the_file_and_never_overwrites_by_default() {
        let dir = temp_dir();
        let mut controller = open_controller(&write_project(&dir, "proj.inx"));
        let before = controller.snapshot().clone();
        let mut draft = ImageDraft { path: dir.join("shot.png").to_str().unwrap().to_owned(), ..ImageDraft::default() };

        let message = run_image_export(&mut controller, &draft).unwrap();
        assert_eq!(message, format!("Exported {} (8x8)", dir.join("shot.png").display()));
        assert_eq!(image::open(dir.join("shot.png")).unwrap().to_rgba8().dimensions(), (8, 8));
        for key in ["revision", "modified", "history", "canUndo"] {
            assert_eq!(controller.snapshot()[key], before[key], "{key}");
        }

        let error = run_image_export(&mut controller, &draft).unwrap_err();
        assert_eq!(error, format!("{} already exists", dir.join("shot.png").display()));
        draft.overwrite = true;
        draft.camera = "Close".into();
        run_image_export(&mut controller, &draft).unwrap();
        assert_eq!(image::open(dir.join("shot.png")).unwrap().to_rgba8().dimensions(), (4, 4));
        draft.camera = "Nope".into();
        assert_eq!(run_image_export(&mut controller, &draft).unwrap_err(), "Camera not found: Nope");
        draft.path.clear();
        assert_eq!(run_image_export(&mut controller, &draft).unwrap_err(), "File path is required");
    }

    #[test]
    fn exporting_frames_writes_numbered_stills_and_the_ffmpeg_vector_is_shown_not_run() {
        let dir = temp_dir();
        let mut controller = open_controller(&write_project(&dir, "proj.inx"));
        let destination = dir.join("frame.png");
        let mut draft = VideoDraft {
            frames_path: destination.to_str().unwrap().to_owned(),
            video_path: dir.join("clip.mp4").to_str().unwrap().to_owned(),
            ..VideoDraft::default()
        };
        // An image track whose file is gone is named in the message.
        let picture = dir.join("bg.png");
        image::RgbaImage::from_pixel(1, 1, image::Rgba([0, 0, 0, 255])).save(&picture).unwrap();
        let add = json!({"op": "animation.image.add", "name": "Idle", "path": picture});
        assert_eq!(controller.with_session(|session| session.handle_request(&add))["succeeded"], true);
        let picture = fs::canonicalize(&picture).unwrap();
        fs::remove_file(&picture).unwrap();
        let message = run_frame_export(&mut controller, &draft).unwrap();
        let first = dir.join("frame-1.png");
        let gone = format!("; left out: image file {} was not found", picture.display());
        assert_eq!(message, format!("Exported 4 frames, first {}{gone}", first.display()));
        for number in 1..=4 {
            assert!(dir.join(format!("frame-{number}.png")).exists(), "frame {number}");
        }
        assert!(!dir.join("frame-5.png").exists());
        assert_eq!(controller.snapshot()["animation"], Value::Null, "preview is left as it was");
        assert!(run_frame_export(&mut controller, &draft).unwrap_err().ends_with("frame-1.png already exists"));

        let line = ffmpeg_preview(&mut controller, &draft).unwrap();
        let clip = dir.join("clip.mp4");
        assert_eq!(
            line,
            format!(
                "ffmpeg [\"-n\", \"-hide_banner\", \"-loglevel\", \"error\", \"-f\", \"rawvideo\", \"-vcodec\", \"rawvideo\", \"-pix_fmt\", \"rgba\", \"-s\", \"8x8\", \
                 \"-r\", \"4\", \"-i\", \"-\", \"-vframes\", \"4\", \"-an\", \"-pix_fmt\", \"yuv420p\", {:?}]{}",
                clip.to_str().unwrap(), gone.replacen("; left out:", "\nleft out:", 1)
            )
        );
        draft.codec = "libx264".into();
        draft.framerate = 30;
        draft.transparency = true;
        draft.ffmpeg_options = "-crf 20".into();
        let line = ffmpeg_preview(&mut controller, &draft).unwrap();
        assert!(line.contains("\"-r\", \"30\""), "{line}");
        assert!(line.contains("\"yuva420p\", \"-vcodec\", \"libx264\", \"-crf\", \"20\""), "{line}");
        // The clip's audio tracks are in the vector, and one whose file is gone is named under it.
        let wav = |name: &str| {
            let path = dir.join(name);
            fs::write(&path, b"RIFF\x24\0\0\0WAVEfmt ").unwrap();
            fs::canonicalize(path).unwrap().to_string_lossy().into_owned()
        };
        let (voice, music) = (wav("voice.wav"), wav("music.wav"));
        for path in [&voice, &music] {
            let add = json!({"op": "animation.audio.add", "name": "Idle", "path": path, "frame": 2});
            assert_eq!(controller.with_session(|session| session.handle_request(&add))["succeeded"], true);
        }
        fs::remove_file(&music).unwrap();
        let line = ffmpeg_preview(&mut controller, &draft).unwrap();
        assert!(line.contains(&format!("{voice:?}")) && !line.contains("\"-an\""), "{line}");
        assert!(line.contains(&format!("\nleft out: audio file {music} was not found")), "{line}");
        assert!(line.ends_with(&format!("image file {} was not found", picture.display())), "{line}");
        draft.video_path.clear();
        assert_eq!(
            ffmpeg_preview(&mut controller, &draft).unwrap_err(),
            "File path is required"
        );
        draft.frames_path = dir.join("frame.jpg").to_str().unwrap().to_owned();
        assert_eq!(
            run_frame_export(&mut controller, &draft).unwrap_err(),
            "frame sequence destination must end in .png or .tga"
        );
    }

