    #[test]
    fn the_presets_the_user_saved_are_offered_for_their_algorithm() {
        let dir = temp_dir();
        let mut controller = open_controller(&write_project(&dir, "proj.inx"));
        let mut draft = AutomeshDraft { algorithm: AutomeshAlgorithm::Contour, ..AutomeshDraft::default() };
        // A session without a settings directory has none, and that is no error.
        assert_eq!(reload_automesh_presets(&mut controller, &mut draft), Ok(()));
        assert_eq!(draft.presets().collect::<Vec<_>>(), AUTOMESH_PRESETS);

        controller.with_session(|session| session.set_config_dir(dir.join("settings")));
        for (name, algorithm) in [("Fine", "contour"), ("Wide", "optimum")] {
            let request = json!({"op": "automesh.preset.save", "name": name, "algorithm": algorithm, "min_distance": 2});
            let saved = controller.core_request(&request);
            assert_eq!(saved["succeeded"], true, "{saved}");
        }
        assert_eq!(controller.snapshot()["canUndo"], false, "a preset is no change of the document");
        assert_eq!(reload_automesh_presets(&mut controller, &mut draft), Ok(()));
        assert_eq!(draft.saved, [("Fine".to_owned(), "contour".to_owned()), ("Wide".to_owned(), "optimum".to_owned())]);
        assert_eq!(draft.presets().skip(6).collect::<Vec<_>>(), ["Fine"]);
        draft.preset = "Fine".into();
        draft.normalize();
        assert_eq!(
            automesh_request(5, &draft),
            json!({"op": "automesh.generate", "id": 5, "algorithm": "contour", "preset": "Fine"})
        );
        let contour = AutomeshDraft { algorithm: AutomeshAlgorithm::Contour, ..AutomeshDraft::default() };
        assert_eq!(run_automesh(&mut controller, 5, &contour).unwrap(), "Auto mesh: 4 vertices, 2 triangles");
        assert_eq!(run_automesh(&mut controller, 5, &draft).unwrap(), "Auto mesh: 9 vertices, 12 triangles");
        draft.algorithm = AutomeshAlgorithm::Optimum;
        assert_eq!(draft.presets().skip(6).collect::<Vec<_>>(), ["Wide"]);
        draft.normalize();
        assert_eq!(draft.preset, "", "Fine is a contour preset");
        draft.algorithm = AutomeshAlgorithm::Grid;
        assert_eq!(draft.presets().count(), 0);

        // A file that is not valid leaves no saved preset and is the error to show.
        std::fs::write(dir.join("settings").join("automesh-presets.json"), b"{").unwrap();
        let error = reload_automesh_presets(&mut controller, &mut draft).unwrap_err();
        assert!(error.starts_with("automesh-presets.json of the settings directory is not valid"), "{error}");
        assert_eq!(draft.saved, []);
    }

    #[test]
    fn a_pending_deform_refresh_is_finished_by_the_frame_driver() {
        let mut controller = EditorController::new();
        fn call(controller: &mut EditorController, request: Value) -> Value {
            let response = controller.core_request(&request);
            assert_eq!(response["succeeded"], true, "{request}: {response}");
            response["result"].clone()
        }
        assert!(!drive_deform(&mut controller), "nothing is pending in a new document");
        let rig = call(&mut controller, json!({"op":"node.create","className":"DepthRigRoot","name":"Rig"}))["created"][0]["uuid"].clone();
        let bone = call(&mut controller, json!({"op":"node.create","className":"DepthBone","name":"Bone","parents":[rig],
            "restHead":[0.0,0.0,0.0],"restTail":[0.0,100.0,0.0]}))["created"][0]["uuid"].clone();
        let grid = call(&mut controller, json!({"op":"node.create","className":"GridDeformer","name":"Grid"}))["created"][0]["uuid"].clone();
        call(&mut controller, json!({"op":"deformer.define_grid","nodes":[grid],"axisX":[0.0,1.0],"axisY":[0.0,1.0]}));
        call(&mut controller, json!({"op":"rig.add_source","root":rig,"target":grid,"bone":bone}));
        let parameter = call(&mut controller, json!({"op":"parameter.create","name":"Pose","dimensions":1,"min":[0.0,0.0],"max":[1.0,1.0]}))["uuid"].clone();
        // Swap in a grid of 262145 vertices, which is over the refresh budget of one step. The session is
        // replaced directly: the controller refuses `new` while the document has unsaved changes.
        let mut model = call(&mut controller, json!({"op":"snapshot"}))["model"].clone();
        fn set_axes(node: &mut Value, id: &Value, xs: &[f64], ys: &[f64]) {
            if node["uuid"] == *id {
                node["grid_axis_x"] = json!(xs);
                node["grid_axis_y"] = json!(ys);
            }
            for child in node["children"].as_array_mut().into_iter().flatten() {
                set_axes(child, id, xs, ys);
            }
        }
        let xs: Vec<f64> = (0..5).map(f64::from).collect();
        let ys: Vec<f64> = (0..52_429).map(f64::from).collect();
        set_axes(&mut model["nodes"], &grid, &xs, &ys);
        controller.with_session(|session| session.handle_request(&json!({"op":"new","model":model})));
        call(&mut controller, json!({"op":"binding.set_trs","parameter":parameter,"nodes":[bone],"key":[1,0],"translation":[4.0,0.0]}));
        assert_eq!(controller.snapshot()["deformPending"], true);
        let refused = controller.core_request(&json!({"op":"parameter.create","dimensions":1}));
        assert_eq!(refused["succeeded"], false, "edits wait for the refresh");
        let mut steps = 0;
        while drive_deform(&mut controller) {
            steps += 1;
            assert!(steps < 100, "the refresh does not finish");
        }
        assert!(steps >= 1);
        assert_eq!(controller.snapshot()["deformPending"], false);
        assert_eq!(controller.core_request(&json!({"op":"parameter.create","dimensions":1}))["succeeded"], true);
    }

