    #[test]
    fn the_export_panel_warns_while_the_exported_animation_is_frozen() {
        let warned = |frozen: &[String], animation: &str| {
            let ctx = egui::Context::default();
            ctx.enable_accesskit();
            let (mut tools, _) = ToolsState::load(Err("test".to_owned()));
            tools.expanded = true;
            tools.video.animation = animation.to_owned();
            let (cameras, animations) = (vec!["Main".to_owned()], vec!["Idle".to_owned(), "Walk".to_owned()]);
            let view = ToolsView { inx: true, cameras: &cameras, animations: &animations, frozen, automesh_target: None };
            let output = ctx.run(egui::RawInput::default(), |ctx| {
                egui::CentralPanel::default().show(ctx, |ui| draw_tools(ui, &mut tools, &view, &mut ToolsOutput::default()));
            });
            let update = output.platform_output.accesskit_update.expect("accesskit is enabled");
            let notice = "Freeze is on: frozen lanes hold their frame in the export.";
            update.nodes.iter().any(|(_, node)| node.value() == Some(notice) || node.label().as_deref() == Some(notice))
        };
        let idle = ["Idle".to_owned()];
        assert!(warned(&idle, ""), "(first) exports Idle");
        assert!(warned(&idle, "Idle"));
        assert!(!warned(&idle, "Walk"));
        assert!(!warned(&[], ""));
    }

    #[test]
    fn the_new_controls_expose_accessibility_names() {
        let ctx = egui::Context::default();
        ctx.enable_accesskit();
        let (mut tools, _) = ToolsState::load(Err("test".to_owned()));
        tools.expanded = true;
        tools.automesh.algorithm = AutomeshAlgorithm::Contour;
        tools.ffmpeg_line = "ffmpeg [\"-y\"]".to_owned();
        let prompt = RestorePrompt { project: "/p/proj.inx".to_owned(), backups: 2 };
        let cameras = vec!["Main".to_owned()];
        let animations = vec!["Idle".to_owned()];
        let view = ToolsView { inx: true, cameras: &cameras, animations: &animations, frozen: &[], automesh_target: Some(5) };
        let mut out = ToolsOutput::default();
        let output = ctx.run(egui::RawInput::default(), |ctx| {
            egui::CentralPanel::default().show(ctx, |ui| draw_tools(ui, &mut tools, &view, &mut out));
            assert_eq!(draw_restore_prompt(ctx, &prompt), None);
        });
        assert_eq!(out, ToolsOutput::default(), "drawing alone triggers nothing");
        let update = output.platform_output.accesskit_update.expect("accesskit is enabled");
        use egui::accesskit::Role;
        for (_, node) in &update.nodes {
            if matches!(node.role(), Role::Button | Role::CheckBox | Role::ComboBox | Role::SpinButton | Role::TextInput) {
                // Combo boxes, spin buttons and text fields are named by their label widget.
                let named = node.label().is_some_and(|label| !label.is_empty()) || !node.labelled_by().is_empty();
                assert!(named, "unlabelled {:?} control {:?}", node.role(), node.value());
            }
        }
        let labels: Vec<String> = update
            .nodes
            .iter()
            .flat_map(|(_, node)| [node.label(), node.value()])
            .flatten()
            .map(str::to_owned)
            .collect();
        for expected in [
            "Tools", "Autosave settings", "Enable autosave", "Autosave interval (minutes)", "Autosave file limit",
            "Auto mesh", "Algorithm", "Preset", "Generate mesh",
            "Export image", "Image path", "Image camera", "Image format", "Allow Transparency",
            "Overwrite existing files", "Export frames", "Frames animation", "Loops", "Frames path (.png or .tga)",
            "Overwrite existing files (frames)", "Show ffmpeg command", "Video file", "Codec",
            "Restore", "Discard", "Cancel", "Restore Autosave",
        ] {
            assert!(labels.iter().any(|label| label == expected), "missing {expected:?} in {labels:?}");
        }
    }
    // -------------------------------------------------------------- PSD import and merge

    /// A layered PSD with solid layers; `layers` are in file order (bottom to top).
    mod psd_fixture {
        pub struct Layer {
            pub name: &'static str,
            pub rect: [i32; 4], // top, left, bottom, right
            pub rgba: [u8; 4],
            /// Group kind: 3 is a closing divider, 1 an open folder; solid layers have none.
            pub group: Option<u32>,
        }

        pub fn solid(name: &'static str, rect: [i32; 4], rgba: [u8; 4]) -> Layer {
            Layer { name, rect, rgba, group: None }
        }

        pub fn group(name: &'static str, kind: u32) -> Layer {
            Layer { name, rect: [0; 4], rgba: [0; 4], group: Some(kind) }
        }

        fn raw(pixels: &[u8]) -> Vec<u8> {
            [&0u16.to_be_bytes()[..], pixels].concat()
        }

        fn record(layer: &Layer) -> (Vec<u8>, Vec<Vec<u8>>) {
            let [top, left, bottom, right] = layer.rect;
            let count = ((bottom - top) * (right - left)) as usize;
            let channels: Vec<(i16, Vec<u8>)> = (0..4)
                .map(|channel| {
                    let id = if channel == 3 { -1 } else { channel as i16 };
                    (id, raw(&vec![if layer.group.is_some() { 0 } else { layer.rgba[channel] }; count]))
                })
                .collect();
            let mut out = Vec::new();
            for value in layer.rect {
                out.extend(value.to_be_bytes());
            }
            out.extend((channels.len() as u16).to_be_bytes());
            for (id, data) in &channels {
                out.extend(id.to_be_bytes());
                out.extend((data.len() as u32).to_be_bytes());
            }
            out.extend_from_slice(b"8BIM");
            out.extend_from_slice(if layer.group.is_some() { b"pass" } else { b"norm" });
            out.extend([255, 0, 0, 0]);
            let mut extra = 0u32.to_be_bytes().to_vec(); // no mask
            extra.extend(0u32.to_be_bytes()); // no blending ranges
            extra.push(layer.name.len() as u8);
            extra.extend_from_slice(layer.name.as_bytes());
            while extra.len() % 4 != 0 {
                extra.push(0);
            }
            if let Some(kind) = layer.group {
                extra.extend_from_slice(b"8BIMlsct");
                extra.extend(4u32.to_be_bytes());
                extra.extend(kind.to_be_bytes());
            }
            out.extend((extra.len() as u32).to_be_bytes());
            out.extend(extra);
            (out, channels.into_iter().map(|(_, data)| data).collect())
        }

        pub fn psd(width: u32, height: u32, layers: &[Layer]) -> Vec<u8> {
            let mut info = (layers.len() as i16).to_be_bytes().to_vec();
            let mut pixels = Vec::new();
            for layer in layers {
                let (header, data) = record(layer);
                info.extend(header);
                pixels.extend(data.concat());
            }
            info.extend(pixels);
            if info.len() % 2 == 1 {
                info.push(0);
            }
            let mut body = (info.len() as u32).to_be_bytes().to_vec();
            body.extend(info);
            let mut out = b"8BPS".to_vec();
            out.extend(1u16.to_be_bytes());
            out.extend([0; 6]);
            out.extend(4u16.to_be_bytes());
            out.extend(height.to_be_bytes());
            out.extend(width.to_be_bytes());
            out.extend(8u16.to_be_bytes());
            out.extend(3u16.to_be_bytes());
            out.extend(0u32.to_be_bytes()); // colour mode data
            let resource = [&b"8BIM"[..], &1005u16.to_be_bytes(), &[0, 0], &4u32.to_be_bytes(), &[1, 2, 3, 4]].concat();
            out.extend((resource.len() as u32).to_be_bytes());
            out.extend(resource);
            out.extend((body.len() as u32).to_be_bytes());
            out.extend(body);
            out.extend([0, 0, 1, 2, 3, 4]);
            out
        }
    }

