    /// A stored-only Krita file with solid single-tile layers; layers are listed top to bottom.
    mod kra_fixture {
        pub enum K {
            Layer(&'static str, [i32; 4], [u8; 4]),
            Group(&'static str, Vec<K>),
        }

        fn zip(members: &[(String, Vec<u8>)]) -> Vec<u8> {
            let (mut out, mut directory) = (Vec::new(), Vec::new());
            for (name, data) in members {
                let mut common = vec![0, 0, 0, 0, 0, 0, 0, 0];
                common.extend_from_slice(&crc32fast::hash(data).to_le_bytes());
                common.extend_from_slice(&(data.len() as u32).to_le_bytes());
                common.extend_from_slice(&(data.len() as u32).to_le_bytes());
                common.extend_from_slice(&(name.len() as u16).to_le_bytes());
                common.extend_from_slice(&0u16.to_le_bytes());
                let offset = out.len() as u32;
                out.extend_from_slice(&0x0403_4b50u32.to_le_bytes());
                out.extend_from_slice(&20u16.to_le_bytes());
                out.extend_from_slice(&common);
                out.extend_from_slice(name.as_bytes());
                out.extend_from_slice(data);
                directory.extend_from_slice(&0x0201_4b50u32.to_le_bytes());
                directory.extend_from_slice(&[20, 0, 20, 0]);
                directory.extend_from_slice(&common);
                directory.extend_from_slice(&[0; 10]);
                directory.extend_from_slice(&offset.to_le_bytes());
                directory.extend_from_slice(name.as_bytes());
            }
            let directory_offset = out.len() as u32;
            out.extend_from_slice(&directory);
            out.extend_from_slice(&0x0605_4b50u32.to_le_bytes());
            out.extend_from_slice(&[0; 4]);
            out.extend_from_slice(&(members.len() as u16).to_le_bytes());
            out.extend_from_slice(&(members.len() as u16).to_le_bytes());
            out.extend_from_slice(&(directory.len() as u32).to_le_bytes());
            out.extend_from_slice(&directory_offset.to_le_bytes());
            out.extend_from_slice(&0u16.to_le_bytes());
            out
        }

        /// One tile at (0,0), planar BGRA, LZF literal runs only.
        fn tile_file(w: usize, h: usize, rgba: [u8; 4]) -> Vec<u8> {
            let planes: Vec<u8> = [rgba[2], rgba[1], rgba[0], rgba[3]].iter().flat_map(|&v| vec![v; w * h]).collect();
            let mut packed = Vec::new();
            for run in planes.chunks(32) {
                packed.push((run.len() - 1) as u8);
                packed.extend_from_slice(run);
            }
            let mut out = format!(
                "VERSION 2\nTILEWIDTH {w}\nTILEHEIGHT {h}\nPIXELSIZE 4\nDATA 1\n0,0,LZF,{}\n",
                packed.len() + 1
            )
            .into_bytes();
            out.push(1);
            out.extend_from_slice(&packed);
            out
        }

        fn xml(layers: &[K], files: &mut Vec<(String, Vec<u8>)>) -> String {
            let mut out = String::new();
            for layer in layers {
                match layer {
                    K::Layer(name, [top, left, bottom, right], rgba) => {
                        let file = format!("layer{}", files.len() + 1);
                        files.push((format!("doc/layers/{file}"), tile_file((right - left) as usize, (bottom - top) as usize, *rgba)));
                        out += &format!(
                            "<layer name=\"{name}\" nodetype=\"paintlayer\" uuid=\"{{{file}}}\" filename=\"{file}\" \
                             colorspacename=\"RGBA\" visible=\"1\" opacity=\"255\" compositeop=\"normal\" x=\"{left}\" y=\"{top}\"/>"
                        );
                    }
                    K::Group(name, children) => {
                        let inner = xml(children, files);
                        out += &format!(
                            "<layer name=\"{name}\" nodetype=\"grouplayer\" uuid=\"{{g-{name}}}\" visible=\"1\" opacity=\"255\" \
                             collapsed=\"0\" x=\"0\" y=\"0\" compositeop=\"normal\"><layers>{inner}</layers></layer>"
                        );
                    }
                }
            }
            out
        }

        pub fn kra(width: u32, height: u32, layers: &[K]) -> Vec<u8> {
            let mut files = Vec::new();
            let inner = xml(layers, &mut files);
            let maindoc = format!(
                "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<DOC xmlns=\"http://www.calligra.org/DTD/krita\" \
                 kritaVersion=\"5.2.2\" syntaxVersion=\"2.0\"><IMAGE name=\"doc\" width=\"{width}\" height=\"{height}\" \
                 colorspacename=\"RGBA\" mime=\"application/x-kra\"><ProjectionBackgroundColor ColorData=\"255,255,255,255\"/>\
                 <layers>{inner}</layers></IMAGE></DOC>"
            );
            let mut members =
                vec![("mimetype".to_owned(), b"application/x-krita".to_vec()), ("maindoc.xml".to_owned(), maindoc.into_bytes())];
            members.extend(files);
            zip(&members)
        }
    }

