    #[test]
    fn the_import_options_start_from_the_d_settings() {
        let mut store = app_settings::Settings::new_user_defaults();
        // D's defaults: ask (the checkbox is the question, so it starts checked) and replace groups by Node.
        assert_eq!(ImportDraft::from_settings(&store), ImportDraft { group_type: "Node".into(), ..ImportDraft::default() });
        store.set("KeepLayerFolder", "NotPreserve".to_owned()).unwrap();
        store.set("LayerGroupReplacement", "Composite".to_owned()).unwrap();
        let draft = ImportDraft::from_settings(&store);
        assert_eq!((draft.keep_structure, draft.group_type.as_str()), (false, "Composite"));
        store.set("KeepLayerFolder", "Preserve".to_owned()).unwrap();
        store.set("LayerGroupReplacement", "Part".to_owned()).unwrap();
        let draft = ImportDraft::from_settings(&store);
        assert_eq!((draft.keep_structure, draft.group_type.as_str()), (true, "Node"), "an unusable type falls back");
        assert_eq!(ToolsState::load(Err("test".to_owned())).0.import.group_type, "Node");
    }

    #[test]
    fn import_requests_need_a_path_and_carry_the_options() {
        assert_eq!(import_request(&ImportDraft::default()).unwrap_err(), "Enter the path of a PSD or Krita file");
        let draft = ImportDraft { path: "  a.psd ".into(), keep_structure: false, group_type: "Composite".into() };
        assert_eq!(
            import_request(&draft).unwrap(),
            json!({"op": "import.psd", "path": "a.psd", "keepStructure": false, "layerGroupNodeType": "Composite"})
        );
        assert_eq!(
            import_request(&ImportDraft { path: "a.psd".into(), ..ImportDraft::default() }).unwrap(),
            json!({"op": "import.psd", "path": "a.psd", "keepStructure": true, "layerGroupNodeType": "DynamicComposite"})
        );
    }

    #[test]
    fn the_extension_of_the_typed_path_picks_psd_or_krita() {
        let request = |path: &str| import_request(&ImportDraft { path: path.into(), ..ImportDraft::default() });
        assert_eq!(request("a.kra").unwrap()["op"], "import.kra");
        assert_eq!(request(" /x/My Art.KRA ").unwrap()["op"], "import.kra");
        assert_eq!(request("/x/y.PSD").unwrap()["op"], "import.psd");
        for path in ["a.txt", "a", "a.psd.bak", "kra", ".kra"] {
            assert_eq!(request(path).unwrap_err(), "Enter the path of a .psd or .kra file", "{path}");
        }
        let plan = |path: &str| merge_plan_request(&MergeDraft { path: path.into(), ..MergeDraft::default() });
        assert_eq!(plan("m.kra").unwrap()["op"], "merge.kra.plan");
        assert_eq!(plan("m.psd").unwrap()["op"], "merge.psd.plan");
        assert!(plan("m.png").is_err());
        let rows = vec![MergeRow { index: 0, name: "Body".into(), path: "/Body".into(), matched: String::new(),
            action: LayerAction::Add, part: None }];
        let draft = MergeDraft { path: "ignored".into(), rows, planned: Some(("m.kra".into(), 1)), ..MergeDraft::default() };
        let apply = merge_apply_request(&draft).unwrap();
        assert_eq!(apply, json!({"op": "merge.kra.apply", "path": "m.kra", "renameMapped": false,
            "retranslateMapped": false, "choices": [{"layer": 0, "action": "add"}]}));
    }

