    #[test]
    fn file_export_runs_the_panel_exports_with_the_panel_options_to_the_typed_path() {
        use crate::editor_windows::ExportKind;
        let dir = temp_dir();
        let mut app = app_with_project(&dir);
        // The panel's camera choice applies; the typed extension picks the still format.
        app.tools.image.camera = "Close".into();
        let tga = dir.join("shot.tga");
        app.run_export(ExportKind::Image, &format!(" {} ", tga.display()));
        assert_eq!(app.tools.info, format!("Exported {} (4x4)", tga.display()));
        assert_eq!(app.tools.image.format, StillFormat::Tga);
        assert!(app.notice.is_empty(), "{}", app.notice);
        assert!(tga.exists());

        // Frames: the first animation, four stills.
        app.run_export(ExportKind::Frames, dir.join("clip.png").to_str().unwrap());
        assert!(app.tools.info.starts_with("Exported 4 frames"), "{}", app.tools.info);
        assert!(dir.join("clip-4.png").exists());

        app.run_export(ExportKind::Inp, dir.join("out.inp").to_str().unwrap());
        assert!(app.tools.info.starts_with("Exported INP: 1 atlases"), "{}", app.tools.info);
        assert!(dir.join("out.inp").exists());
        assert_eq!(app.controller.snapshot()["modified"], false, "exporting leaves the document alone");
    }

    #[test]
    fn file_export_failures_reach_the_notice_and_pause_playback() {
        use crate::editor_windows::ExportKind;
        let dir = temp_dir();
        let mut app = app_with_project(&dir);
        let target = dir.join("shot.png");
        app.run_export(ExportKind::Image, target.to_str().unwrap());
        assert!(app.notice.is_empty());
        // Overwrite stays off: the second run is refused and says why.
        app.run_export(ExportKind::Image, target.to_str().unwrap());
        assert_eq!(app.notice, format!("{} already exists", target.display()));
        app.run_export(ExportKind::Inp, &format!("{}/", dir.display()));
        assert!(!app.notice.is_empty());
        app.controller.play("Idle");
        assert!(app.controller.playing());
        app.run_export(ExportKind::Frames, dir.join("again.png").to_str().unwrap());
        assert!(!app.controller.playing(), "frames are exported from a paused document");
    }

