    #[test]
    fn reset_layout_forgets_the_stored_panel_sizes() {
        use egui::containers::panel::PanelState;
        let ctx = egui::Context::default();
        let rect = egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(777.0, 10.0));
        ctx.data_mut(|data| {
            for id in LAYOUT_PANELS {
                data.insert_persisted(egui::Id::new(id), PanelState { rect });
            }
            data.insert_persisted(egui::Id::new("status"), PanelState { rect });
        });
        reset_layout(&ctx);
        for id in LAYOUT_PANELS {
            assert!(PanelState::load(&ctx, egui::Id::new(id)).is_none(), "{id}");
        }
        assert!(PanelState::load(&ctx, egui::Id::new("status")).is_some(), "only the resizable panels reset");
    }

    #[test]
    fn open_dyslexic_goes_first_only_when_asked_and_is_a_loadable_font() {
        let families = |dyslexic: bool| fonts(dyslexic).families[&egui::FontFamily::Proportional].clone();
        assert_eq!(families(false).first().map(String::as_str), Some("noto-sans"));
        assert_eq!(families(true)[..2], ["open-dyslexic".to_owned(), "noto-sans".to_owned()]);
        assert!(!fonts(false).font_data.contains_key("open-dyslexic"));
        // egui parses the face when it lays text out, and the glyph shapes differ from Noto's.
        let width = |dyslexic: bool| {
            let ctx = egui::Context::default();
            ctx.set_fonts(fonts(dyslexic));
            let mut width = 0.0;
            for _ in 0..2 {
                let _ = ctx.run(egui::RawInput::default(), |ctx| {
                    width = ctx.fonts_mut(|fonts| {
                        fonts.layout_no_wrap("Soul2D".to_owned(), egui::FontId::proportional(20.0), egui::Color32::WHITE).size().x
                    });
                });
            }
            width
        };
        let (plain, dyslexic) = (width(false), width(true));
        assert!(plain > 0.0 && dyslexic > 0.0 && (plain - dyslexic).abs() > 0.5, "{plain} vs {dyslexic}");
    }

    #[test]
    fn exporting_an_inp_reports_atlases_and_scale_and_refuses_to_replace_a_file() {
        let dir = temp_dir();
        let mut controller = open_controller(&write_project(&dir, "proj.inx"));
        let target = dir.join("out.inp");
        let mut draft = InpDraft { path: target.to_str().unwrap().to_owned(), padding: 0, ..InpDraft::default() };
        let message = run_inp_export(&mut controller, &mut draft).unwrap();
        let size = fs::metadata(&target).unwrap().len();
        assert_eq!(message, format!("Exported INP: 1 atlases, {size} bytes to {}", target.display()));
        assert_eq!(draft.last, Some(InpReport { atlases: 1, output_scale: 1.0 }));
        assert_eq!(controller.snapshot()["modified"], false, "the document is untouched");
        assert_eq!(controller.snapshot()["history"]["count"], 0);

        // Without Overwrite the second export is refused and the old report goes away.
        assert_eq!(run_inp_export(&mut controller, &mut draft).unwrap_err(), "export destination already exists");
        assert_eq!(draft.last, None);
        assert_eq!(fs::metadata(&target).unwrap().len(), size);

        // Three 6x4 layers in a 6 pixel atlas force D's uniform output scale of 6/6 - 0.015.
        use psd_fixture::{psd, solid};
        let layers = psd(12, 12, &[
            solid("A", [0, 0, 4, 6], [10, 0, 0, 255]),
            solid("B", [4, 0, 8, 6], [0, 10, 0, 255]),
            solid("C", [8, 0, 12, 6], [0, 0, 10, 255]),
        ]);
        let source = dir.join("three.psd");
        fs::write(&source, layers).unwrap();
        let import = ImportDraft { path: source.to_str().unwrap().to_owned(), ..ImportDraft::default() };
        run_import(&mut controller, &import).unwrap();
        draft.overwrite = true;
        draft.resolution = 6;
        run_inp_export(&mut controller, &mut draft).unwrap();
        // The atlas count is the backend's: ask the session the same question directly.
        let other = dir.join("direct.inp");
        let direct = controller.core_request(&json!({"op": "export.inp", "path": other.to_str().unwrap(),
            "atlasResolution": 6, "padding": 0}));
        let atlases = direct["result"]["atlases"].as_u64().unwrap();
        assert_eq!(draft.last, Some(InpReport { atlases, output_scale: f64::from(1.0f32 - 0.015f32) }));
        assert!(atlases >= 2, "three 6x4 parts cannot share one 6x6 atlas");
    }

    #[test]
    fn merge_rows_default_to_the_plans_binding_and_apply_sends_explicit_choices() {
        let plan = json!({"layers": [
            {"index": 0, "name": "Extra", "path": "/Extra", "rect": [6, 8, 6, 4], "target": null, "matchedBy": null},
            {"index": 1, "name": "Body", "path": "/Body", "rect": [0, 0, 6, 4], "target": 5, "matchedBy": "path"},
        ]});
        let parts = vec![(5, "Body".to_owned()), (7, "Face".to_owned())];
        let rows = merge_rows(&plan, &parts);
        assert_eq!(
            rows,
            [
                MergeRow { index: 0, name: "Extra".into(), path: "/Extra".into(), matched: "no matching Part".into(),
                    action: LayerAction::Add, part: None },
                MergeRow { index: 1, name: "Body".into(), path: "/Body".into(), matched: "Body (5), by path".into(),
                    action: LayerAction::Replace, part: Some(5) },
            ]
        );
        let mut draft = MergeDraft { path: " m.psd ".into(), rename: true, rows, parts, ..MergeDraft::default() };
        assert_eq!(merge_plan_request(&draft).unwrap(), json!({"op": "merge.psd.plan", "path": "m.psd",
            "renameMapped": true, "retranslateMapped": false}));
        assert_eq!(merge_apply_request(&draft).unwrap_err(), "Plan the merge first");
        draft.planned = Some(("m.psd".into(), 3));
        assert_eq!(
            merge_apply_request(&draft).unwrap(),
            json!({"op": "merge.psd.apply", "path": "m.psd", "renameMapped": true, "retranslateMapped": false,
                "choices": [{"layer": 0, "action": "add"}, {"layer": 1, "action": "replace", "part": 5}]})
        );
        draft.rows[0].action = LayerAction::Replace;
        assert_eq!(merge_apply_request(&draft).unwrap_err(), "Choose the Part that layer Extra replaces");
        draft.rows[0].part = Some(7);
        draft.rows[1].action = LayerAction::Ignore;
        assert_eq!(
            merge_apply_request(&draft).unwrap()["choices"],
            json!([{"layer": 0, "action": "replace", "part": 7}, {"layer": 1, "action": "ignore"}])
        );
    }

    #[test]
    fn cancelling_empty_and_nonempty_merge_plans_releases_replacement_and_quit_without_editing() {
        use crate::editor_test_support::Harness;
        use egui::accesskit::Role;

        fn call(app: &mut EditorApp, name: &str) -> Value {
            let message = json!({"jsonrpc":"2.0", "id":"merge-cancel", "method":"tools/call",
                "params":{"name":name, "arguments":{}}});
            app.sync_panel_drafts();
            editor_view!(app, &egui::Context::default())
                .mcp(&mut app.controller, &message, McpOrigin::Client).into_message().unwrap()["result"].clone()
        }

        for empty in [true, false] {
            let dir = temp_dir();
            let mut app = EditorApp::build(None, None, Ok(dir.join("config")));
            let opened = app.controller.core_request(&json!({"op":"open", "path":write_project(&dir, "clean.inx")}));
            assert_eq!(opened["succeeded"], true, "{opened}");
            let path = if empty {
                let path = dir.join("empty.psd");
                fs::write(&path, psd_fixture::psd(1, 1, &[])).unwrap();
                path.to_str().unwrap().to_owned()
            } else {
                merge_psd(&dir)
            };
            app.tools.merge = MergeDraft { path: path.clone(), rename: true, retranslate: true, ..Default::default() };
            let before = app.controller.snapshot().clone();
            run_merge_plan(&mut app.controller, &mut app.tools.merge).unwrap();
            assert_eq!(app.tools.merge.rows.is_empty(), empty);
            assert!(app.tools.merge.planned.is_some() && !app.tools.merge.parts.is_empty());
            for name in ["editor_quit", "new"] {
                let response = call(&mut app, name);
                assert_eq!(response["isError"], true, "{name}: {response}");
            }
            app.guard_replace(PendingAction::Request(json!({"op":"new"})));
            assert_eq!(app.controller.snapshot(), &before, "planning and refusals leave the whole session unchanged");

            let mut out = ToolsOutput::default();
            Harness::new().click(Role::Button, "Cancel merge plan", |ctx| {
                egui::CentralPanel::default().show(ctx, |ui| draw_merge(ui, &mut app.tools, &mut out, true));
            });
            assert_eq!(out, ToolsOutput::default(), "cancellation sends no document operation");
            assert!(app.tools.merge.rows.is_empty() && app.tools.merge.parts.is_empty() && app.tools.merge.planned.is_none());
            assert_eq!((&app.tools.merge.path, app.tools.merge.rename, app.tools.merge.retranslate), (&path, true, true));
            assert_eq!(app.controller.snapshot(), &before, "cancellation preserves model, revision and history");

            let response = call(&mut app, "new");
            assert_eq!(response["isError"], false, "replacement is released: {response}");
            assert_eq!((&app.tools.merge.path, app.tools.merge.rename, app.tools.merge.retranslate), (&path, true, true));
            let response = call(&mut app, "editor_quit");
            assert_eq!(response["isError"], false, "Quit is released: {response}");
            assert_eq!(response["structuredContent"]["quit"]["state"], "accepted");
        }
    }

    #[test]
    fn a_psd_is_imported_and_merged_through_the_controller() {
        let dir = temp_dir();
        let mut controller = EditorController::new();
        let mut import = ImportDraft { path: base_psd(&dir), ..ImportDraft::default() };
        assert_eq!(run_import(&mut controller, &import).unwrap(), "Imported PSD: 4 nodes, 3 textures");
        assert_eq!(controller.snapshot()["modified"], false);

        let mut merge = MergeDraft { path: merge_psd(&dir), ..MergeDraft::default() };
        assert_eq!(run_merge_apply(&mut controller, &mut merge).unwrap_err(), "Plan the merge first");
        assert_eq!(run_merge_plan(&mut controller, &mut merge).unwrap(), "PSD merge plan: 3 layers");
        let rows: Vec<(&str, &str, LayerAction)> =
            merge.rows.iter().map(|row| (row.name.as_str(), row.matched.as_str(), row.action)).collect();
        assert_eq!(
            rows,
            [
                ("Extra", "no matching Part", LayerAction::Add),
                ("Brim", "Brim (4), by path", LayerAction::Replace),
                ("Body", "Body (5), by path", LayerAction::Replace),
            ]
        );
        assert_eq!(merge.parts, [(5, "Body".to_owned()), (4, "Brim".into()), (2, "Face".into())]);
        assert_eq!(controller.snapshot()["history"]["count"], 0, "planning changes nothing");

        // Ignore Body; the other two layers keep their default binding.
        merge.rows[2].action = LayerAction::Ignore;
        let message = run_merge_apply(&mut controller, &mut merge).unwrap();
        assert_eq!(message, "Merged PSD: 1 replaced, 1 added, 4 textures");
        assert!(merge.rows.is_empty() && merge.parts.is_empty() && merge.planned.is_none(), "a used plan is dropped");
        let snapshot = controller.snapshot().clone();
        assert_eq!((snapshot["modified"].clone(), snapshot["history"]["count"].clone()), (json!(true), json!(1)));
        let mut parts = Vec::new();
        collect_parts(&snapshot["model"]["nodes"], &mut parts);
        let names: Vec<&str> = parts.iter().map(|(_, name)| name.as_str()).collect();
        assert_eq!(names, ["Body", "Brim", "Face", "Extra"]);

        // The document has unsaved changes now, so another import is refused by the controller.
        import.path = base_psd(&dir);
        assert_eq!(run_import(&mut controller, &import).unwrap_err(), "Save the current document before replacing it");
        let undone = controller.core_request(&json!({"op": "undo"}));
        assert_eq!((undone["succeeded"].clone(), controller.snapshot()["modified"].clone()), (json!(true), json!(false)));
        assert!(run_import(&mut controller, &import).is_ok());

        // A missing file reports the error and leaves the document alone.
        import.path = dir.join("none.psd").to_str().unwrap().to_owned();
        let revision = controller.snapshot()["revision"].clone();
        assert!(run_import(&mut controller, &import).unwrap_err().contains("could not open PSD file"));
        assert_eq!(controller.snapshot()["revision"], revision);
    }

    #[test]
    fn the_import_status_names_what_was_left_out() {
        assert_eq!(import_losses(&json!({"nodes": 4, "textures": 3})), "");
        let skipped = json!({"visible": true, "types": [{"type": "shapelayer", "count": 2}, {"type": "filelayer", "count": 1}], "other": 4});
        assert_eq!(import_losses(&json!({"skippedLayers": skipped})), ", 7 layers skipped");
        let report = json!({"skippedLayers": skipped, "groupBlendNotApplied": {"count": 2, "groups": []}});
        assert_eq!(import_losses(&report), ", 7 layers skipped, 2 group blend modes not applied");
        let report = json!({"blendModesNotApplied": {"count": 3, "modes": [{"mode": "Hue", "count": 3}], "other": 0}});
        assert_eq!(import_losses(&report), ", 3 blend modes not applied");
    }

    #[test]
    fn a_krita_file_is_imported_and_merged_through_the_controller() {
        let dir = temp_dir();
        let mut controller = EditorController::new();
        let import = ImportDraft { path: base_kra(&dir), ..ImportDraft::default() };
        assert_eq!(run_import(&mut controller, &import).unwrap(), "Imported Krita: 4 nodes, 3 textures");
        assert_eq!(controller.snapshot()["modified"], false);

        let mut merge = MergeDraft { path: merge_kra(&dir), ..MergeDraft::default() };
        assert_eq!(run_merge_plan(&mut controller, &mut merge).unwrap(), "Krita merge plan: 3 layers");
        let rows: Vec<(&str, &str, LayerAction)> =
            merge.rows.iter().map(|row| (row.name.as_str(), row.matched.as_str(), row.action)).collect();
        assert_eq!(
            rows,
            [
                ("Extra", "no matching Part", LayerAction::Add),
                ("Brim", "Brim (4), by path", LayerAction::Replace),
                ("Body", "Body (5), by path", LayerAction::Replace),
            ]
        );
        merge.rows[2].action = LayerAction::Ignore;
        assert_eq!(run_merge_apply(&mut controller, &mut merge).unwrap(), "Merged Krita: 1 replaced, 1 added, 4 textures");
        let snapshot = controller.snapshot().clone();
        assert_eq!((snapshot["modified"].clone(), snapshot["history"]["count"].clone()), (json!(true), json!(1)));

        // The unsaved-changes gate covers the Krita import like the PSD one.
        assert_eq!(run_import(&mut controller, &import).unwrap_err(), "Save the current document before replacing it");

        // A PSD behind a .kra name is a format error, not a silent PSD import.
        let disguised = dir.join("really.kra");
        fs::write(&disguised, fs::read(base_psd(&dir)).unwrap()).unwrap();
        controller.core_request(&json!({"op": "undo"}));
        let wrong = ImportDraft { path: disguised.to_str().unwrap().to_owned(), ..ImportDraft::default() };
        assert!(run_import(&mut controller, &wrong).is_err());
        assert_eq!(controller.snapshot()["history"]["count"], 1);
    }

