    fn write_japanese(config: &Path) {
        let locale = config.join("i18n");
        fs::create_dir_all(&locale).unwrap();
        fs::write(
            locale.join("ja.po"),
            "msgid \"\"\nmsgstr \"Language: ja\\n\"\n\nmsgid \"LANG_NAME\"\nmsgstr \"日本語\"\n\n\
             msgid \"Loops\"\nmsgstr \"ループ\"\n\nmsgid \"Apply\"\nmsgstr \"適用\"\n\nmsgid \"Tools\"\nmsgstr \"ツール\"\n",
        )
        .unwrap();
    }

    #[test]
    fn locale_folders_follow_d_scan_order_per_platform() {
        let config = Path::new("/cfg/i18n");
        let exe = Path::new("/app/bin");
        let none = |_: &str| None;
        let dirs = |platform, env: &dyn Fn(&str) -> Option<String>| locale_dirs(Some(config), Some(exe), platform, env);
        assert_eq!(dirs(Platform::Linux, &none), [PathBuf::from("/cfg/i18n"), PathBuf::from("/app/bin")]);
        assert_eq!(
            dirs(Platform::Linux, &|name| (name == "HERE").then(|| "/tmp/.mount_x".to_owned())),
            [PathBuf::from("/cfg/i18n"), PathBuf::from("/app/bin"), PathBuf::from("/tmp/.mount_x")]
        );
        assert_eq!(dirs(Platform::Windows, &none)[2], PathBuf::from("/app/bin/i18n"));
        assert_eq!(dirs(Platform::MacOs, &none)[2], PathBuf::from("/app/bin/../Resources/i18n"));
        assert_eq!(locale_dirs(None, None, Platform::Linux, &none), Vec::<PathBuf>::new());
    }

    #[test]
    fn choosing_a_language_swaps_the_labels_stores_the_setting_and_survives_a_restart() {
        let _english = EnglishAfter;
        let config = temp_dir();
        write_japanese(&config);
        let (mut tools, problems) = ToolsState::load(Ok(config.clone()));
        assert!(problems.is_empty(), "{problems:?}");
        let japanese = tools.locales.iter().find(|entry| entry.code == "ja").expect("ja.po is found");
        assert_eq!(japanese.name, "日本語");
        assert_eq!((tools.lang.as_str(), tr("Loops")), ("en", "Loops".to_owned()));
        assert_eq!(tools.set_language("xx").unwrap_err(), "Unknown language xx");

        tools.set_language("ja").unwrap();
        assert_eq!((tr("Loops"), tr("Tools"), tr("Not in the catalogue")), ("ループ".into(), "ツール".into(), "Not in the catalogue".into()));
        let stored: Value =
            serde_json::from_str(&fs::read_to_string(app_settings::settings_path(&config)).unwrap()).unwrap();
        assert_eq!(stored["lang"], "ja");
        tools.expanded = true;
        let roles = control_roles(&mut tools);
        for translated in ["ツール", "ループ"] {
            assert!(roles.iter().any(|(_, name)| name == translated), "{translated} in {roles:?}");
        }
        assert!(roles.iter().all(|(_, name)| name != "Loops"), "the English label is gone");
        // Labels that are not msgids stay English.
        assert!(roles.iter().any(|(_, name)| name == "Import PSD/KRA"));

        // A new start reads the setting back.
        install_catalog(Catalog::empty());
        let (restarted, _) = ToolsState::load(Ok(config.clone()));
        assert_eq!((restarted.lang.as_str(), tr("Apply")), ("ja", "適用".to_owned()));

        let mut restarted = restarted;
        restarted.set_language("en").unwrap();
        assert_eq!(tr("Apply"), "Apply");
        let stored: Value =
            serde_json::from_str(&fs::read_to_string(app_settings::settings_path(&config)).unwrap()).unwrap();
        assert_eq!(stored["lang"], "en");
    }

