    #[test]
    fn a_clean_document_and_the_dont_save_setting_replace_without_a_dialog() {
        let (mut app, _) = app("flow-clean");
        app.command(json!({"op": "new"}));
        assert!(app.unsaved.is_none());
        edit(&mut app, "Edited");
        window_shell::set_close_setting(&mut app.tools.store, window_shell::CloseSetting::DontSave).unwrap();
        app.command(json!({"op": "new"}));
        assert!(app.unsaved.is_none(), "SaveProjectOnClose = dontSave never asks");
        assert!(names(&app).is_empty() && !modified(&app));
        // An unknown stored value is treated as Ask and written back as Ask.
        app.tools.store.set("SaveProjectOnClose", "Save".to_owned()).unwrap();
        edit(&mut app, "Again");
        app.command(json!({"op": "new"}));
        assert!(app.unsaved.is_some());
        assert_eq!(app.tools.store.get::<String>("SaveProjectOnClose").unwrap(), "Ask");
    }

