    #[test]
    fn window_close_asks_when_modified_and_closes_after_the_answer() {
        let close = |harness: &mut Harness, app: &mut EditorApp| {
            harness.next_input = Some(Box::new(|input| {
                let mut info = egui::ViewportInfo::default();
                info.events.push(egui::ViewportEvent::Close);
                input.viewports.insert(egui::ViewportId::ROOT, info);
            }));
            harness.frame(Vec::new(), |ctx| app.handle_close_request(ctx));
        };
        let (mut app, _) = app("flow-close");
        let mut harness = Harness::new();
        close(&mut harness, &mut app);
        assert!(app.closing && app.unsaved.is_none(), "a clean document closes at once");

        let (mut app, _) = self::app("flow-close-modified");
        edit(&mut app, "Edited");
        close(&mut harness, &mut app);
        assert!(!app.closing && app.unsaved.is_some());
        answer(&mut app, &mut harness, "Cancel");
        assert!(!app.closing && app.unsaved.is_none());
        close(&mut harness, &mut app);
        answer(&mut app, &mut harness, "Don't Save");
        assert!(app.closing);
        assert_eq!(names(&app), ["Edited"], "closing does not touch the document");

        let (mut app, dir) = self::app("flow-close-save");
        edit(&mut app, "Edited");
        close(&mut harness, &mut app);
        app.unsaved.as_mut().unwrap().dialog.path = dir.join("close.inx").display().to_string();
        answer(&mut app, &mut harness, "Save");
        assert!(app.closing);
        assert_eq!(saved_names(&dir.join("close.inx")), ["Edited"]);

        let (mut app, _) = self::app("flow-close-setting");
        window_shell::set_close_setting(&mut app.tools.store, window_shell::CloseSetting::DontSave).unwrap();
        edit(&mut app, "Edited");
        close(&mut harness, &mut app);
        assert!(app.closing && app.unsaved.is_none());
    }

