    #[test]
    fn native_parameter_filter_mcp_is_transient_and_separate_from_inx() {
        let mut app = app("native-parameter-filter");
        call(&mut app, "editor_parameters_set", json!({"filter":"Blink"}));
        assert_eq!(state(&mut app)["nativeParameterPanel"], Value::Null);
        assert_eq!(refused(&mut app, "editor_native_parameters_set", json!({"filter":"bad"})),
            "the native parameter panel is available only for CMO3 and CAN3 documents");
        let path = temp_dir("native-parameter-filter").join("fixture.cmo3");
        std::fs::write(&path, crate::editor_test_support::cmo3_bytes()).unwrap();
        app.command(json!({"op":"open","path":path}));
        let before = document(&app);
        let settings = std::fs::read(app.tools.store_path.as_ref().unwrap()).ok();
        for filter in ["tEsT", "", "  ", "顔"] {
            let seen = call(&mut app, "editor_native_parameters_set", json!({"filter":filter}));
            assert_eq!(seen["nativeParameterPanel"], json!({"filter":filter}));
            assert_eq!(state(&mut app)["nativeParameterPanel"], seen["nativeParameterPanel"]);
            assert_eq!(app.parameters.filter, "Blink");
        }
        for args in [json!({}), json!({"filter":null}), json!({"filter":1}), json!({"filter":"bad","extra":true})] {
            assert_eq!(rpc(&mut app, "tools/call", json!({"name":"editor_native_parameters_set","arguments":args}))["isError"], true);
            assert_eq!(state(&mut app)["nativeParameterPanel"], json!({"filter":"顔"}));
        }
        assert_eq!(document(&app), before);
        assert_eq!(std::fs::read(app.tools.store_path.as_ref().unwrap()).ok(), settings);
        call(&mut app, "new", json!({}));
        assert_eq!(state(&mut app)["nativeParameterPanel"], Value::Null);
        app.command(json!({"op":"open","path":path}));
        assert_eq!(state(&mut app)["nativeParameterPanel"], json!({"filter":"顔"}));
    }

