    fn replacement_message(app: &EditorApp, tool: &str) -> Value {
        let dir = app.tools.config_dir.as_ref().unwrap().parent().unwrap();
        let arguments = match tool {
            "new" => json!({}),
            "editor_recovery_restore" => json!({"id":SNAPSHOT_NEW}),
            "import_psd" => json!({"path":super::tools_tests::base_psd(dir)}),
            "import_kra" => json!({"path":super::tools_tests::base_kra(dir)}),
            "import_folder" | "FileCommand_ImportImageFolder" => {
                let folder = dir.join("incoming-images");std::fs::create_dir_all(&folder).unwrap();
                image::RgbaImage::from_pixel(2, 2, image::Rgba([10, 20, 30, 255])).save(folder.join("part.png")).unwrap();
                json!({"path":folder})
            }
            _ => {
                let path = dir.join("incoming.inx");std::fs::write(&path, model_bytes()).unwrap();
                if tool == "FileCommand_OpenFile" { json!({"file":path}) } else { json!({"path":path}) }
            }
        };
        json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":tool,"arguments":arguments}})
    }

    #[test]
    fn acp_document_replacement_aliases_wait_for_exact_single_use_consent() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{texts, Harness};
        use egui::accesskit::Role;
        for tool in ["new", "open", "FileCommand_OpenFile", "import_psd", "import_kra", "import_inp", "FileCommand_ImportINP",
            "import_folder", "FileCommand_ImportImageFolder", "editor_recovery_restore"] {
            let mut app = app_with_two_snapshots(&format!("acp-replace-{tool}"));
            let message = replacement_message(&app, tool);
            let before = document(&app);
            let old_path = app.controller.project_path().unwrap().to_path_buf();
            let old_bytes = std::fs::read(&old_path).unwrap();
            let mut approval = HostApproval::default();approval.set_active(true);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true, "{tool}");
            assert_eq!(document(&app), before);
            assert_eq!(app.controller.project_path(), Some(old_path.as_path()));
            let settings = app.tools.store_path.clone();
            let mut harness = Harness::new();
            let output = harness.frame(Vec::new(), |ctx| approval.show(ctx, settings.as_deref()));
            let labels = texts(&output).join("\n");
            let effect = if matches!(tool, "new" | "open" | "FileCommand_OpenFile" | "editor_recovery_restore") { "project-reset" } else { "import" };
            let target = match tool {
                "new" => "Target: New document",
                "import_folder" | "FileCommand_ImportImageFolder" => "Input folder:",
                "editor_recovery_restore" => "Recovery snapshot:",
                _ => "Input file:",
            };
            for label in [format!("Effect: {effect}"), target.into(), "Source document:".into(), "Replaces the current document.".into()] {
                assert!(labels.contains(&label), "{tool}: {label}: {labels}");
            }
            harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, settings.as_deref()));
            for id in [None, Some(Value::Null)] {
                let mut notification = message.clone();notification.as_object_mut().unwrap().remove("id");
                if let Some(id) = id { notification["id"] = id; }
                let response = agent_rpc(&mut app, &mut approval, &notification);
                assert!(response.is_none_or(|reply| reply["result"]["isError"] == true));
                assert_eq!(document(&app), before);
            }
            let other = replacement_message(&app, if tool == "new" { "open" } else { "new" });
            assert_eq!(agent_rpc(&mut app, &mut approval, &other).unwrap()["result"]["isError"], true);
            assert_eq!(document(&app), before);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], false, "{tool}");
            let after = document(&app);
            assert!(app.controller.snapshot()["revision"].as_u64().unwrap() > before[1].as_u64().unwrap(), "{tool}");
            assert_eq!(std::fs::read(&old_path).unwrap(), old_bytes);
            assert_eq!(app.controller.snapshot()["history"]["count"], 0);
            if tool == "new" { assert!(app.controller.snapshot()["model"]["nodes"]["children"].as_array().is_none_or(Vec::is_empty)); }
            if matches!(tool, "open" | "FileCommand_OpenFile") {
                assert_eq!(app.controller.project_path().unwrap(), old_path.with_file_name("incoming.inx"));
            } else { assert!(app.controller.project_path().is_none(), "{tool}"); }
            if tool == "editor_recovery_restore" {
                assert_eq!(app.tools.recovery.as_ref().unwrap().current().unwrap().file_name().unwrap(), SNAPSHOT_NEW);
            }
            let retry = agent_rpc(&mut app, &mut approval, &message).unwrap();
            assert_eq!(retry["result"]["isError"], true);
            assert_eq!(document(&app), after, "a completed grant cannot be reused");
            let error = retry["result"]["content"][0]["text"].as_str().unwrap();
            if error == UNSAVED_REPLACEMENT_MESSAGE {
                assert_eq!(app.controller.snapshot()["modified"], true);
                let output = harness.frame(Vec::new(), |ctx| approval.show(ctx, settings.as_deref()));
                assert!(!crate::editor_test_support::has(&output, Role::Button, "Allow once"));
            } else {
                assert!(error.starts_with("Waiting for host approval"), "{tool}: {error}");
                harness.click(Role::Button, "Deny changes this turn", |ctx| approval.show(ctx, settings.as_deref()));
            }
            assert_eq!(agent_rpc(&mut app, &mut approval, &other).unwrap()["result"]["isError"], true);
            assert_eq!(document(&app), after);
        }
    }

    #[test]
    fn acp_replacement_refuses_existing_file_gates_without_prompting() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{has, Harness};
        use egui::accesskit::Role;
        for tool in ["new", "open", "import_psd", "import_kra", "import_inp", "import_folder", "editor_recovery_restore"] {
            for event in ["draft", "modified", "dialog", "closing"] {
                let mut app = app_with_two_snapshots(&format!("acp-preflight-{tool}-{event}"));
                let message = replacement_message(&app, tool);
                let expected = match event {
                    "draft" => {
                        app.select_node_draft(2);app.controller.set_draft_name("Unapplied".into());FILE_OP_BLOCKED_MESSAGE
                    }
                    "modified" => {
                        assert_eq!(app.controller.core_request(&json!({"op":"node.rename","id":2,"name":"Changed"}))["succeeded"], true);
                        UNSAVED_REPLACEMENT_MESSAGE
                    }
                    "dialog" => { app.unsaved = Some(unsaved_dialog());DIALOG_PENDING_MESSAGE }
                    "closing" => { app.closing = true;CLOSING_MESSAGE }
                    _ => unreachable!(),
                };
                let before = document(&app);
                let path = app.controller.project_path().map(Path::to_owned);
                let mut approval = HostApproval::default();approval.set_active(true);
                let response = agent_rpc(&mut app, &mut approval, &message).unwrap();
                assert_eq!(response["result"]["isError"], true, "{tool}/{event}");
                assert_eq!(response["result"]["content"][0]["text"], expected, "{tool}/{event}");
                assert_eq!(document(&app), before);
                assert_eq!(app.controller.project_path(), path.as_deref());
                let output = Harness::new().frame(Vec::new(), |ctx| approval.show(ctx, app.tools.store_path.as_deref()));
                assert!(!has(&output, Role::Button, "Allow once"), "{tool}/{event}");
            }
        }
    }

    #[test]
    fn acp_replacement_consent_expires_when_the_document_or_dialog_changes() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{has, Harness};
        use egui::accesskit::Role;
        for tool in ["new", "open", "import_folder", "editor_recovery_restore"] {
            for event in ["edit", "replace", "draft", "dialog", "closing"] {
                let mut app = app_with_two_snapshots(&format!("acp-replace-stale-{tool}-{event}"));
                let message = replacement_message(&app, tool);
                let mut approval = HostApproval::default();approval.set_active(true);
                assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
                let mut harness = Harness::new();
                harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, app.tools.store_path.as_deref()));
                match event {
                    "edit" => assert_eq!(app.controller.core_request(&json!({"op":"node.rename","id":2,"name":"Changed"}))["succeeded"], true),
                    "replace" => assert_eq!(app.controller.core_request(&json!({"op":"new"}))["succeeded"], true),
                    "draft" => { app.select_node_draft(2);app.controller.set_draft_name("Unapplied".into()); }
                    "dialog" => app.unsaved = Some(unsaved_dialog()),
                    "closing" => app.closing = true,
                    _ => unreachable!(),
                }
                let before = document(&app);
                let path = app.controller.project_path().map(Path::to_owned);
                let response = agent_rpc(&mut app, &mut approval, &message).unwrap();
                assert_eq!(response["result"]["isError"], true, "{tool}/{event}: {response}");
                assert_eq!(document(&app), before);
                assert_eq!(app.controller.project_path(), path.as_deref());
                let output = harness.frame(Vec::new(), |ctx| approval.show(ctx, app.tools.store_path.as_deref()));
                assert!(!has(&output, Role::Button, "Allow once"), "{tool}/{event}");
            }
        }
    }

    #[cfg(unix)]
    #[test]
    fn acp_replacement_refuses_a_changed_source_path_or_recovery_listing() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{has, Harness};
        use egui::accesskit::Role;
        for tool in ["open", "import_folder", "editor_recovery_restore"] {
            let mut app = app_with_two_snapshots(&format!("acp-replace-path-{tool}"));
            let message = replacement_message(&app, tool);
            let path = if tool == "editor_recovery_restore" { recovery_dir_of(&app).join(SNAPSHOT_NEW) }
                else { PathBuf::from(message["params"]["arguments"]["path"].as_str().unwrap()) };
            let retained = path.with_file_name("retained-source");
            let mut approval = HostApproval::default();approval.set_active(true);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            let mut harness = Harness::new();
            harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, app.tools.store_path.as_deref()));
            std::fs::rename(&path, &retained).unwrap();
            let second = path.with_file_name("other-source");
            if tool == "import_folder" { std::fs::create_dir(&second).unwrap(); }
                else { std::fs::write(&second, model_bytes()).unwrap(); }
            std::os::unix::fs::symlink(&second, &path).unwrap();
            let before = document(&app);
            let response = agent_rpc(&mut app, &mut approval, &message).unwrap();
            assert_eq!(response["result"]["isError"], true, "{tool}");
            assert_eq!(document(&app), before);
            assert!(retained.exists() && second.exists());
            let output = harness.frame(Vec::new(), |ctx| approval.show(ctx, app.tools.store_path.as_deref()));
            assert!(!has(&output, Role::Button, "Allow once"));
            if tool != "import_folder" {
                assert_eq!(std::fs::read(&retained).unwrap(), model_bytes());
                assert_eq!(std::fs::read(&second).unwrap(), model_bytes());
            }
        }
    }

    #[test]
    fn acp_replacement_parse_failure_uses_the_grant_without_replacing_the_document() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{has, Harness};
        use egui::accesskit::Role;
        for tool in ["open", "import_psd", "import_kra", "import_inp", "editor_recovery_restore"] {
            let mut app = app_with_two_snapshots(&format!("acp-replace-invalid-{tool}"));
            let message = replacement_message(&app, tool);
            let path = if tool == "editor_recovery_restore" { recovery_dir_of(&app).join(SNAPSHOT_NEW) }
                else { PathBuf::from(message["params"]["arguments"]["path"].as_str().unwrap()) };
            let before = document(&app);
            let mut approval = HostApproval::default();approval.set_active(true);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            let mut harness = Harness::new();
            harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, app.tools.store_path.as_deref()));
            std::fs::write(&path, b"malformed input after consent").unwrap();
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            assert_eq!(document(&app), before);
            let output = harness.frame(Vec::new(), |ctx| approval.show(ctx, app.tools.store_path.as_deref()));
            assert!(!has(&output, Role::Button, "Allow once"), "a failed attempt consumes the grant");
            let retry = agent_rpc(&mut app, &mut approval, &message).unwrap();
            assert!(retry["result"]["content"][0]["text"].as_str().unwrap().starts_with("Waiting for host approval"), "{tool}: {retry}");
            assert_eq!(document(&app), before);
        }
    }

    #[test]
    fn acp_replacement_denial_applies_to_the_prompt_and_ends_with_it() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{has, Harness};
        use egui::accesskit::Role;
        for tool in ["new", "open", "import_psd", "import_kra", "import_inp", "import_folder", "editor_recovery_restore"] {
            let mut app = app_with_two_snapshots(&format!("acp-replace-denied-{tool}"));
            let message = replacement_message(&app, tool);
            let before = document(&app);
            let mut approval = HostApproval::default();approval.set_active(true);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            let mut harness = Harness::new();
            harness.click(Role::Button, "Deny changes this turn", |ctx| approval.show(ctx, app.tools.store_path.as_deref()));
            for request in [&message, &replacement_message(&app, if tool == "new" { "open" } else { "new" })] {
                let denied = agent_rpc(&mut app, &mut approval, request).unwrap();
                assert_eq!(denied["result"]["isError"], true);
                assert_eq!(denied["result"]["content"][0]["text"], "The host denied protected changes for this prompt");
                assert_eq!(document(&app), before);
            }
            let read = json!({"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"snapshot","arguments":{}}});
            assert_eq!(agent_rpc(&mut app, &mut approval, &read).unwrap()["result"]["isError"], false);
            approval.set_active(false);approval.set_active(true);
            let again = agent_rpc(&mut app, &mut approval, &message).unwrap();
            assert!(again["result"]["content"][0]["text"].as_str().unwrap().starts_with("Waiting for host approval"));
            let output = harness.frame(Vec::new(), |ctx| approval.show(ctx, app.tools.store_path.as_deref()));
            assert!(has(&output, Role::Button, "Allow once"));
            assert_eq!(document(&app), before);
        }
    }

    #[test]
    fn acp_replacement_validates_input_kind_and_recovery_ids_before_prompting() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{has, Harness};
        use egui::accesskit::Role;
        let mut app = app_with_two_snapshots("acp-replace-input-validation");
        let directory = app.tools.config_dir.clone().unwrap();
        let file = app.controller.project_path().unwrap().to_path_buf();
        let missing = directory.join("missing-source");
        let own = recovery_dir_of(&app).join("rust-recovery-current-1.inx");
        std::fs::write(&own, model_bytes()).unwrap();app.tools.recovery.as_mut().unwrap().adopt(own.clone());
        let before = document(&app);
        let mut approval = HostApproval::default();approval.set_active(true);
        for (tool, arguments) in [
            ("open", json!({"path":directory})), ("import_folder", json!({"path":file})),
            ("open", json!({"path":missing})), ("import_folder", json!({"path":missing})),
            ("editor_recovery_restore", json!({"id":"../outside.inx"})),
            ("editor_recovery_restore", json!({"id":own.file_name().unwrap().to_str().unwrap()})),
        ] {
            let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":tool,"arguments":arguments}});
            let result = agent_rpc(&mut app, &mut approval, &message).unwrap();
            assert_eq!(result["result"]["isError"], true);
            assert!(!result["result"]["content"][0]["text"].as_str().unwrap().starts_with("Waiting for host approval"));
            assert_eq!(document(&app), before);
        }
        let output = Harness::new().frame(Vec::new(), |ctx| approval.show(ctx, app.tools.store_path.as_deref()));
        assert!(!has(&output, Role::Button, "Allow once"));
        assert!(own.exists());
    }

