    #[test]
    fn acp_texture_export_asks_for_the_output_folder_then_writes_slot_pngs() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{texts, Harness};
        use egui::accesskit::Role;
        let mut app = export_app("acp-texture-export");
        let source = app.controller.project_path().unwrap().to_owned();
        let source_bytes = std::fs::read(&source).unwrap();
        let before = document(&app);
        let mut approval = HostApproval::default();
        approval.set_active(true);
        let missing = source.parent().unwrap().join("no-such-texture-dir");
        let refused = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"texture_export",
            "arguments":{"directory": missing}}});
        let refused = agent_rpc(&mut app, &mut approval, &refused).unwrap();
        assert_eq!(refused["result"]["isError"], true, "{refused}");
        let refused_text = refused["result"]["content"][0]["text"].as_str().unwrap();
        assert!(!refused_text.contains("Waiting for host approval"), "{refused_text}");
        assert_eq!(document(&app), before);
        let directory = source.parent().unwrap().join("slot-out");
        std::fs::create_dir(&directory).unwrap();
        let directory = std::fs::canonicalize(&directory).unwrap();
        let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"texture_export",
            "arguments":{"directory": &directory}}});
        let parked = agent_rpc(&mut app, &mut approval, &message).unwrap();
        assert_eq!(parked["result"]["isError"], true, "{parked}");
        assert!(!directory.join("slot-0.png").exists());
        assert_eq!(document(&app), before);
        let mut harness = Harness::new();
        let output = harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
        let labels = texts(&output).join("\n");
        assert!(labels.contains(&format!("Output folder: {}", directory.display())), "{labels}");
        assert!(labels.contains("Effect: file-write"), "{labels}");
        harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, None));
        let response = agent_rpc(&mut app, &mut approval, &message).unwrap();
        assert_eq!(response["result"]["isError"], false, "{response}");
        let png = std::fs::read(directory.join("slot-0.png")).unwrap();
        let image = image::load_from_memory_with_format(&png, image::ImageFormat::Png).unwrap();
        assert_eq!(image.to_rgba8().into_raw(), vec![1, 1, 1, 255]);
        assert_eq!(document(&app), before);
        assert_eq!(std::fs::read(&source).unwrap(), source_bytes);
    }

    #[test]
    fn acp_single_file_exports_require_exact_consent_for_the_effective_output_name() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{has, texts, Harness};
        use egui::accesskit::Role;
        for (index, (tool, mut arguments, extension)) in [
            ("export_inp", json!({"overwrite":true}), Some("inp")),
            ("export_image", json!({"format":"png","overwrite":true}), Some("png")),
            ("export_image", json!({"format":"tga","overwrite":true}), Some("tga")),
            ("export_image", json!({"format":"jpeg","overwrite":true}), Some("jpeg")),
            ("export_gif", json!({"animation":"Idle","overwrite":true}), Some("gif")),
            ("view_screenshot", json!({"size":16}), Some("png")),
            ("ViewCommand_SaveScreenshot", json!({"size":16}), Some("png")),
            ("object_export_csv", json!({"overwrite":true}), None),
            ("motion3_export", json!({"name":"Motion"}), None),
            ("Motion3Command_Export", json!({"name":"Motion"}), None),
            ("animation_onion", json!({"name":"Idle","frame":1,"size":16}), None),
            ("live2d_cdi3_export", json!({}), None),
            ("live2d_physics3_export", json!({}), None),
            ("live2d_userdata3_export", json!({}), None),
        ].into_iter().enumerate() {
            let name = format!("acp-export-{index}-{tool}");
            let mut app = if tool.starts_with("live2d_") { runtime_export_app(&name, tool == "live2d_physics3_export") }
                else { export_app(&name) };
            let source = app.controller.project_path().unwrap().to_owned();
            let source_bytes = std::fs::read(&source).unwrap();
            let raw = source.with_file_name(if tool == "object_export_csv" { "objects.csv" }
                else if tool == "export_image" && arguments["format"] == "jpeg" { "output.jpg" } else { "output.ignored" });
            let target = extension.map_or_else(|| raw.clone(), |extension| raw.with_extension(extension));
            let key = if tool == "ViewCommand_SaveScreenshot" { "filename" } else { "path" };
            arguments[key] = json!(raw);
            let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":tool,"arguments":arguments}});
            let before = document(&app);
            app.tools.store_path = None;
            let mut approval = HostApproval::default();approval.set_active(true);
            let response = agent_rpc(&mut app, &mut approval, &message).unwrap();
            assert_eq!(response["result"]["isError"], true, "{tool}: {response}");
            assert!(!target.exists() && !raw.exists());assert_eq!(document(&app), before);
            let mut harness = Harness::new();
            let output = harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
            let labels = texts(&output).join("\n");
            assert!(labels.contains(&format!("Output file: {}", target.display())), "{tool}: {labels}");
            assert!(labels.contains("Effect: file-write"), "{tool}: {labels}");
            harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, None));
            let mut wrong = message.clone();wrong["params"]["arguments"][key] = json!(raw.with_file_name("wrong.csv"));
            assert_eq!(agent_rpc(&mut app, &mut approval, &wrong).unwrap()["result"]["isError"], true);
            for id in [None, Some(Value::Null)] {
                let mut notification = message.clone();notification.as_object_mut().unwrap().remove("id");
                if let Some(id) = id { notification["id"] = id; }
                assert!(agent_rpc(&mut app, &mut approval, &notification).is_none_or(|reply| reply["result"]["isError"] == true));
                assert!(!target.exists());
            }
            let response = agent_rpc(&mut app, &mut approval, &message).unwrap();
            assert_eq!(response["result"]["isError"], false, "{tool}: {response}");
            let bytes = std::fs::read(&target).unwrap();
            match tool {
                "export_inp" => {
                    let reply = soul2d_core::Session::new().handle_request(&json!({"op":"open","path":target}));
                    assert_eq!(reply["succeeded"], true, "{reply}");assert_eq!(reply["result"]["documentFormat"], "inx");
                }
                "object_export_csv" => assert!(String::from_utf8(bytes.clone()).unwrap().contains("2,Part,Face")),
                "motion3_export" | "Motion3Command_Export" => {
                    let reply = soul2d_core::Session::new().handle_request(&json!({"op":"motion3.import","name":"Roundtrip","path":target}));
                    assert_eq!(reply["succeeded"], true, "{reply}");
                },
                tool if tool.starts_with("live2d_") => assert_eq!(serde_json::from_slice::<Value>(&bytes).unwrap()["Version"], 3),
                "export_gif" => {
                    assert_eq!(&bytes[..6], b"GIF89a");assert_eq!(bytes.last(), Some(&0x3b));
                    assert_eq!(u16::from_le_bytes(bytes[6..8].try_into().unwrap()), 8);
                    assert_eq!(u16::from_le_bytes(bytes[8..10].try_into().unwrap()), 8);
                    assert!(response["result"]["structuredContent"]["frames"].as_u64().unwrap() > 0);
                }
                "export_image" if arguments["format"] == "jpeg" => {
                    let image = soul2d_core::jpeg::decode(&bytes, 8, 64).unwrap();
                    assert_eq!((image.width(), image.height()), (8, 8));
                }
                _ => {
                    let format = if target.extension().is_some_and(|extension| extension == "tga") { image::ImageFormat::Tga }
                        else { image::ImageFormat::Png };
                    let image = image::load_from_memory_with_format(&bytes, format).unwrap_or_else(|error| panic!("{tool}: {error}"));
                    let size = if tool == "export_image" { 8 } else { 16 };
                    assert_eq!((image.width(), image.height()), (size, size), "{tool}");
                },
            }
            assert_eq!(document(&app), before);assert_eq!(std::fs::read(&source).unwrap(), source_bytes);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            let output = harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
            assert!(has(&output, Role::Button, "Allow once"), "{tool} needs a fresh grant");
            harness.click(Role::Button, "Deny changes this turn", |ctx| approval.show(ctx, None));
            assert_eq!(agent_rpc(&mut app, &mut approval, &wrong).unwrap()["result"]["isError"], true);
            assert_eq!(std::fs::read(&target).unwrap(), bytes);assert_eq!(document(&app), before);
        }
    }

    #[test]
    fn acp_gltf_reports_remain_available_and_writes_need_exact_single_use_consent() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{texts, Harness};
        use egui::accesskit::Role;
        use base64::Engine;
        for extension in ["glb", "gltf"] {
            let mut app = export_app(&format!("acp-gltf-{extension}"));
            let source = app.controller.project_path().unwrap().to_owned();
            let target = source.with_file_name(format!("output.{extension}"));
            let expected = source.with_file_name(format!("expected.{extension}"));
            let mut reference = soul2d_core::Session::new();
            assert_eq!(reference.handle_request(&json!({"op":"open","path":source}))["succeeded"], true);
            assert_eq!(reference.handle_request(&json!({"op":"export.gltf","path":expected,"unitsPerMetre":100,"lossy":true}))["succeeded"], true);
            let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"export_gltf",
                "arguments":{"path":target,"unitsPerMetre":100,"lossy":true,"overwrite":true}}});
            let mut approval = HostApproval::default();approval.set_active(true);
            let before = document(&app);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            let mut harness = Harness::new();
            let frame = harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
            assert!(texts(&frame).join("\n").contains(&format!("Output file: {}", target.display())));
            harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
            harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, None));
            let reports = [json!({}), json!({"unitsPerMetre":100}), json!({"lossy":true}),
                json!({"unitsPerMetre":100,"lossy":true,"dryRun":true})];
            for options in &reports {
                let mut report = message.clone();report["params"]["arguments"] = options.clone();
                report["params"]["arguments"]["path"] = json!(target);
                report["params"]["arguments"]["overwrite"] = json!(true);
                let answer = agent_rpc(&mut app, &mut approval, &report).unwrap();
                assert_eq!(answer["result"]["isError"], false, "{answer}");
                assert_eq!(answer["result"]["structuredContent"]["applied"], false);
                report.as_object_mut().unwrap().remove("id");
                assert!(agent_rpc(&mut app, &mut approval, &report).is_none());
                assert!(!target.exists());
            }
            let mut notification = message.clone();notification.as_object_mut().unwrap().remove("id");
            assert!(agent_rpc(&mut app, &mut approval, &notification).is_none());assert!(!target.exists());
            notification["id"] = Value::Null;
            assert!(agent_rpc(&mut app, &mut approval, &notification).is_none_or(|reply| reply["result"]["isError"] == true));
            assert!(!target.exists());
            let answer = agent_rpc(&mut app, &mut approval, &message).unwrap();
            assert_eq!(answer["result"]["isError"], false, "{answer}");
            assert_eq!(std::fs::read(&target).unwrap(), std::fs::read(&expected).unwrap());
            assert_eq!(document(&app), before);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
            harness.click(Role::Button, "Deny changes this turn", |ctx| approval.show(ctx, None));
            for options in reports {
                let mut report = message.clone();report["params"]["arguments"] = options;
                report["params"]["arguments"]["path"] = json!(target);report["params"]["arguments"]["overwrite"] = json!(true);
                assert_eq!(agent_rpc(&mut app, &mut approval, &report).unwrap()["result"]["isError"], false);
            }
            let meta = base64::engine::general_purpose::STANDARD.encode(br#"{"name":"Synthetic","licenseUrl":"https://example.invalid/terms"}"#);
            assert_eq!(app.controller.core_request(&json!({"op":"extdata.set","key":"io.github.geekjapan.soul2d.VrmMeta","base64":meta}))["succeeded"], true);
            let report = agent_rpc(&mut app, &mut approval, &message).unwrap();
            assert_eq!(report["result"]["isError"], false);
            assert_eq!(report["result"]["structuredContent"]["needs"], json!(["acknowledgeRights"]));
            assert_eq!(std::fs::read(&target).unwrap(), std::fs::read(&expected).unwrap());
            let last = rpc(&mut app, "resources/read", json!({"uri":"resource://soul2d/export/gltf-report"}));
            assert_eq!(serde_json::from_str::<Value>(last["contents"][0]["text"].as_str().unwrap()).unwrap(), answer["result"]["structuredContent"]);
        }
    }

    #[cfg(unix)]
    #[test]
    fn acp_gltf_consent_expires_on_document_or_destination_changes() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::Harness;
        use egui::accesskit::Role;
        use std::os::unix::fs::symlink;
        for change in ["document", "file_link", "parent_link", "missing_parent"] {
            let mut app = export_app(&format!("acp-gltf-stale-{change}"));
            let root = app.controller.project_path().unwrap().parent().unwrap().to_owned();
            let first = root.join("first");let second = root.join("second");
            std::fs::create_dir(&first).unwrap();std::fs::create_dir(&second).unwrap();
            let alias = root.join("linked");symlink(&first, &alias).unwrap();
            let a = first.join("out.glb");let b = second.join("out.glb");
            let target = match change {
                "file_link" => {
                    std::fs::write(&a, b"first").unwrap();std::fs::write(&b, b"second").unwrap();
                    let path = root.join("out.glb");symlink(&a, &path).unwrap();path
                },
                "parent_link" => alias.join("out.glb"),
                _ => a.clone(),
            };
            let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"export_gltf",
                "arguments":{"path":target,"unitsPerMetre":100,"lossy":true,"overwrite":true}}});
            let mut approval = HostApproval::default();approval.set_active(true);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            let mut harness = Harness::new();harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
            harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
            harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, None));
            match change {
                "document" => assert_eq!(app.controller.core_request(&json!({"op":"node.rename","id":2,"name":"Changed"}))["succeeded"], true),
                "file_link" => { std::fs::remove_file(&target).unwrap();symlink(&b, &target).unwrap(); },
                "parent_link" => { std::fs::remove_file(&alias).unwrap();symlink(&second, &alias).unwrap(); },
                _ => std::fs::rename(&first, root.join("stored")).unwrap(),
            }
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true, "{change}");
            if change == "missing_parent" {
                std::fs::rename(root.join("stored"), &first).unwrap();
                assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            }
            if change == "file_link" {
                assert_eq!(std::fs::read(a).unwrap(), b"first");assert_eq!(std::fs::read(b).unwrap(), b"second");
            } else { assert!(!a.exists() && !b.exists()); }
        }
    }

    fn store_app(name: &str) -> (EditorApp, PathBuf) {
        let mut app = export_app(name);
        let dir = app.controller.project_path().unwrap().parent().unwrap().join("missing/presets");
        app.controller.with_session(|session| session.set_config_dir(dir.clone()));
        assert_eq!(app.controller.core_request(&json!({"op":"animation.key.set","name":"Idle","parameter":10,"axis":0,"frame":0,"value":0.5}))["succeeded"], true);
        app.tools.store_path = None;
        (app, dir)
    }

    #[test]
    fn acp_store_writes_require_exact_single_use_consent_for_all_eight_operations() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{texts, Harness};
        use egui::accesskit::Role;
        for (family, save, delete, file) in [
            ("automesh_preset", json!({"name":"Owned","algorithm":"contour"}), json!({"name":"Owned"}), "automesh-presets.json"),
            ("physics_preset", json!({"name":"Owned","gravity":2.0}), json!({"name":"Owned"}), "physics-presets.json"),
            ("live2d_physics3_preset", json!({"list":"inputs","name":"Owned","items":[{"source":"ParamAngleX","type":"X","weight":50.0,"reflect":false}]}),
                json!({"list":"inputs","name":"Owned"}), "physics3-input-presets.json"),
            ("animation_template", json!({"name":"Idle","template":"Owned","from":0,"to":1}), json!({"template":"Owned"}), "animation-templates.json"),
        ] {
            let (mut app, dir) = store_app(&format!("acp-store-{family}"));
            let reference_dir = dir.parent().unwrap().parent().unwrap().join("reference");
            let mut reference = soul2d_core::Session::new();reference.set_config_dir(reference_dir.clone());
            assert_eq!(reference.handle_request(&json!({"op":"new","model":app.controller.snapshot()["model"]}))["succeeded"], true);
            for (suffix, args) in [("save", save), ("delete", delete)] {
                let mut request = args.clone();request["op"] = json!(format!("{}.{}", family.replace('_', "."), suffix));
                let expected = reference.handle_request(&request);assert_eq!(expected["succeeded"], true, "{expected}");
                let before = document(&app);let bytes = std::fs::read(dir.join(file)).ok();
                let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":format!("{family}_{suffix}"),"arguments":args}});
                let mut approval = HostApproval::default();approval.set_active(true);
                let mut notification = message.clone();notification.as_object_mut().unwrap().remove("id");
                assert!(agent_rpc(&mut app, &mut approval, &notification).is_none());
                assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
                assert_eq!(std::fs::read(dir.join(file)).ok(), bytes);
                if suffix == "save" { assert!(!dir.parent().unwrap().exists()); }
                let mut harness = Harness::new();let frame = harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
                let labels = texts(&frame).join("\n");assert!(labels.contains(file) && labels.contains("Owned") && labels.contains("Effect: file-write"), "{labels}");
                harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
                harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, None));
                assert!(agent_rpc(&mut app, &mut approval, &notification).is_none());
                notification["id"] = Value::Null;
                assert!(agent_rpc(&mut app, &mut approval, &notification).is_none_or(|reply| reply["result"]["isError"] == true));
                assert_eq!(std::fs::read(dir.join(file)).ok(), bytes);
                let reply = agent_rpc(&mut app, &mut approval, &message).unwrap();
                assert_eq!(reply["result"]["isError"], false, "{reply}");
                assert_eq!(reply["result"]["structuredContent"], expected["result"]);
                assert_eq!(std::fs::read(dir.join(file)).unwrap(), std::fs::read(reference_dir.join(file)).unwrap());
                assert_eq!(document(&app), before);
                assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
                approval.set_active(false);
                assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
                assert_eq!(std::fs::read(dir.join(file)).unwrap(), std::fs::read(reference_dir.join(file)).unwrap());
            }
        }
        let (mut app, dir) = store_app("acp-store-missing-config");
        app.controller.with_session(|session| *session = soul2d_core::Session::new());
        let mut approval = HostApproval::default();approval.set_active(true);
        let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"automesh_preset_save","arguments":{"name":"Owned","algorithm":"contour"}}});
        let reply = agent_rpc(&mut app, &mut approval, &message).unwrap();
        assert_eq!(reply["result"]["isError"], true);assert!(!dir.exists());
        assert!(reply["result"]["content"][0]["text"].as_str().unwrap().contains("no settings directory"));
    }

    #[cfg(unix)]
    #[test]
    fn acp_store_consent_expires_on_external_changes_and_config_retargeting() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::Harness;
        use egui::accesskit::Role;
        use std::os::unix::fs::symlink;
        for change in ["other", "format", "removed", "appeared", "config", "parent", "leaf", "dangling"] {
            let (mut app, dir) = store_app(&format!("acp-store-stale-{change}"));
            let root = dir.parent().unwrap().parent().unwrap().to_owned();
            let file = dir.join("automesh-presets.json");let first = root.join("first");let second = root.join("second");
            std::fs::create_dir(&first).unwrap();std::fs::create_dir(&second).unwrap();
            if change == "parent" { std::fs::create_dir_all(dir.parent().unwrap()).unwrap();symlink(&first, &dir).unwrap(); }
            if matches!(change, "other" | "format" | "removed" | "leaf") {
                assert_eq!(app.controller.core_request(&json!({"op":"automesh.preset.save","name":"A","algorithm":"contour"}))["succeeded"], true);
            }
            if change == "leaf" {
                std::fs::copy(&file, first.join("store.json")).unwrap();std::fs::copy(&file, second.join("store.json")).unwrap();
                std::fs::remove_file(&file).unwrap();symlink(first.join("store.json"), &file).unwrap();
            }
            if change == "dangling" { std::fs::create_dir_all(&dir).unwrap();symlink(first.join("absent.json"), &file).unwrap(); }
            let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"automesh_preset_save","arguments":{"name":"B","algorithm":"contour"}}});
            let mut approval = HostApproval::default();approval.set_active(true);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            let mut harness = Harness::new();harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
            harness.frame(Vec::new(), |ctx| approval.show(ctx, None));harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, None));
            match change {
                "other" | "appeared" => {
                    std::fs::create_dir_all(&dir).unwrap();
                    let mut store = if change == "other" { serde_json::from_slice::<Value>(&std::fs::read(&file).unwrap()).unwrap() }
                        else { json!({"presets":{}}) };
                    store["presets"]["Other"] = json!({"algorithm":"contour"});std::fs::write(&file, store.to_string()).unwrap();
                },
                "format" => { let mut bytes = std::fs::read(&file).unwrap();bytes.push(b'\n');std::fs::write(&file, bytes).unwrap(); },
                "removed" => std::fs::rename(&file, root.join("held.json")).unwrap(),
                "config" => app.controller.with_session(|session| session.set_config_dir(second.clone())),
                "parent" => { std::fs::remove_file(&dir).unwrap();symlink(&second, &dir).unwrap(); },
                "leaf" | "dangling" => { std::fs::remove_file(&file).unwrap();symlink(second.join(if change == "leaf" { "store.json" } else { "absent.json" }), &file).unwrap(); },
                _ => unreachable!(),
            }
            let bytes = std::fs::read(&file).ok();
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true, "{change}");
            assert_eq!(std::fs::read(&file).ok(), bytes);
            if change == "removed" { std::fs::rename(root.join("held.json"), &file).unwrap(); }
            if change == "dangling" { std::fs::remove_file(&file).unwrap();symlink(first.join("absent.json"), &file).unwrap(); }
            if matches!(change, "removed" | "dangling") {
                assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true, "restored {change}");
            }
            assert!(!first.join("automesh-presets.json").exists());assert!(!second.join("automesh-presets.json").exists());
        }
    }

