    fn collection_app(name: &str) -> (EditorApp, PathBuf, PathBuf) {
        let mut app = export_app(name);
        let project = app.controller.project_path().unwrap().to_owned();
        let directory = project.parent().unwrap().to_owned();
        let source = directory.join("source.png");
        let (_, texture) = model_and_texture();
        std::fs::write(&source, &texture.data).unwrap();
        let loaded = app.controller.core_request(&json!({"op":"depth.draw.load_png","path":source,"id":"source"}));
        assert_eq!(loaded["succeeded"], true, "{loaded}");
        let saved = app.controller.core_request(&json!({"op":"save","path":project}));
        assert_eq!(saved["succeeded"], true, "{saved}");
        (app, directory, source)
    }

    #[test]
    fn acp_depth_png_export_shows_all_outputs_and_writes_the_approved_bytes_once() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{texts, Harness};
        use egui::accesskit::Role;
        let (mut app, directory, source) = collection_app("acp-depth-png-once");
        let output = directory.join("missing/nested/export");
        let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"depth_draw_export_png",
            "arguments":{"dir":output,"overwrite":true}}});
        let before = document(&app);
        let mut reference = soul2d_core::Session::new();
        for request in [json!({"op":"open","path":app.controller.project_path().unwrap()}),
            json!({"op":"depth.draw.load_png","path":source,"id":"source"}),
            json!({"op":"depth.draw.export_png","dir":directory.join("expected")})] {
            let result = reference.handle_request(&request);assert_eq!(result["succeeded"], true, "{result}");
        }
        let mut approval = HostApproval::default();approval.set_active(true);
        let mut notification = message.clone();notification.as_object_mut().unwrap().remove("id");
        assert!(agent_rpc(&mut app, &mut approval, &notification).is_none());
        assert!(!directory.join("missing").exists());
        assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
        let mut harness = Harness::new();
        let frame = harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
        let labels = texts(&frame).join("\n");
        assert!(labels.contains("Depth PNG directory:") && labels.contains("000-source.png") && labels.contains("manifest.json") && labels.contains("Effect: file-write"), "{labels}");
        harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
        harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, None));
        assert!(agent_rpc(&mut app, &mut approval, &notification).is_none());
        notification["id"] = Value::Null;
        assert!(agent_rpc(&mut app, &mut approval, &notification).is_none_or(|reply| reply["result"]["isError"] == true));
        assert!(!directory.join("missing").exists());
        let reply = agent_rpc(&mut app, &mut approval, &message).unwrap();
        assert_eq!(reply["result"]["isError"], false, "{reply}");
        for name in ["000-source.png", "manifest.json"] {
            assert_eq!(std::fs::read(output.join(name)).unwrap(), std::fs::read(directory.join("expected").join(name)).unwrap());
        }
        assert_eq!(document(&app), before);
        assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
        harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
        harness.click(Role::Button, "Deny changes this turn", |ctx| approval.show(ctx, None));
        assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
        assert_eq!(document(&app), before);
    }

    #[cfg(unix)]
    #[test]
    fn acp_depth_png_export_expires_for_depth_state_and_path_changes() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::Harness;
        use egui::accesskit::Role;
        use std::os::unix::fs::symlink;
        for change in ["depth", "document", "directory", "manifest", "source", "dangling"] {
            let (mut app, directory, source) = collection_app(&format!("acp-depth-png-stale-{change}"));
            if change == "dangling" {
                std::fs::remove_file(&source).unwrap();symlink(directory.join("absent.png"), &source).unwrap();
            }
            let first = directory.join("first");let second = directory.join("second");
            std::fs::create_dir(&first).unwrap();std::fs::create_dir(&second).unwrap();
            let output = directory.join("out");
            if change == "directory" { symlink(&first, &output).unwrap(); }
            let manifest = directory.join("result.json");
            if change == "manifest" {
                std::fs::write(first.join("result.json"), b"first").unwrap();
                std::fs::write(second.join("result.json"), b"second").unwrap();
                symlink(first.join("result.json"), &manifest).unwrap();
            }
            let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"depth_draw_export_png",
                "arguments":{"dir":output,"manifest":manifest,"overwrite":true}}});
            let mut approval = HostApproval::default();approval.set_active(true);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            let mut harness = Harness::new();harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
            harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
            harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, None));
            match change {
                "depth" => {
                    let revision = app.controller.snapshot()["revision"].clone();
                    assert_eq!(app.controller.core_request(&json!({"op":"depth.draw.layer.update","layer":"source","zOffset":0.25}))["succeeded"], true);
                    assert_eq!(app.controller.snapshot()["revision"], revision, "DepthDraw has its own revision");
                },
                "document" => assert_eq!(app.controller.core_request(&json!({"op":"node.rename","id":2,"name":"Changed"}))["succeeded"], true),
                "directory" => { std::fs::remove_file(&output).unwrap();symlink(&second, &output).unwrap(); },
                "manifest" => { std::fs::remove_file(&manifest).unwrap();symlink(second.join("result.json"), &manifest).unwrap(); },
                "dangling" => { std::fs::remove_file(&source).unwrap();symlink(directory.join("other-absent.png"), &source).unwrap(); },
                _ => std::fs::rename(&source, directory.join("retained.png")).unwrap(),
            }
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true, "{change}");
            if change == "source" {
                std::fs::rename(directory.join("retained.png"), &source).unwrap();
                assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            }
            if change == "dangling" {
                std::fs::remove_file(&source).unwrap();symlink(directory.join("absent.png"), &source).unwrap();
                assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            }
            assert!(!output.join("000-source.png").exists());
            if change == "manifest" {
                assert_eq!(std::fs::read(first.join("result.json")).unwrap(), b"first");
                assert_eq!(std::fs::read(second.join("result.json")).unwrap(), b"second");
            } else { assert!(!manifest.exists()); }
        }
    }

    #[test]
    fn acp_collection_approval_shows_copies_and_writes_once_after_consent() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{texts, Harness};
        use egui::accesskit::Role;
        let (mut app, directory, source) = collection_app("acp-collection-once");
        let output = directory.join("missing/nested/copy");
        let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"export_collect",
            "arguments":{"dir":output,"overwrite":true}}});
        let before = document(&app);
        let mut plan = None;
        app.controller.mcp_request_with_prepared(&message, true, &mut |_, prepared| {
            plan = match prepared? { Some(export::ExportConsent::Collection(plan)) => Some(plan.clone()), _ => None };
            Err("inspect only".into())
        }, &mut |_, _| unreachable!());
        let plan = plan.unwrap();assert_eq!(plan.copies.len(), 1);
        let mut approval = HostApproval::default();approval.set_active(true);
        let mut notification = message.clone();notification.as_object_mut().unwrap().remove("id");
        agent_rpc(&mut app, &mut approval, &notification);
        assert!(!directory.join("missing").exists());
        assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
        let mut harness = Harness::new();
        let frame = harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
        let labels = texts(&frame).join("\n");
        assert!(labels.contains("Collection directory:") && labels.contains("Document output:") && labels.contains("source.png"), "{labels}");
        harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
        harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, None));
        agent_rpc(&mut app, &mut approval, &notification);
        assert!(!directory.join("missing").exists());
        let reply = agent_rpc(&mut app, &mut approval, &message).unwrap();
        assert_eq!(reply["result"]["isError"], false, "{reply}");
        assert_eq!(std::fs::read(&plan.copies[0].destination).unwrap(), std::fs::read(&source).unwrap());
        let saved = std::fs::read(&plan.document).unwrap();
        let opened = soul2d_core::Session::new().handle_request(&json!({"op":"open","path":plan.document}));
        assert_eq!(opened["succeeded"], true, "{opened}");assert_eq!(document(&app), before);
        assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
        harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
        harness.click(Role::Button, "Deny changes this turn", |ctx| approval.show(ctx, None));
        assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
        assert_eq!(std::fs::read(&plan.document).unwrap(), saved);
        let ordinary = call(&mut app, "export_collect", json!({"dir":directory.join("ordinary")}));
        assert!(Path::new(ordinary["path"].as_str().unwrap()).is_file());
        assert_eq!(document(&app), before);
    }

    #[cfg(unix)]
    #[test]
    fn acp_collection_approval_expires_on_source_directory_or_document_changes() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::Harness;
        use egui::accesskit::Role;
        use std::os::unix::fs::symlink;
        for change in ["root", "assets", "source", "missing_source", "document"] {
            let (mut app, directory, source) = collection_app(&format!("acp-collection-stale-{change}"));
            let document_name = app.controller.project_path().unwrap().file_name().unwrap().to_owned();
            let first = directory.join("first");let second = directory.join("second");
            std::fs::create_dir(&first).unwrap();std::fs::create_dir(&second).unwrap();
            let output = directory.join("copy");
            if change == "root" { symlink(&first, &output).unwrap(); }
            if change == "assets" {
                std::fs::create_dir(&output).unwrap();symlink(&first, output.join("assets")).unwrap();
            }
            let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"export_collect",
                "arguments":{"dir":output,"overwrite":true}}});
            let mut approval = HostApproval::default();approval.set_active(true);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            let mut harness = Harness::new();
            harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
            harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
            harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, None));
            match change {
                "root" => { std::fs::remove_file(&output).unwrap();symlink(&second, &output).unwrap(); },
                "assets" => { std::fs::remove_file(output.join("assets")).unwrap();symlink(&second, output.join("assets")).unwrap(); },
                "source" => {
                    let replacement = directory.join("replacement.png");std::fs::write(&replacement, b"new source").unwrap();
                    std::fs::remove_file(&source).unwrap();symlink(replacement, &source).unwrap();
                },
                "missing_source" => std::fs::rename(&source, directory.join("saved.png")).unwrap(),
                _ => {
                    let changed = app.controller.core_request(&json!({"op":"node.rename","id":2,"name":"Changed"}));
                    assert_eq!(changed["succeeded"], true, "{changed}");
                },
            }
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true, "{change}");
            if change == "missing_source" {
                std::fs::rename(directory.join("saved.png"), &source).unwrap();
                assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            }
            assert_eq!(std::fs::read_dir(&first).unwrap().count(), 0, "{change}");
            assert_eq!(std::fs::read_dir(&second).unwrap().count(), 0, "{change}");
            assert!(!output.join(&document_name).exists());
        }
    }

    #[test]
    fn ordinary_video_clients_keep_guarding_and_async_encoder_failure() {
        let mut app = export_app("ordinary-video-missing-encoder");
        let directory = app.controller.project_path().unwrap().parent().unwrap().to_owned();
        app.controller.with_session(|session| session.set_video_encoder(directory.join("missing-encoder").to_str().unwrap()));
        let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"export_video_start",
            "arguments":{"path":directory.join("movie.mp4")}}});
        let mut guarded = false;
        let refusal = app.controller.mcp_request_with(&message, &mut |call| {
            assert_eq!(call["op"], "export.video.start");guarded = true;Err("old guard refusal".into())
        }, &mut |_, _| unreachable!()).unwrap();
        assert!(guarded);assert_eq!(refusal["result"]["isError"], true);
        let reply = rpc(&mut app, "tools/call", message["params"].clone());
        assert_eq!(reply["isError"], false, "{reply}");
        let job = reply["structuredContent"]["job"].as_u64().unwrap();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            let response = app.controller.core_request(&json!({"op":"export.video.status","job":job}));
            if response["result"]["state"] != "running" {
                assert_eq!(response["result"]["state"], "failed", "{response}");break
            }
            assert!(std::time::Instant::now() < deadline);std::thread::sleep(std::time::Duration::from_millis(5));
        }
    }

    #[cfg(unix)]
    fn approval_encoder_stub(directory: &Path, name: &str) -> String {
        use std::os::unix::fs::PermissionsExt;
        let path = directory.join(name);
        std::fs::write(&path, format!("#!/bin/sh\nprintf '%s\\n' \"$@\" > '{}/args.txt'\nprintf 'launch\\n' >> '{}/launches.txt'\ncat > '{}/frames.bin'\n", directory.display(), directory.display(), directory.display())).unwrap();
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o755)).unwrap();
        path.to_string_lossy().into_owned()
    }

    #[cfg(unix)]
    #[test]
    fn acp_video_consent_runs_the_exact_prepared_command_once() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::Harness;
        use egui::accesskit::Role;
        for (index, options) in [json!({}), json!({"codec":"mpeg4"}), json!({"codec":"png"}),
            json!({"codec":"jpeg"}), json!({"codec":"jpg"}), json!({"codec":"tga"}),
            json!({"preset":"mp4"}), json!({"preset":"webm"}), json!({"preset":"mov"})].into_iter().enumerate() {
            let mut app = export_app(&format!("acp-video-command-{index}"));
            let directory = app.controller.project_path().unwrap().parent().unwrap().to_owned();
            let program = approval_encoder_stub(&directory, "encoder");
            app.controller.with_session(|session| { session.set_video_encoder(&program);session.set_video_ffmpeg_options("-threads 2"); });
            let mut args = options;args["path"] = json!(directory.join("movie.mp4"));args["overwrite"] = json!(index % 2 == 0);
            let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"export_video_start","arguments":args}});
            let before = document(&app);
            let mut expected = None;
            app.controller.mcp_request_with_prepared(&message, true, &mut |_, video| {
                expected = match video? { Some(export::ExportConsent::Video(video)) => Some(video.clone()), _ => None };Err("inspect only".into())
            }, &mut |_, _| unreachable!());
            let expected = expected.unwrap();
            assert_eq!(expected.command.args[0], if index % 2 == 0 { "-y" } else { "-n" });
            let mut approval = HostApproval::default();approval.set_active(true);
            let mut notification = message.clone();notification.as_object_mut().unwrap().remove("id");
            agent_rpc(&mut app, &mut approval, &notification);
            assert!(!directory.join("launches.txt").exists());
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            assert!(!directory.join("launches.txt").exists());
            let mut harness = Harness::new();
            harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
            let output = harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
            let button = crate::editor_test_support::center(&output, Role::Button, "Allow once");
            assert!(egui::Rect::from_min_size(egui::Pos2::ZERO, harness.screen).contains(button), "approval button is off screen: {button:?}");
            harness.click(Role::Button,"Allow once",|ctx|approval.show(ctx,None));
            agent_rpc(&mut app, &mut approval, &notification);
            let reply = agent_rpc(&mut app, &mut approval, &message).unwrap();
            assert_eq!(reply["result"]["isError"], false, "{reply}");
            let job = reply["result"]["structuredContent"]["job"].as_u64().unwrap();
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
            loop {
                let state = app.controller.core_request(&json!({"op":"export.video.status","job":job}));
                if state["result"]["state"] != "running" { assert_eq!(state["result"]["state"], "finished", "{state}");break }
                assert!(std::time::Instant::now() < deadline);std::thread::sleep(std::time::Duration::from_millis(5));
            }
            assert_eq!(std::fs::read_to_string(directory.join("args.txt")).unwrap().lines().map(str::to_owned).collect::<Vec<_>>(), expected.command.args);
            assert_eq!(std::fs::read_to_string(directory.join("launches.txt")).unwrap(), "launch\n");
            assert_eq!(std::fs::read(directory.join("frames.bin")).unwrap().len(), expected.plan.frames()*8*8*4);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            assert_eq!(document(&app), before);
        }
    }

    #[cfg(unix)]
    #[test]
    fn acp_video_consent_expires_when_host_settings_or_render_source_changes() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::Harness;
        use egui::accesskit::Role;
        for change in ["program", "options", "values", "ambient", "missing_program", "program_link"] {
            let mut app = export_app(&format!("acp-video-stale-{change}"));
            let directory = app.controller.project_path().unwrap().parent().unwrap().to_owned();
            let first = approval_encoder_stub(&directory, "first-encoder");
            let second = approval_encoder_stub(&directory, "second-encoder");
            let link = directory.join("linked-encoder");
            std::os::unix::fs::symlink(&first, &link).unwrap();
            app.controller.with_session(|session| session.set_video_encoder(if change == "program_link" { link.to_str().unwrap() } else { &first }));
            let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"export_video_start",
                "arguments":{"path":directory.join("movie.mp4")}}});
            let mut approval = HostApproval::default();approval.set_active(true);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            Harness::new().click(Role::Button,"Allow once",|ctx|approval.show(ctx,None));
            match change {
                "missing_program" => std::fs::rename(&first, directory.join("saved-encoder")).unwrap(),
                "program_link" => { std::fs::remove_file(&link).unwrap();std::os::unix::fs::symlink(&second, &link).unwrap(); },
                "program" => app.controller.with_session(|session| session.set_video_encoder(&second)),
                "options" => app.controller.with_session(|session| session.set_video_ffmpeg_options("-threads 2")),
                "ambient" => { let result = app.controller.core_request(&json!({"op":"scene.ambient.set","color":[0.1,0.2,0.3]}));assert_eq!(result["succeeded"],true,"{result}"); },
                _ => { let result = app.controller.core_request(&json!({"op":"value.set","id":10,"value":[0.5,0.0]}));assert_eq!(result["succeeded"],true,"{result}"); },
            }
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true, "{change}");
            assert!(!directory.join("launches.txt").exists());
            if change == "missing_program" {
                std::fs::rename(directory.join("saved-encoder"), &first).unwrap();
                assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
                assert!(!directory.join("launches.txt").exists());
            }
        }
    }

    #[test]
    fn acp_frame_exports_require_exact_single_use_approval() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{texts, Harness};
        use egui::accesskit::Role;
        let mut app = export_app("acp-frame-approval");
        let source = app.controller.project_path().unwrap().to_owned();
        let target = source.with_file_name("sequence.png");
        let before = document(&app);
        let paths = export::frame_sequence_paths(app.controller.snapshot(), &export::VideoExportOptions::default(), &target).unwrap();
        assert!(!paths.is_empty());
        let request = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"export_frames",
            "arguments":{"path":target,"overwrite":true}}});
        let mut approval = HostApproval::default();
        approval.set_active(true);
        for stage in ["before", "allowed"] {
            if stage == "allowed" {
                assert_eq!(agent_rpc(&mut app, &mut approval, &request).unwrap()["result"]["isError"], true);
                let mut harness = Harness::new();
                let output = harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
                let labels = texts(&output).join("\n");
                assert!(labels.contains(&format!("Output files: {}", paths.len())));
                for path in &paths { assert!(labels.contains(&path.display().to_string())); }
                harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, None));
            }
            let mut notification = request.clone();notification.as_object_mut().unwrap().remove("id");
            agent_rpc(&mut app, &mut approval, &notification);
            assert!(paths.iter().all(|path| !path.exists()));
        }
        let result = agent_rpc(&mut app, &mut approval, &request).unwrap();
        assert_eq!(result["result"]["isError"], false, "{result}");
        assert!(paths.iter().all(|path| path.exists()));
        assert_eq!(document(&app), before);
        assert_eq!(agent_rpc(&mut app, &mut approval, &request).unwrap()["result"]["isError"], true);
        let bytes: Vec<_> = paths.iter().map(|path| std::fs::read(path).unwrap()).collect();
        let mut harness = Harness::new();
        harness.click(Role::Button, "Deny changes this turn", |ctx| approval.show(ctx, None));
        assert_eq!(agent_rpc(&mut app, &mut approval, &request).unwrap()["result"]["isError"], true);
        assert_eq!(paths.iter().map(|path| std::fs::read(path).unwrap()).collect::<Vec<_>>(), bytes);
        approval.set_active(false);approval.set_active(true);
        assert_eq!(agent_rpc(&mut app, &mut approval, &request).unwrap()["result"]["isError"], true);
        harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, None));
        app.command(json!({"op":"node.rename","id":2,"name":"Changed during approval"}));
        assert_eq!(agent_rpc(&mut app, &mut approval, &request).unwrap()["result"]["isError"], true);
        assert_eq!(paths.iter().map(|path| std::fs::read(path).unwrap()).collect::<Vec<_>>(), bytes);
    }

    #[cfg(unix)]
    #[test]
    fn acp_frame_paths_protect_the_source_and_recheck_symlinks() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{has, Harness};
        use egui::accesskit::Role;
        use std::{fs, os::unix::fs::symlink};
        for mode in ["retarget", "leaf", "collision"] {
            let mut app = export_app(&format!("acp-frame-path-{mode}"));
            let mut source = app.controller.project_path().unwrap().to_owned();
            let target = source.with_file_name("sequence.png");
            let first = export::frame_path(&target, 1);
            if mode == "collision" {
                app.command(json!({"op":"save","path":first}));
                source = app.controller.project_path().unwrap().to_owned();
                assert_eq!(source, first);
            }
            let bytes = fs::read(&source).unwrap();
            let before = document(&app);
            let alias = source.with_file_name("alias.png");
            let other = source.with_file_name("other.png");
            if mode == "retarget" {
                fs::write(&target, b"template").unwrap();
                fs::write(&other, b"other").unwrap();
                symlink(&target, &alias).unwrap();
            } else if mode == "leaf" {
                symlink(&source, &first).unwrap();
            }
            let request = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"export_frames",
                "arguments":{"path":if mode == "retarget" { &alias } else { &target },"overwrite":true}}});
            let mut approval = HostApproval::default();approval.set_active(true);
            assert_eq!(agent_rpc(&mut app, &mut approval, &request).unwrap()["result"]["isError"], true);
            let mut harness = Harness::new();
            if mode == "collision" {
                let output = harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
                assert!(!has(&output, Role::Button, "Allow once"));
            } else {
                harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, None));
                if mode == "retarget" {
                    fs::remove_file(&alias).unwrap();symlink(&other, &alias).unwrap();
                }
                let reply = agent_rpc(&mut app, &mut approval, &request).unwrap();
                assert_eq!(reply["result"]["isError"], mode == "retarget", "{mode}: {reply}");
                if mode == "leaf" {
                    assert!(!fs::symlink_metadata(&first).unwrap().file_type().is_symlink());
                    let image = image::load_from_memory(&fs::read(&first).unwrap()).unwrap();
                    assert_eq!((image.width(), image.height()), (8,8));
                } else {
                    for base in [&target, &other] {
                        for path in export::frame_sequence_paths(app.controller.snapshot(), &export::VideoExportOptions::default(), base).unwrap() {
                            assert!(!path.exists());
                        }
                    }
                    assert_eq!(fs::read(&target).unwrap(), b"template");
                    assert_eq!(fs::read(&other).unwrap(), b"other");
                }
            }
            assert_eq!(fs::read(source).unwrap(), bytes);
            assert_eq!(document(&app), before);
        }
    }

