    #[test]
    fn acp_save_and_file_capture_aliases_need_exact_single_use_host_approval() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{texts, Harness};
        use egui::accesskit::Role;
        for tool in ["save", "FileCommand_SaveFile", "render", "ViewCommand_CaptureLiveScreenshot"] {
            let mut app = app(&format!("acp-file-approval-{tool}"));
            let saving = matches!(tool, "save" | "FileCommand_SaveFile");
            let path = app.tools.store_path.as_ref().unwrap().with_file_name(if saving { "agent.inx" } else { "agent.png" });
            app.tools.store_path = None;
            let before = document(&app);
            let source = app.controller.project_path().unwrap().display().to_string();
            let key = if tool == "FileCommand_SaveFile" { "file" } else { "path" };
            let mut arguments = if saving { json!({}) } else { json!({"width":4,"height":4,"bounds":[0,0,2,2]}) };
            arguments[key] = json!(path);
            let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call",
                "params":{"name":tool,"arguments":arguments}});
            let mut approval = HostApproval::default();
            approval.set_active(true);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true, "{tool}");
            assert!(!path.exists());
            assert_eq!(document(&app), before);
            let mut harness = Harness::new();
            let output = harness.frame(Vec::new(), |ctx| approval.show(ctx, None));
            let labels = texts(&output).join("\n");
            for label in ["Effect: file-write", "Output file:", "Source document:", &source] {
                assert!(labels.contains(label), "{tool}: {label}: {labels}");
            }
            harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, None));
            let other = path.with_file_name("different-output");
            let mut wrong = message.clone();wrong["params"]["arguments"][key] = json!(other);
            assert_eq!(agent_rpc(&mut app, &mut approval, &wrong).unwrap()["result"]["isError"], true);
            assert!(!other.exists() && !path.exists());
            for id in [None, Some(Value::Null)] {
                let mut notification = message.clone();notification.as_object_mut().unwrap().remove("id");
                if let Some(id) = id { notification["id"] = id; }
                let response = agent_rpc(&mut app, &mut approval, &notification);
                assert!(response.is_none_or(|response| response["result"]["isError"] == true));
                assert!(!path.exists());
            }
            let mut malformed = message.clone();malformed["params"]["arguments"][key] = json!(1);
            assert_eq!(agent_rpc(&mut app, &mut approval, &malformed).unwrap()["result"]["isError"], true);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], false, "{tool}");
            let bytes = std::fs::read(&path).unwrap();
            if saving {
                let mut reopened = soul2d_core::Session::new();
                let reply = reopened.handle_mcp(&json!({"jsonrpc":"2.0","id":1,"method":"tools/call",
                    "params":{"name":"open","arguments":{"path":path}}})).unwrap();
                assert_eq!(reply["result"]["isError"], false);
                assert_eq!(reopened.snapshot()["model"], before[0]);
            } else {
                let image = image::load_from_memory(&bytes).unwrap();
                assert_eq!((image.width(), image.height()), (4, 4));
            }
            assert_eq!(document(&app), before);
            assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
            assert_eq!(std::fs::read(&path).unwrap(), bytes);
            harness.click(Role::Button, "Deny changes this turn", |ctx| approval.show(ctx, None));
            assert_eq!(agent_rpc(&mut app, &mut approval, &wrong).unwrap()["result"]["isError"], true);
            for read_tool in ["render", "ViewCommand_CaptureLiveScreenshot"] {
                let read = json!({"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":read_tool,
                    "arguments":{"width":4,"height":4,"bounds":[0,0,2,2]}}});
                let response = agent_rpc(&mut app, &mut approval, &read).unwrap();
                assert_eq!(response["result"]["isError"], false, "{read_tool}: {response}");
                assert!(response["result"]["content"].as_array().unwrap().iter().any(|block| block["type"] == "image"));
            }
            assert!(!other.exists());
            assert_eq!(std::fs::read(path).unwrap(), bytes);
        }
    }

    #[test]
    fn acp_file_approval_refuses_a_changed_document_or_draft() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::{has, Harness};
        use egui::accesskit::Role;
        for tool in ["save", "render"] {
            for event in ["edit", "replace", "draft"] {
                let mut app = app(&format!("acp-file-stale-{tool}-{event}"));
                let path = app.tools.store_path.as_ref().unwrap().with_file_name(if tool == "save" { "stale.inx" } else { "stale.png" });
                let mut arguments = if tool == "save" { json!({}) } else { json!({"width":4,"height":4,"bounds":[0,0,2,2]}) };
                arguments["path"] = json!(path);
                let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":tool,"arguments":arguments}});
                let mut approval = HostApproval::default();approval.set_active(true);
                assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
                let settings = app.tools.store_path.clone();
                let mut harness = Harness::new();
                harness.click(Role::Button, "Allow once", |ctx| approval.show(ctx, settings.as_deref()));
                match event {
                    "edit" => assert_eq!(app.controller.core_request(&json!({"op":"node.rename","id":2,"name":"Changed"}))["succeeded"], true),
                    "replace" => assert_eq!(app.controller.core_request(&json!({"op":"new"}))["succeeded"], true),
                    "draft" => {
                        app.controller.select_node_target(2).unwrap();app.select_node_draft(2);
                        app.controller.set_draft_name("Unapplied".into());
                    }
                    _ => unreachable!(),
                }
                let changed = document(&app);
                let reply = agent_rpc(&mut app, &mut approval, &message).unwrap();
                assert_eq!(reply["result"]["isError"], true, "{tool}/{event}: {reply}");
                assert!(!path.exists());
                assert_eq!(document(&app), changed);
                let output = harness.frame(Vec::new(), |ctx| approval.show(ctx, settings.as_deref()));
                assert!(!has(&output, Role::Button, "Allow once"), "{tool}/{event}");
            }
        }
    }

