        let before=document(&app);
        click_track_delete(&mut app,&mut harness,"scene-guid","image-track-guid");
        let output=harness.frame(Vec::new(),|ctx|draw_can3_scene_gui(&mut app,ctx));
        let text=texts(&output).join("\n");
