        click_track_delete(&mut app,&mut harness,"scene-guid","image-track-guid");
        harness.click(Role::Button,"Confirm track deletion",|ctx|draw_can3_scene_gui(&mut app,ctx));
        let mut expected=changed[0].clone();expected["scenes"][0]["imageTracks"]=json!([]);
        assert_eq!(app.controller.snapshot()["model"],expected);
