    #[test]
    fn can3_track_gui_guards_save_replace_close_and_stdin_eof() {
        use crate::editor_test_support::Harness;
        use egui::accesskit::Role;
        for mode in ["draft","model","image"] {
            let pending=mode!="draft";
            let name=format!("can3-track-{mode}-guards");
            let mut app=if mode=="image" {can3_app_with_xml(&name,include_str!("../tests/fixtures/can3-image-track.xml"))} else {can3_scene_app(&name)};
            let mut harness=Harness::new();harness.screen=egui::vec2(1200.0,1800.0);
            if pending {click_track_delete(&mut app,&mut harness,"scene-guid",if mode=="image" {"image-track-guid"} else {"track-guid"});}
            else {
                harness.click(Role::TextInput,"New track name",|ctx|draw_can3_scene_gui(&mut app,ctx));
                harness.frame(vec![egui::Event::Text(" pending".into())],|ctx|draw_can3_scene_gui(&mut app,ctx));
            }
            let before=document(&app);
            if !pending {
                let path=temp_dir(&name).join("saved.can3");
                app.command(json!({"op":"save","path":path}));assert_eq!(app.notice,CAN3_TRACK_DRAFT_MESSAGE);
                assert_eq!(app.save_for_dialog(path.to_str().unwrap()),Err(CAN3_TRACK_DRAFT_MESSAGE.into()));
                assert_eq!(refused(&mut app,"save",json!({"path":path})),FILE_OP_BLOCKED_MESSAGE);
                assert_eq!(state(&mut app)["drafts"]["panels"],true);assert!(!path.exists());
            }
            app.command(json!({"op":"new"}));
            let message=if pending {DIALOG_PENDING_MESSAGE} else {DRAFT_BLOCKS_MESSAGE};assert_eq!(app.notice,message);
            assert_eq!(refused(&mut app,"new",json!({})),if pending {DIALOG_PENDING_MESSAGE} else {FILE_OP_BLOCKED_MESSAGE});
            harness.next_input=Some(Box::new(|input|input.viewports.entry(egui::ViewportId::ROOT).or_default().events.push(egui::ViewportEvent::Close)));
            harness.frame(Vec::new(),|ctx|app.handle_close_request(ctx));assert!(!app.closing);
            let (sender,receiver)=std::sync::mpsc::channel();app.host_rx=Some(receiver);sender.send(HostMessage::StdinClosed).unwrap();
            let ctx=egui::Context::default();
            let output=ctx.run(egui::RawInput::default(),|ctx|app.drain_host(ctx));
            assert!(!output.viewport_output[&egui::ViewportId::ROOT].commands.contains(&egui::ViewportCommand::Close));
            assert_eq!(document(&app),before);
            if pending {harness.click(Role::Button,"Cancel track deletion",|ctx|draw_can3_scene_gui(&mut app,ctx));}
            else {harness.click(Role::Button,"Discard new track",|ctx|draw_can3_scene_gui(&mut app,ctx));}
            assert_eq!(state(&mut app)["drafts"]["panels"],false);
            call(&mut app,"new",json!({}));assert!(app.can3_track_draft.is_none() && app.can3_delete.is_none());
        }
    }

    fn click_scene_delete(app: &mut EditorApp, harness: &mut crate::editor_test_support::Harness, guid: &str) {
        use crate::editor_test_support::has;
        use egui::accesskit::Role;
        let name = app.controller.snapshot()["model"]["scenes"].as_array().unwrap().iter()
            .find(|scene| scene["guid"] == guid).unwrap()["name"].as_str().unwrap().to_owned();
        let label = format!("Delete scene \"{name}\"...");
        let output = harness.frame(Vec::new(), |ctx| draw_can3_scene_gui(app,ctx));
        if !has(&output, Role::Button, &label) {
            harness.click(Role::Button, &name, |ctx| draw_can3_scene_gui(app,ctx));
        }
        harness.click(Role::Button, &label, |ctx| draw_can3_scene_gui(app,ctx));
        assert!(matches!(&app.can3_delete, Some(Can3DeleteConfirmation::Scene(pending)) if pending.scene_guid == guid));
    }

    fn can3_curve_choose(app: &mut EditorApp, harness: &mut crate::editor_test_support::Harness, combo: &str, choice: &str) {
        use crate::editor_test_support::name_of;
        use egui::accesskit::Role;
        let output=harness.click(Role::ComboBox,combo,|ctx|draw_can3_scene_gui(app,ctx));
        let role=output.iter().find(|(_,node)|name_of(&output,node).as_deref()==Some(choice))
            .map(|(_,node)|node.role()).unwrap_or_else(||panic!("missing choice {choice}"));
        harness.click(role,choice,|ctx|draw_can3_scene_gui(app,ctx));
    }

    fn can3_curve_attach(app: &mut EditorApp, name: &str) -> PathBuf {
        let path=temp_dir(name).join("source.cmo3");
        std::fs::write(&path,crate::editor_test_support::cmo3_bytes()).unwrap();
        app.command(json!({"op":"live2d.model.attach","path":path,"resourceGuid":"res-guid"}));
        assert_eq!(app.controller.snapshot()["nativePlayback"]["modelPath"],path.to_str().unwrap());
        path
    }

    fn open_can3_curve(app: &mut EditorApp, harness: &mut crate::editor_test_support::Harness,
        scene: &str, track: &str, curve_id: &str, map_key: Option<&str>)
    {
        use crate::editor_test_support::has;
        use egui::accesskit::Role;
        let row=app.controller.snapshot()["model"]["scenes"].as_array().unwrap().iter().find(|row|row["guid"]==scene).unwrap();
        let scene_name=row["name"].as_str().unwrap().to_owned();
        let track_name=row["tracks"].as_array().unwrap().iter().find(|row|row["guid"]==track).unwrap()["name"].as_str().unwrap().to_owned();
        let curve_label=map_key.map(|key|format!("{curve_id} [{key}]")).unwrap_or_else(||curve_id.to_owned());
        let mut output=harness.frame(Vec::new(),|ctx|draw_can3_scene_gui(app,ctx));
        if !has(&output,Role::Button,&track_name) {output=harness.click(Role::Button,&scene_name,|ctx|draw_can3_scene_gui(app,ctx));}
        if !has(&output,Role::Button,&curve_label) {output=harness.click(Role::Button,&track_name,|ctx|draw_can3_scene_gui(app,ctx));}
        let label=format!("Delete curve \"{curve_label}\"...");
        if !has(&output,Role::Button,&label) {harness.click(Role::Button,&curve_label,|ctx|draw_can3_scene_gui(app,ctx));}
    }

    fn click_curve_delete(app: &mut EditorApp, harness: &mut crate::editor_test_support::Harness,
        scene: &str, track: &str, curve_id: &str, map_key: Option<&str>)
    {
        use egui::accesskit::Role;
        open_can3_curve(app,harness,scene,track,curve_id,map_key);
        let curve_label=map_key.map(|key|format!("{curve_id} [{key}]")).unwrap_or_else(||curve_id.to_owned());
        let label=format!("Delete curve \"{curve_label}\"...");
        harness.click(Role::Button,&label,|ctx|draw_can3_scene_gui(app,ctx));
        assert!(matches!(&app.can3_delete,Some(Can3DeleteConfirmation::Curve(pending))
            if pending.scene_guid==scene && pending.track_guid==track && pending.curve_id==curve_id && pending.map_key.as_deref()==map_key));
    }

