    #[test]
    fn can3_key_gui_adds_each_family_with_exact_identity_history_and_native_save() {
        use crate::editor_test_support::Harness;
        use egui::accesskit::Role;
        for (name,xml,field,index,kind) in can3_key_cases() {
            let name=format!("can3-key-create-{name}");let mut app=can3_app_with_xml(&name,xml);
            let before=app.controller.snapshot()["model"].clone();
            let scene=before["scenes"][0]["guid"].as_str().unwrap();
            let track=before["scenes"][0]["tracks"][0]["guid"].as_str().unwrap();
            let curve=&before["scenes"][0]["tracks"][0][field][index];
            let mut harness=Harness::new();harness.screen=egui::vec2(1200.0,3600.0);
            begin_can3_key(&mut app,&mut harness,scene,track,curve["id"].as_str().unwrap(),curve["mapKey"].as_str());
            set_can3_key_fields(&mut app,&mut harness,-5,2.5,kind);
            let revision=app.controller.snapshot()["revision"].as_u64().unwrap();
            harness.click(Role::Button,"Add CAN3 key",|ctx|draw_can3_scene_gui(&mut app,ctx));
            assert_eq!(app.controller.snapshot()["revision"],revision+1,"{name}: {}",app.controller.status());
            assert!(app.can3_key_draft.is_none());let added=app.controller.snapshot()["model"].clone();
            let channel=&added["scenes"][0]["tracks"][0][field][index];
            assert_eq!(channel["points"][0]["anchor"]["frame"],-5);assert_eq!(channel["points"][0]["anchor"]["value"],2.5);
            assert_eq!(channel["curveTypes"][0],kind);
            let mut restored=added.clone();let channel=&mut restored["scenes"][0]["tracks"][0][field][index];
            channel["points"].as_array_mut().unwrap().remove(0);channel["curveTypes"].as_array_mut().unwrap().remove(0);
            assert_eq!(restored,before);
            app.command(json!({"op":"undo"}));assert_eq!(app.controller.snapshot()["model"],before);
            app.command(json!({"op":"redo"}));assert_eq!(app.controller.snapshot()["model"],added);
            let saved=temp_dir(&name).join("saved.can3");app.command(json!({"op":"save","path":saved}));assert!(saved.exists(),"{}",app.notice);
            app.command(json!({"op":"open","path":saved}));assert_eq!(app.controller.snapshot()["model"],added);
        }
    }

    #[test]
    fn can3_key_gui_deletes_the_last_key_and_repopulates_each_family() {
        use crate::editor_test_support::Harness;
        use egui::accesskit::Role;
        for (name,xml,field,index,_) in can3_key_cases() {
            let name=format!("can3-key-delete-{name}");let mut app=can3_app_with_xml(&name,xml);
            let original=app.controller.snapshot()["model"].clone();
            let scene=original["scenes"][0]["guid"].as_str().unwrap();let track=original["scenes"][0]["tracks"][0]["guid"].as_str().unwrap();
            let curve=&original["scenes"][0]["tracks"][0][field][index];let id=curve["id"].as_str().unwrap();let key=curve["mapKey"].as_str();
            let label=key.map(|key|format!("{id} [{key}]")).unwrap_or_else(||id.to_owned());
            let frames:Vec<i64>=curve["points"].as_array().unwrap().iter().map(|p|p["anchor"]["frame"].as_i64().unwrap()).collect();
            let mut harness=Harness::new();harness.screen=egui::vec2(1200.0,3600.0);
            open_can3_curve(&mut app,&mut harness,scene,track,id,key);
            for frame in frames {
                let before=app.controller.snapshot()["model"].clone();let revision=app.controller.snapshot()["revision"].as_u64().unwrap();
                harness.click(Role::Button,&format!("Delete key {frame} in \"{label}\""),|ctx|draw_can3_scene_gui(&mut app,ctx));
                assert_eq!(app.controller.snapshot()["revision"],revision+1,"{name}: {}",app.controller.status());
                let after=app.controller.snapshot()["model"].clone();let mut expected=before.clone();
                let curve=&mut expected["scenes"][0]["tracks"][0][field][index];
                curve["points"].as_array_mut().unwrap().remove(0);curve["curveTypes"].as_array_mut().unwrap().remove(0);
                assert_eq!(after,expected);
                app.command(json!({"op":"undo"}));assert_eq!(app.controller.snapshot()["model"],before);
                app.command(json!({"op":"redo"}));assert_eq!(app.controller.snapshot()["model"],after);
            }
            let empty=app.controller.snapshot()["model"].clone();assert_eq!(empty["scenes"][0]["tracks"][0][field][index]["points"],json!([]));
            let saved=temp_dir(&name).join("saved.can3");app.command(json!({"op":"save","path":saved}));assert!(saved.exists(),"{}",app.notice);
            app.command(json!({"op":"open","path":saved}));assert_eq!(app.controller.snapshot()["model"],empty);
            begin_can3_key(&mut app,&mut harness,scene,track,id,key);
            harness.click(Role::Button,"Add CAN3 key",|ctx|draw_can3_scene_gui(&mut app,ctx));
            let channel=&app.controller.snapshot()["model"]["scenes"][0]["tracks"][0][field][index];
            assert_eq!(channel["points"].as_array().unwrap().len(),1,"{}",app.controller.status());assert_eq!(channel["curveTypes"],json!(["LINEAR"]));
        }
    }

