    #[test]
    fn can3_key_gui_guards_save_replace_close_dialogs_and_stdin_eof() {
        use crate::editor_test_support::Harness;
        use egui::accesskit::Role;
        let name="can3-key-guards";let mut app=can3_scene_app(name);let mut harness=Harness::new();harness.screen=egui::vec2(1200.0,3600.0);
        begin_can3_key(&mut app,&mut harness,"scene-guid","track-guid","live2dParam_ParamTest",None);
        set_can3_key_fields(&mut app,&mut harness,-5,0.4,"STEP");let before=document(&app);
        let saved=temp_dir(name).join("saved.can3");app.command(json!({"op":"save","path":saved}));assert_eq!(app.notice,CAN3_KEY_DRAFT_MESSAGE);
        assert_eq!(app.save_for_dialog(saved.to_str().unwrap()),Err(CAN3_KEY_DRAFT_MESSAGE.into()));
        assert_eq!(refused(&mut app,"save",json!({"path":saved})),FILE_OP_BLOCKED_MESSAGE);assert!(!saved.exists());assert_eq!(state(&mut app)["drafts"]["panels"],true);
        app.command(json!({"op":"new"}));assert_eq!(app.notice,DRAFT_BLOCKS_MESSAGE);assert_eq!(refused(&mut app,"new",json!({})),FILE_OP_BLOCKED_MESSAGE);
        harness.next_input=Some(Box::new(|input|input.viewports.entry(egui::ViewportId::ROOT).or_default().events.push(egui::ViewportEvent::Close)));
        harness.frame(Vec::new(),|ctx|app.handle_close_request(ctx));assert!(!app.closing);
        let (sender,receiver)=std::sync::mpsc::channel();app.host_rx=Some(receiver);sender.send(HostMessage::StdinClosed).unwrap();
        let ctx=egui::Context::default();let output=ctx.run(egui::RawInput::default(),|ctx|app.drain_host(ctx));
        assert!(!output.viewport_output[&egui::ViewportId::ROOT].commands.contains(&egui::ViewportCommand::Close));assert_eq!(document(&app),before);
        click_curve_delete(&mut app,&mut harness,"scene-guid","track-guid","live2dParam_ParamTest",None);
        harness.click(Role::Button,"Discard new key",|ctx|draw_can3_scene_gui(&mut app,ctx));assert!(app.can3_key_draft.is_some());
        harness.click(Role::Button,"Cancel curve deletion",|ctx|draw_can3_scene_gui(&mut app,ctx));
        harness.click(Role::Button,"Discard new key",|ctx|draw_can3_scene_gui(&mut app,ctx));
        call(&mut app,"new",json!({}));assert!(app.can3_key_draft.is_none());
    }

    #[test]
    fn can3_curve_gui_creates_parameter_and_part_channels_with_history_and_native_save() {
        use crate::editor_test_support::Harness;
        use egui::accesskit::Role;
        for part in [false,true] {
            let name=if part {"can3-curve-part-create"} else {"can3-curve-parameter-create"};
            let mut app=can3_scene_app(name);
            let mut harness=Harness::new();harness.screen=egui::vec2(1200.0,2600.0);
            harness.click(Role::Button,"Add CAN3 scene",|ctx|draw_can3_scene_gui(&mut app,ctx));
            harness.click(Role::Button,"Add CAN3 track",|ctx|draw_can3_scene_gui(&mut app,ctx));
            can3_curve_attach(&mut app,name);
            if part {
                can3_curve_choose(&mut app,&mut harness,"New curve kind","PartOpacity");
                assert!(app.can3_part_choices.parts.is_empty());
                harness.click(Role::Button,"Refresh Part choices",|ctx|draw_can3_scene_gui(&mut app,ctx));
                can3_curve_choose(&mut app,&mut harness,"New curve target","root (part-guid)");
            } else {can3_curve_choose(&mut app,&mut harness,"New curve target","ParamTest (ParamTest)");}
            let before=app.controller.snapshot()["model"].clone();
            let revision=app.controller.snapshot()["revision"].as_u64().unwrap();
            let guid=app.native_scene_guid.clone();
            harness.click(Role::Button,"Add CAN3 curve",|ctx|draw_can3_scene_gui(&mut app,ctx));
            assert_eq!(app.controller.snapshot()["revision"],revision+1,"{}",app.controller.status());
            let added=app.controller.snapshot()["model"].clone();
            let scene=added["scenes"].as_array().unwrap().iter().find(|scene|scene["guid"]==guid).unwrap();
            let field=if part {"partOpacityCurves"} else {"parameterCurves"};
            let curve=&scene["tracks"][0][field][0];
            assert_eq!(curve["points"],json!([]));assert_eq!(curve["curveTypes"],json!([]));
            if part {
                assert_eq!(curve["id"],"live2DPartsOpacity_root");assert_eq!(curve["partGuid"],"part-guid");
                assert_eq!(curve["sourcePart"],json!({"type":"CPartId","value":"root"}));assert_eq!(curve["range"],json!([0.0,1.0]));
            } else {
                assert_eq!(curve["id"],"live2dParam_ParamTest");assert_eq!(curve["parameterGuid"],"parameter-guid");
                assert_eq!(curve["sourceParameter"],json!({"type":"CParameterId","value":"ParamTest"}));assert_eq!(curve["range"],json!([-1.0,1.0]));
            }
            assert!(!app.can3_creation_dirty());
            app.command(json!({"op":"undo"}));assert_eq!(app.controller.snapshot()["model"],before);
            app.command(json!({"op":"redo"}));assert_eq!(app.controller.snapshot()["model"],added);
            let path=temp_dir(name).join("saved.can3");
            app.command(json!({"op":"save","path":path}));assert!(path.exists(),"{}",app.notice);
            app.command(json!({"op":"open","path":path}));assert_eq!(app.controller.snapshot()["model"],added);
        }
    }

