    #[test]
    fn can3_curve_gui_deletes_each_family_with_exact_identity_and_native_history() {
        use crate::editor_test_support::{texts,Harness};
        use egui::accesskit::Role;
        for (name,xml,field,index) in [
            ("can3-delete-parameter",include_str!("../tests/fixtures/can3-curve-editor.xml"),"parameterCurves",0),
            ("can3-delete-modern-part",include_str!("../tests/fixtures/can3-part-opacity.xml"),"partOpacityCurves",0),
            ("can3-delete-legacy",include_str!("../tests/fixtures/can3-underscore-opacity.xml"),"legacyPartOpacityCurves",0),
            ("can3-delete-underscore",include_str!("../tests/fixtures/can3-underscore-opacity.xml"),"underscorePartOpacityCurves",1),
        ] {
            let mut app=can3_app_with_xml(name,xml);
            let before=app.controller.snapshot()["model"].clone();
            let curve=before["scenes"][0]["tracks"][0][field][index].clone();
            let scene=before["scenes"][0]["guid"].as_str().unwrap();
            let track=before["scenes"][0]["tracks"][0]["guid"].as_str().unwrap();
            let id=curve["id"].as_str().unwrap();let key=curve["mapKey"].as_str();
            let mut harness=Harness::new();harness.screen=egui::vec2(1200.0,3200.0);
            click_curve_delete(&mut app,&mut harness,scene,track,id,key);
            let output=harness.frame(Vec::new(),|ctx|draw_can3_scene_gui(&mut app,ctx));
            let text=texts(&output).join("\n");assert!(text.contains(&format!("Curve ID: {id}")) && text.contains(field));
            if let Some(key)=key {assert!(text.contains(&format!("Map key: {key}")));}
            let revision=app.controller.snapshot()["revision"].as_u64().unwrap();
            harness.click(Role::Button,"Confirm curve deletion",|ctx|draw_can3_scene_gui(&mut app,ctx));
            assert_eq!(app.controller.snapshot()["revision"],revision+1,"{name}: {}",app.controller.status());
            let mut expected=before.clone();expected["scenes"][0]["tracks"][0][field].as_array_mut().unwrap().remove(index);
            let count=expected["scenes"][0]["tracks"][0]["legacyPartOpacityCurves"].as_array().unwrap().len()
                +expected["scenes"][0]["tracks"][0]["underscorePartOpacityCurves"].as_array().unwrap().len();
            expected["scenes"][0]["tracks"][0]["skippedLegacyPartOpacityCount"]=json!(count);
            assert_eq!(app.controller.snapshot()["model"],expected);
            app.command(json!({"op":"undo"}));assert_eq!(app.controller.snapshot()["model"],before);
            app.command(json!({"op":"redo"}));assert_eq!(app.controller.snapshot()["model"],expected);
            let path=temp_dir(name).join("saved.can3");app.command(json!({"op":"save","path":path}));assert!(path.exists(),"{}",app.notice);
            app.command(json!({"op":"open","path":path}));assert_eq!(app.controller.snapshot()["model"],expected);
        }
    }

    #[test]
    fn can3_curve_gui_reads_parts_explicitly_and_invalidates_attachment_choices() {
        use crate::editor_test_support::Harness;
        use egui::accesskit::Role;
        let name="can3-curve-part-choices";
        let xml=include_str!("../tests/fixtures/can3-scene-editor.xml").replace("fixture.cmo3","/missing/stored-model.cmo3");
        let mut app=can3_app_with_xml(name,&xml);let path=can3_curve_attach(&mut app,name);
        let mut harness=Harness::new();harness.screen=egui::vec2(1200.0,2600.0);
        can3_curve_choose(&mut app,&mut harness,"New curve kind","PartOpacity");
        assert!(app.can3_part_choices.source.is_none() && app.can3_part_choices.parts.is_empty());
        let before=document(&app);
        harness.click(Role::Button,"Refresh Part choices",|ctx|draw_can3_scene_gui(&mut app,ctx));
        assert_eq!(document(&app),before);assert_eq!(app.can3_part_choices.parts,vec![("root".into(),"root (part-guid)".into())],
            "status={} cache={:?} draftPath={} draftRev={} actualRev={} actualPath={} resource={}",app.controller.status(),app.can3_part_choices.source,
            app.can3_curve_draft.as_ref().unwrap().model_path,app.can3_curve_draft.as_ref().unwrap().expected_revision,
            app.controller.snapshot()["revision"],app.controller.snapshot()["nativePlayback"]["modelPath"],app.controller.snapshot()["nativePlayback"]["resourceGuid"]);
        assert_eq!(app.can3_part_choices.source,Some(("res-guid".into(),path.to_str().unwrap().into())));
        let source=soul2d_core::caff::CaffDocument::parse(&crate::editor_test_support::cmo3_bytes()).unwrap();
        let original_xml=String::from_utf8(source.main_xml()).unwrap();
        for (guid,mcp) in [("local-reloaded-part",false),("mcp-reloaded-part",true)] {
            let xml=original_xml.replace("part-guid",guid);
            std::fs::write(&path,source.replace_main_xml(xml.as_bytes()).unwrap()).unwrap();
            if mcp {call(&mut app,"live2d_model_attach",json!({"path":path,"resourceGuid":"res-guid"}));}
            else {app.command(json!({"op":"live2d.model.attach","path":path,"resourceGuid":"res-guid"}));}
            assert!(app.can3_part_choices.source.is_none() && app.can3_part_choices.parts.is_empty());
            harness.click(Role::Button,"Refresh Part choices",|ctx|draw_can3_scene_gui(&mut app,ctx));
            assert_eq!(app.can3_part_choices.parts,vec![("root".into(),format!("root ({guid})"))]);
        }
        let xml=String::from_utf8(source.main_xml()).unwrap().replace("part-guid","other-part-guid").replace("idstr='root'","idstr='OtherPart'");
        let other=path.parent().unwrap().join("other.cmo3");std::fs::write(&other,source.replace_main_xml(xml.as_bytes()).unwrap()).unwrap();
        app.command(json!({"op":"live2d.model.attach","path":other,"resourceGuid":"res-guid"}));
        harness.frame(Vec::new(),|ctx|draw_can3_scene_gui(&mut app,ctx));
        assert!(app.can3_part_choices.source.is_none() && app.can3_part_choices.parts.is_empty());
        assert_eq!(app.can3_curve_draft.as_ref().unwrap().model_path,path.to_str().unwrap());
        harness.click(Role::Button,"Discard new curve",|ctx|draw_can3_scene_gui(&mut app,ctx));
        can3_curve_choose(&mut app,&mut harness,"New curve kind","PartOpacity");
        harness.click(Role::Button,"Refresh Part choices",|ctx|draw_can3_scene_gui(&mut app,ctx));
        assert_eq!(app.can3_part_choices.parts,vec![("OtherPart".into(),"OtherPart (other-part-guid)".into())]);
        let xml=original_xml.replace("idstr='root'","idstr='Invalid:Part'");
        std::fs::write(&other,source.replace_main_xml(xml.as_bytes()).unwrap()).unwrap();
        app.command(json!({"op":"live2d.model.attach","path":other,"resourceGuid":"res-guid"}));
        harness.click(Role::Button,"Refresh Part choices",|ctx|draw_can3_scene_gui(&mut app,ctx));
        assert!(app.can3_part_choices.parts.is_empty());
        harness.click(Role::Button,"Discard new curve",|ctx|draw_can3_scene_gui(&mut app,ctx));
        call(&mut app,"new",json!({}));
        assert!(app.can3_part_choices.source.is_none() && app.can3_part_choices.parts.is_empty());
        assert!(app.can3_curve_draft.is_none() && app.can3_curve_track_guid.is_empty());
    }

