    #[test]
    fn can3_scene_gui_creates_from_named_fields_with_undo_redo_and_native_save() {
        use crate::editor_test_support::{name_of, Harness};
        use egui::accesskit::{Action, ActionData, ActionRequest, Role};
        let mut app = can3_scene_app("can3-scene-create-gui");
        let before = app.controller.snapshot()["model"].clone();
        let revision = app.controller.snapshot()["revision"].as_u64().unwrap();
        let mut harness = Harness::new();
        harness.click(Role::TextInput, "New scene name", |ctx| draw_can3_scene_gui(&mut app,ctx));
        harness.frame(vec![egui::Event::Key { key:egui::Key::A, physical_key:None, pressed:true, repeat:false,
            modifiers:egui::Modifiers { command:true, ctrl:true, ..Default::default() } }, egui::Event::Text("GUI scene".into())],
            |ctx| draw_can3_scene_gui(&mut app,ctx));
        assert_eq!(app.can3_scene_draft.name,"GUI scene");
        for (label,value) in [("New scene FPS",48.0),("New scene duration (frames)",120.0)] {
            let output=harness.frame(Vec::new(),|ctx|draw_can3_scene_gui(&mut app,ctx));
            let target=output.iter().find(|(_,node)|node.role()==Role::SpinButton && name_of(&output,node).as_deref()==Some(label))
                .map(|(id,_)|*id).unwrap();
            harness.frame(vec![egui::Event::AccessKitActionRequest(ActionRequest {
                action:Action::SetValue,target,data:Some(ActionData::NumericValue(value)),
            })],|ctx|draw_can3_scene_gui(&mut app,ctx));
        }
        assert_eq!(app.can3_scene_draft.fps,48.0);
        assert_eq!(app.can3_scene_draft.duration_frames,120);
        harness.click(Role::Button,"Add CAN3 scene",|ctx|draw_can3_scene_gui(&mut app,ctx));
        assert_eq!(app.controller.snapshot()["revision"],revision+1);
        let added=app.controller.snapshot()["model"].clone();
        let scene=added["scenes"].as_array().unwrap().last().unwrap().clone();
        assert_eq!(scene["name"],"GUI scene");
        assert_eq!(scene["fps"],48.0);
        assert_eq!(scene["durationFrames"],120);
        assert_eq!(scene["tracks"],json!([]));
        assert_eq!(app.native_scene_guid,scene["guid"].as_str().unwrap());
        assert!(!app.can3_scene_draft.is_dirty());
        app.command(json!({"op":"undo"}));
        assert_eq!(app.controller.snapshot()["model"],before);
        app.command(json!({"op":"redo"}));
        assert_eq!(app.controller.snapshot()["model"],added);
        let saved=temp_dir("can3-scene-create-gui").join("saved.can3");
        app.command(json!({"op":"save","path":saved}));
        assert!(saved.is_file(),"{}",app.notice);
        app.command(json!({"op":"open","path":saved}));
        assert_eq!(app.controller.snapshot()["model"]["scenes"].as_array().unwrap().last().unwrap(),&scene);
        let bytes=std::fs::read(saved).unwrap();
        let container=soul2d_core::caff::CaffDocument::parse(&bytes).unwrap();
        assert!(String::from_utf8(container.main_xml()).unwrap().contains("keep-root"));
    }

    #[test]
    fn can3_scene_gui_confirms_deletion_and_refuses_a_stale_confirmation() {
        use crate::editor_test_support::{texts,Harness};
        use egui::accesskit::Role;
        let mut app=can3_scene_app("can3-scene-delete-gui");
        let mut harness=Harness::new();
        app.can3_scene_draft.name="Pending scene".into();
        let before=document(&app);
        click_scene_delete(&mut app,&mut harness,"scene-guid");
        let output=harness.frame(Vec::new(),|ctx|draw_can3_scene_gui(&mut app,ctx));
        let labels=texts(&output).join("\n");
        assert!(labels.contains("GUID: scene-guid") && labels.contains("2 model tracks")
            && labels.contains("all stored contents") && labels.contains("known curve entries")
            && labels.contains("Undo is available"));
        assert_eq!(refused(&mut app,"new",json!({})),DIALOG_PENDING_MESSAGE);
        app.command(json!({"op":"new"}));
        assert_eq!(app.notice,DIALOG_PENDING_MESSAGE);
        assert_eq!(document(&app),before);
        harness.click(Role::Button,"Cancel scene deletion",|ctx|draw_can3_scene_gui(&mut app,ctx));
        assert!(app.can3_delete.is_none());
        assert_eq!(app.can3_scene_draft.name,"Pending scene");
        assert_eq!(document(&app),before);
        harness.click(Role::Button,"Discard new scene",|ctx|draw_can3_scene_gui(&mut app,ctx));
        click_scene_delete(&mut app,&mut harness,"scene-guid");
        let revision=app.controller.snapshot()["revision"].clone();
        call(&mut app,"live2d_animation_scene_set",json!({"sceneGuid":"scene-guid","name":"Changed by MCP","expectedRevision":revision}));
        let changed=document(&app);
        let output=harness.click(Role::Button,"Confirm scene deletion",|ctx|draw_can3_scene_gui(&mut app,ctx));
        assert!(texts(&output).iter().any(|label|label.contains("CAN3 changed")));
        assert_eq!(document(&app),changed);
        assert!(app.can3_delete.is_some());
        harness.click(Role::Button,"Cancel scene deletion",|ctx|draw_can3_scene_gui(&mut app,ctx));
        click_scene_delete(&mut app,&mut harness,"scene-guid");
        let revision=app.controller.snapshot()["revision"].as_u64().unwrap();
        harness.click(Role::Button,"Confirm scene deletion",|ctx|draw_can3_scene_gui(&mut app,ctx));
        assert!(app.can3_delete.is_none());
        assert_eq!(app.controller.snapshot()["revision"],revision+1);
        assert_eq!(app.controller.snapshot()["model"]["scenes"].as_array().unwrap().len(),1);
        let deleted=app.controller.snapshot()["model"].clone();
        app.command(json!({"op":"undo"}));
        assert_eq!(app.controller.snapshot()["model"],changed[0]);
        app.command(json!({"op":"redo"}));
        assert_eq!(app.controller.snapshot()["model"],deleted);
        let saved=temp_dir("can3-scene-delete-gui").join("saved.can3");
        app.command(json!({"op":"save","path":saved}));
        assert!(saved.is_file(),"{}",app.notice);
        app.command(json!({"op":"open","path":saved}));
        assert_eq!(app.controller.snapshot()["model"]["scenes"].as_array().unwrap().len(),1);
    }

