    #[test]
    fn can3_scene_form_is_frozen_while_a_dialog_waits() {
        use crate::editor_test_support::{find,Harness};
        use egui::accesskit::Role;
        for kind in ["unsaved","restore","delete","closing"] {
            let mut app=can3_scene_app(&format!("can3-scene-wait-{kind}"));
            let mut harness=Harness::new();
            harness.click(Role::TextInput,"New scene name",|ctx|draw_can3_scene_gui(&mut app,ctx));
            match kind {
                "unsaved" => {
                    let revision=app.controller.snapshot()["revision"].clone();
                    app.command(json!({"op":"live2d.animation.scene.set","sceneGuid":"scene-guid","name":"Modified","expectedRevision":revision}));
                    app.command(json!({"op":"new"}));
                    assert!(app.unsaved.is_some());
                }
                "restore" => app.tools.prompt=Some(RestorePrompt {project:"/tmp/restore.can3".into(),backups:1}),
                "delete" => app.can3_delete=Some(Can3DeleteConfirmation::Scene(SceneDeleteConfirmation {scene_guid:"scene-guid".into(),scene_name:"Scene".into(),expected_revision:app.controller.snapshot()["revision"].as_u64().unwrap()})),
                _ => harness.next_input=Some(Box::new(|input|input.viewports.entry(egui::ViewportId::ROOT).or_default().events.push(egui::ViewportEvent::Close))),
            }
            let output=harness.frame(vec![egui::Event::Text("Unreviewed input".into())],|ctx| {
                if kind=="closing" {app.handle_close_request(ctx);}
                draw_can3_scene_gui(&mut app,ctx);
            });
            if kind=="closing" {assert!(app.closing);}
            assert_eq!(app.can3_scene_draft.name,"Scene","{kind}");
            for (role,label) in [(Role::TextInput,"New scene name"),(Role::SpinButton,"New scene FPS"),
                (Role::SpinButton,"New scene duration (frames)"),(Role::Button,"Add CAN3 scene")] {
                assert!(find(&output,role,label).unwrap().is_disabled(),"{kind} {label}");
            }
            if kind=="unsaved" {
                harness.click(Role::Button,"Don't Save",|ctx|app.draw_unsaved(ctx));
                assert_eq!(app.controller.snapshot()["documentFormat"],"inx");
                assert!(!app.can3_scene_draft.is_dirty());
            }
        }
    }

    #[test]
    fn remote_quit_is_accepted_without_closing_before_its_reply_is_written() {
        let mut app = app("remote-quit-before-reply");
        let before = document(&app);
        let (sender, receiver) = std::sync::mpsc::channel();
        let (reply, written) = std::sync::mpsc::sync_channel(1);
        app.host_rx = Some(receiver);
        sender.send(HostMessage::Rpc { request: json!({"jsonrpc":"2.0","id":"quit-red","method":"tools/call",
            "params":{"name":"editor_quit","arguments":{}}}), reply }).unwrap();
        let output = egui::Context::default().run(Default::default(), |ctx| app.drain_host(ctx));
        let response = written.try_recv().unwrap().into_message();
        assert_eq!(response.as_ref().unwrap()["result"]["isError"], false, "{response:?}");
        assert!(!app.closing);
        assert!(output.viewport_output.values().all(|viewport| !viewport.commands.iter()
            .any(|command| matches!(command, egui::ViewportCommand::Close))));
        assert_eq!(document(&app), before);
    }

    fn request_quit(app: &mut EditorApp) -> RpcReply {
        let message = json!({"jsonrpc":"2.0","id":"quit-test","method":"tools/call",
            "params":{"name":"editor_quit","arguments":{}}});
        app.sync_panel_drafts();
        CTX.with(|ctx| editor_view!(app, ctx).mcp(&mut app.controller, &message, McpOrigin::Client))
    }

    fn finish_quit(app: &mut EditorApp) -> usize {
        let output = egui::Context::default().run(Default::default(), |ctx| app.finish_remote_quit(ctx));
        output.viewport_output.values().flat_map(|viewport| viewport.commands.iter())
            .filter(|command| matches!(command, egui::ViewportCommand::Close)).count()
    }

