    #[cfg(unix)]
    #[test]
    fn acp_quit_real_writer_failure_cannot_be_revived_by_successful_turn() {
        acp_quit_scenario("writer_failure");
    }

    fn acp_quit_scenario(scenario: &str) {
        use crate::editor_test_support::Harness;
        use egui::accesskit::Role;
        let mut app = app(&format!("acp-quit-review-http-{scenario}"));
        let before = document(&app);
        let before_snapshot = app.controller.snapshot().clone();
        let run_dir = temp_dir(&format!("acp-quit-review-peer-{scenario}"));
        let fixture = Path::new(env!("CARGO_MANIFEST_DIR")).join("../tools/acp-panel-approval-fixture.py");
        let python = if cfg!(windows) { "python" } else { "python3" };
        let interpreter = std::process::Command::new(python).args(["-I", "-c", "import sys; print(sys.executable)"])
            .output().unwrap();
        assert!(interpreter.status.success(), "fixture interpreter probe failed: {interpreter:?}");
        let interpreter = String::from_utf8(interpreter.stdout).unwrap().trim().to_owned();
        assert!(!interpreter.is_empty(), "fixture interpreter probe returned no executable path");
        app.tools.store.set("ACP.Command", format!("\"{}\" -I \"{}\" --run-dir \"{}\"",
            interpreter, fixture.display(), run_dir.display())).unwrap();
        app.tools.store.set("ACP.Workdir", env!("CARGO_MANIFEST_DIR").to_owned()).unwrap();
        app.agent.set_enabled(true);
        app.agent.start(&app.tools.store);
        let mut harness = Harness::new();
        harness.screen = egui::vec2(1400.0, 1200.0);
        let mut frame = eframe::Frame::_new_kittest();
        let result = (|| -> Result<(), String> {
            let deadline = Instant::now() + Duration::from_secs(15);
            while !app.agent.state().ready {
                harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame));
                if Instant::now() >= deadline || app.agent.state().closed {
                    return Err(format!("fixture initialization failed using {interpreter}: {} {:?}", app.agent.status(), app.agent.error()));
                }
                std::thread::sleep(Duration::from_millis(10));
            }
            *app.agent.prompt_mut() = "Deterministic lifecycle review check".into();
            app.agent.send();
            let deadline = Instant::now() + Duration::from_secs(15);
            let instance = loop {
                harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame));
                let instance = std::fs::read_dir(run_dir.join("instances")).ok().into_iter().flatten()
                    .filter_map(Result::ok).map(|entry| entry.path())
                    .find(|path| path.join("prompt-ready.json").exists());
                if let Some(instance) = instance { break instance; }
                if Instant::now() >= deadline { return Err("fixture prompt did not start".into()); }
                std::thread::sleep(Duration::from_millis(10));
            };
            std::fs::write(instance.join("commands/001.tmp"), json!({"reset_after_review":scenario == "writer_failure", "request":{
                "jsonrpc":"2.0", "id":"acp-quit-review", "method":"tools/call",
                "params":{"name":"editor_quit", "arguments":{}}
            }}).to_string()).map_err(|error| error.to_string())?;
            std::fs::rename(instance.join("commands/001.tmp"), instance.join("commands/001.json"))
                .map_err(|error| error.to_string())?;
            let deadline = Instant::now() + Duration::from_secs(15);
            loop {
                let output = harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame));
                let reviewed = crate::editor_test_support::has(&output, Role::Label, "Tool: editor_quit")
                    && crate::editor_test_support::has(&output, Role::Button, "Allow once");
                let early = std::fs::read_to_string(instance.join("results/001.json")).ok();
                if app.closing || document(&app) != before {
                    return Err("Quit changed the document or closed before lifecycle consent".into());
                }
                if reviewed {
                    if early.is_some() { return Err(format!("original request completed before Allow once: {early:?}")); }
                    break;
                }
                if early.is_some() || Instant::now() >= deadline {
                    return Err(format!("Quit must reach human lifecycle review; early result: {early:?}"));
                }
                std::thread::sleep(Duration::from_millis(10));
            }
            if scenario == "success" {
                let duplicate = json!({"request":{"jsonrpc":"2.0", "id":"acp-quit-review", "method":"tools/call",
                    "params":{"name":"editor_quit", "arguments":{}}}});
                std::fs::write(instance.join("commands/002.tmp"), duplicate.to_string()).unwrap();
                std::fs::rename(instance.join("commands/002.tmp"), instance.join("commands/002.json")).unwrap();
                let deadline = Instant::now() + Duration::from_secs(15);
                while !instance.join("results/002.json").exists() {
                    harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame));
                    if Instant::now() >= deadline { return Err("duplicate Quit was not refused".into()); }
                    std::thread::sleep(Duration::from_millis(10));
                }
                let duplicate: Value = serde_json::from_slice(&std::fs::read(instance.join("results/002.json")).unwrap()).unwrap();
                if duplicate["response"]["result"]["isError"] != true || instance.join("results/001.json").exists()
                    || app.remote_quit.state()["state"] != "awaiting_human" {
                    return Err(format!("duplicate replaced or invalidated the original: {duplicate}"));
                }
            }
            if scenario == "writer_failure" {
                std::fs::write(instance.join("results/001.reset"), b"reset after human review").unwrap();
                let deadline = Instant::now() + Duration::from_secs(15);
                while !instance.join("results/001.json").exists() {
                    harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame));
                    if Instant::now() >= deadline { return Err("reviewed HTTP peer did not reset".into()); }
                    std::thread::sleep(Duration::from_millis(10));
                }
                let reset: Value = serde_json::from_slice(&std::fs::read(instance.join("results/001.json")).unwrap()).unwrap();
                if reset["resetSent"] != true { return Err(format!("HTTP peer reset failed: {reset}")); }
            }
            match scenario {
                "deny" => { harness.click(Role::Button, "Deny changes this turn", |ctx| app.update(ctx, &mut frame)); },
                "cancel" => app.agent.cancel(),
                "early_turn" => { std::fs::write(instance.join("commands/003.json"), json!({"action":"finish"}).to_string()).unwrap(); },
                "transient_draft" => {
                    app.form_time_draft = Some(3.0);
                    harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame));
                    app.form_time_draft = None;
                },
                "transient_depth" => {
                    app.psd_depth.open = true;
                    harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame));
                    app.psd_depth.open = false;
                },
                "native_draft_discard" => {
                    app.select_node_draft(2);
                    let original = app.draft_name.clone();
                    let draw = |app: &mut EditorApp, ctx: &egui::Context| {
                        let dirty = app.controller.draft_dirty();
                        let stale = app.controller.draft_stale();
                        egui::CentralPanel::default().show(ctx, |ui| app.draft_editor(ui,
                            Some(OwnedDraft::NodeName { id: 2, original: original.clone() }), dirty, stale));
                    };
                    harness.click(Role::TextInput, &original, |ctx| draw(&mut app, ctx));
                    harness.frame(vec![egui::Event::Text(" changed".into())], |ctx| {
                        draw(&mut app, ctx);
                        app.controller.discard_draft();
                    });
                    if app.remote_quit.state()["state"] != "cancelled" || app.controller.draft_dirty() {
                        return Err("native edit then Discard in one frame preserved stale consent".into());
                    }
                },
                "new_operation" => app.run_command(json!({"op":"history.limit.set","limit":100})),
                _ => {},
            }
            if matches!(scenario, "deny" | "cancel" | "early_turn" | "transient_draft" | "transient_depth" | "native_draft_discard" | "new_operation") {
                let deadline = Instant::now() + Duration::from_secs(15);
                while !instance.join("results/001.json").exists() || app.remote_quit.state()["state"] != "cancelled" {
                    harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame));
                    if Instant::now() >= deadline { return Err(format!("invalidated original was not refused: {}", app.remote_quit.state())); }
                    std::thread::sleep(Duration::from_millis(10));
                }
                let response: Value = serde_json::from_slice(&std::fs::read(instance.join("results/001.json")).unwrap()).unwrap();
                if response["response"]["result"]["isError"] != true || app.closing || harness.close_requests != 0
                    || !app.agent.state().has_client || document(&app) != before {
                    return Err(format!("invalidated review changed work, released the client or accepted: {response}"));
                }
                for _ in 0..3 { harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame)); }
                if app.remote_quit.state()["state"] != "cancelled" { return Err("clean editor revived stale consent".into()); }
                return Ok(());
            }
            app.hold_quit_receipt_for_test = scenario == "receipt_held";
            if scenario == "final_refusal" {
                app.after_quit_release_for_test = Some(|app| app.form_time_draft = Some(3.0));
            }
            harness.click(Role::Button, "Allow once", |ctx| app.update(ctx, &mut frame));
            if scenario == "writer_failure" {
                let deadline = Instant::now() + Duration::from_secs(15);
                while app.remote_quit.state()["state"] != "cancelled" {
                    harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame));
                    if Instant::now() >= deadline { return Err("reset peer produced no failed writer receipt".into()); }
                    std::thread::sleep(Duration::from_millis(10));
                }
                if !app.remote_quit.state()["reason"].as_str().is_some_and(|reason| reason.starts_with("reply_failed:")) {
                    return Err(format!("reset did not cause a real failed writer receipt: {}", app.remote_quit.state()));
                }
                std::fs::write(instance.join("commands/003.tmp"), json!({"action":"finish"}).to_string()).unwrap();
                std::fs::rename(instance.join("commands/003.tmp"), instance.join("commands/003.json")).unwrap();
                let deadline = Instant::now() + Duration::from_secs(15);
                while app.agent.state().turn_active {
                    harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame));
                    if Instant::now() >= deadline { return Err("post-failure turn did not finish".into()); }
                    std::thread::sleep(Duration::from_millis(10));
                }
                if app.agent.status() != "Done (end_turn)" || app.agent.state().closed || app.closing
                    || !app.agent.state().has_client || harness.close_requests != 0 || document(&app) != before {
                    return Err("successful turn was not observed or revived a failed writer receipt".into());
                }
                return Ok(());
            }
            let deadline = Instant::now() + Duration::from_secs(15);
            let response: Value = loop {
                harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame));
                if let Ok(bytes) = std::fs::read(instance.join("results/001.json")) {
                    break serde_json::from_slice(&bytes).map_err(|error| error.to_string())?;
                }
                if Instant::now() >= deadline { return Err("original HTTP acceptance was not delivered".into()); }
                std::thread::sleep(Duration::from_millis(10));
            };
            if response["status"] != 200 || response["response"]["id"] != "acp-quit-review"
                || response["response"]["result"]["isError"] != false
                || response["response"]["result"]["structuredContent"]["quit"]["state"] != "accepted" {
                return Err(format!("original HTTP acceptance was wrong: {response}"));
            }
            if app.closing || !app.agent.state().has_client || harness.close_requests != 0 {
                return Err("Quit released or closed before the initiating prompt completed".into());
            }
            let completion = match scenario {
                "late_permission" => json!({"action":"permission"}),
                "unknown_turn" => json!({"action":"finish", "result":{"stopReason":"unknown"}}),
                "failed_turn" => json!({"action":"finish", "error":{"code":-32000,"message":"deterministic failure"}}),
                _ => json!({"action":"finish"}),
            };
            if scenario == "turn_timeout" {
                if let RemoteQuit::Waiting { origin: QuitOrigin::Acp { turn_deadline, .. }, .. } = &mut app.remote_quit {
                    *turn_deadline = Instant::now() - Duration::from_secs(1);
                }
            }
            std::fs::write(instance.join("commands/003.tmp"), completion.to_string())
                .map_err(|error| error.to_string())?;
            std::fs::rename(instance.join("commands/003.tmp"), instance.join("commands/003.json"))
                .map_err(|error| error.to_string())?;
            let deadline = Instant::now() + Duration::from_secs(15);
            if scenario == "receipt_held" {
                while app.agent.state().turn_active {
                    harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame));
                    if Instant::now() >= deadline { return Err("held-receipt turn did not finish".into()); }
                    std::thread::sleep(Duration::from_millis(10));
                }
                let observed = match &app.remote_quit {
                    RemoteQuit::Waiting { delivered: false, origin: QuitOrigin::Acp { target, admitted_at, .. }, .. } =>
                        app.agent.quit_status(target, Some(*admitted_at)) == Ok(true),
                    _ => false,
                };
                if !observed || app.closing || !app.agent.state().has_client || harness.close_requests != 0 {
                    return Err("completion before receipt processing released or closed the editor".into());
                }
                app.hold_quit_receipt_for_test = false;
            }
            if !matches!(scenario, "success" | "receipt_held") {
                while app.remote_quit.state()["state"] != "cancelled" {
                    harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame));
                    if Instant::now() >= deadline { return Err(format!("unsuccessful turn was not cancelled: {}", app.remote_quit.state())); }
                    std::thread::sleep(Duration::from_millis(10));
                }
                let owner_correct = app.agent.state().has_client != (scenario == "final_refusal");
                let draft_correct = scenario != "final_refusal" || app.form_time_draft == Some(3.0);
                if app.closing || !owner_correct || !draft_correct || harness.close_requests != 0 || document(&app) != before {
                    return Err("unsuccessful turn released the client, changed work or closed".into());
                }
                return Ok(());
            }
            while !app.closing {
                harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame));
                if Instant::now() >= deadline { return Err(format!("Quit did not finish: {} {}", app.remote_quit.state(), app.notice)); }
                std::thread::sleep(Duration::from_millis(10));
            }
            harness.frame(Vec::new(), |ctx| app.update(ctx, &mut frame));
            if app.agent.state().has_client || !app.close_sent || harness.close_requests != 1 || document(&app) != before {
                return Err("Quit must release only the owned client, preserve the document and send one Close".into());
            }
            Ok(())
        })();
        // Resolve a parked request and reap the owned fixture before asserting the expected RED.
        app.agent.stop();
        assert!(result.is_ok(), "{scenario}: {}", result.unwrap_err());
        assert_eq!(document(&app), before);
        if matches!(scenario, "success" | "receipt_held" | "writer_failure" | "final_refusal") {
            assert_eq!(app.controller.snapshot(), &before_snapshot);
        }
        assert_eq!(app.closing, matches!(scenario, "success" | "receipt_held"));
    }

    #[test]
    fn remote_quit_closes_once_only_after_the_exact_reply_has_been_flushed() {
        let mut app = app("remote-quit-flush");
        let before = document(&app);
        let reply = request_quit(&mut app);
        assert_eq!(finish_quit(&mut app), 0);
        assert_eq!(state(&mut app)["quit"]["state"], "waiting_for_reply");
        let duplicate = request_quit(&mut app).into_message().unwrap();
        assert_eq!(duplicate["result"]["isError"], true);
        assert_eq!(app.remote_quit.attempt(), 1);
        let mut bytes = Vec::new(); reply.write_line(&mut bytes).unwrap();
        let response: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(response["id"], "quit-test");
        assert_eq!(response["result"]["structuredContent"]["quit"]["state"], "accepted");
        assert_eq!(finish_quit(&mut app), 1);
        assert!(app.closing && app.close_sent);
        assert_eq!(finish_quit(&mut app), 0);
        let mut frame = eframe::Frame::_new_kittest();
        let _ = egui::Context::default().run(Default::default(), |ctx| app.update(ctx, &mut frame));
        assert_eq!(document(&app), before, "a committed quit processes no later authoring frame");
    }

    #[test]
    fn remote_quit_expired_lost_and_failed_receipts_cannot_close_through_eof() {
        struct Broken;
        impl std::io::Write for Broken {
            fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> { Ok(bytes.len()) }
            fn flush(&mut self) -> std::io::Result<()> { Err(std::io::ErrorKind::BrokenPipe.into()) }
        }
        for failure in ["expired", "lost", "failed"] {
            let mut app = app(&format!("remote-quit-{failure}"));
            let reply = request_quit(&mut app);
            match failure {
                "expired" => {
                    if let RemoteQuit::Waiting { deadline, .. } = &mut app.remote_quit { *deadline = Instant::now() - Duration::from_secs(1); }
                    assert_eq!(finish_quit(&mut app), 0);
                    reply.write_line(&mut Vec::new()).unwrap();
                }
                "lost" => drop(reply),
                _ => { assert!(reply.write_line(&mut Broken).is_err()); }
            }
            assert_eq!(finish_quit(&mut app), 0);
            assert_eq!(app.remote_quit.state()["state"], "cancelled");
            let (sender, receiver) = std::sync::mpsc::channel(); app.host_rx = Some(receiver);
            sender.send(HostMessage::StdinClosed).unwrap();
            let output = egui::Context::default().run(Default::default(), |ctx| app.drain_host(ctx));
            assert!(output.viewport_output.values().all(|viewport| !viewport.commands.iter()
                .any(|command| matches!(command, egui::ViewportCommand::Close))));
            assert!(!app.closing);
            request_quit(&mut app).write_line(&mut Vec::new()).unwrap();
            assert_eq!(app.remote_quit.attempt(), 2);
            assert_eq!(finish_quit(&mut app), 1, "a fresh request can close after cancellation");
        }
    }

    #[test]
    fn remote_quit_rechecks_late_work_and_document_identity_after_delivery() {
        for event in ["edit-undo", "draft", "dialog", "tool", "depth", "replace", "animation", "parameter", "split", "merge"] {
            let mut app = app(&format!("remote-quit-late-{event}"));
            let reply = request_quit(&mut app);
            match event {
                "edit-undo" => {
                    app.command(json!({"op":"node.rename","id":2,"name":"Changed"}));
                    app.command(json!({"op":"undo"})); assert!(app.controller.can_close());
                }
                "draft" => app.can3_scene_draft.name = "Pending".into(),
                "dialog" => app.tools.prompt = Some(RestorePrompt { project: "x".into(), backups: 1 }),
                "tool" => app.mesh_tools.start_edit_mesh(2),
                "depth" => app.depth_tools.enter(2),
                "replace" => app.after_document_replaced(),
                "parameter" => app.parameters.edit = Some(ParameterEditDraft {
                    name: "Changed".into(), ..ParameterEditDraft::new(10, "Blink".into(), None) }),
                "split" => app.parameters.split = Some((10, vec![2])),
                "merge" => app.tools.merge.planned = Some(("pending.psd".into(), 0)),
                _ => {
                    app.animation_draft = AnimationDraft::read(("Idle".into(), 0), &json!({"length":10}));
                    app.animation_draft.length = 11;
                }
            }
            reply.write_line(&mut Vec::new()).unwrap();
            assert_eq!(finish_quit(&mut app), 0, "{event}");
            assert!(!app.closing);
            assert_eq!(app.remote_quit.state()["state"], "cancelled", "{event}");
        }
    }

    #[test]
    fn remote_quit_parameter_drafts_refuse_at_admission_and_reset_with_the_document() {
        let mut app = app_with_two_snapshots("remote-quit-parameter-drafts");
        let parameter = &app.controller.snapshot()["model"]["param"][0];
        let axes = AxesDraft::read(parameter).unwrap();
        app.parameters.edit = Some(ParameterEditDraft::new(10, "Blink".into(), Some(axes.clone())));
        assert!(!app.parameters.has_draft());
        for field in ["name", "axes", "split", "merge"] {
            match field {
                "name" => app.parameters.edit.as_mut().unwrap().name = "Pending".into(),
                "axes" => app.parameters.edit.as_mut().unwrap().axes.as_mut().unwrap().min[0] -= 0.5,
                "split" => app.parameters.split = Some((10, vec![2])),
                _ => app.tools.merge.planned = Some(("pending.psd".into(), 0)),
            }
            assert_eq!(request_quit(&mut app).into_message().unwrap()["result"]["isError"], true, "{field}");
            assert!(matches!(app.remote_quit, RemoteQuit::Idle));
            let before = document(&app);
            let response = rpc(&mut app, "tools/call", json!({"name":"new","arguments":{}}));
            assert_eq!(response["isError"], true, "replacement must preserve {field}: {response}");
            assert_eq!(document(&app), before);
            let response = rpc(&mut app, "tools/call", json!({"name":"editor_recovery_restore","arguments":{"id":SNAPSHOT_NEW}}));
            assert_eq!(response["isError"], true, "recovery must preserve {field}: {response}");
            assert_eq!(document(&app), before);
            assert!(recovery_dir_of(&app).join(SNAPSHOT_NEW).exists());
            app.guard_replace(PendingAction::Request(json!({"op":"new"})));
            assert_eq!(document(&app), before, "native replacement must preserve {field}");
            assert!(app.parameters.has_draft() || app.tools.merge.planned.is_some());
            app.parameters.edit = Some(ParameterEditDraft::new(10, "Blink".into(), Some(axes.clone())));
            app.parameters.split = None;
            app.tools.merge = MergeDraft::default();
        }
        app.animation_draft = AnimationDraft::read(("Idle".into(), 0), &json!({"length":10}));
        app.animation_draft.length = 11;
        app.form_time_draft = Some(3.0);
        app.timeline_marker_at = Some(("Idle".into(), 0));
        app.timeline_marker_text = "Old document".into();
        app.parameters.edit.as_mut().unwrap().name = "Old name".into();
        app.parameters.split = Some((10, vec![2]));
        app.tools.merge.planned = Some(("old.psd".into(), 0));
        app.after_document_replaced();
        assert!(!app.animation_draft.has_draft() && !app.parameters.has_draft());
        assert!(app.form_time_draft.is_none() && app.timeline_marker_at.is_none() && app.timeline_marker_text.is_empty());
        assert!(app.tools.merge.planned.is_none());
        request_quit(&mut app).write_line(&mut Vec::new()).unwrap();
        assert_eq!(finish_quit(&mut app), 1);
    }

    #[test]
    fn remote_quit_notifications_acp_and_internal_calls_never_arm_exit() {
        let mut app = app("remote-quit-origins");
        let before = document(&app);
        let message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"editor_quit","arguments":{}}});
        for id in [None, Some(Value::Null)] {
            let mut notification = message.clone(); notification.as_object_mut().unwrap().remove("id");
            if let Some(id) = id { notification["id"] = id; }
            let mut bytes = Vec::new();
            CTX.with(|ctx| editor_view!(app, ctx).mcp(&mut app.controller, &notification, McpOrigin::Client))
                .write_line(&mut bytes).unwrap();
            assert!(bytes.is_empty(), "notifications never produce a Quit reply");
            assert!(matches!(app.remote_quit, RemoteQuit::Idle));
        }
        let mut approval = crate::editor_agent::HostApproval::default(); approval.set_active(true);
        assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], true);
        let internal = CTX.with(|ctx| editor_view!(app, ctx).mcp(&mut app.controller, &message, McpOrigin::Internal)).into_message().unwrap();
        assert_eq!(internal["result"]["isError"], true);
        assert!(matches!(app.remote_quit, RemoteQuit::Idle));
        assert_eq!(document(&app), before);
    }

