    #[test]
    fn command_browser_visibility_validates_without_document_settings_or_draft_changes() {
        use crate::editor_agent::HostApproval;
        use crate::editor_test_support::Harness;
        use egui::accesskit::Role;
        let mut app = app("editor-command-browser");
        app.select_node_draft(2);
        app.controller.set_draft_name("Pending".into());
        app.parameters.armed = Some(10);
        let before = app.controller.snapshot().clone();
        let initial = state(&mut app);
        let path = app.tools.store_path.clone().unwrap();
        let settings = std::fs::read(&path).ok();
        for open in [true, true, false, false, true] {
            let response = call(&mut app, "editor_command_browser_set", json!({"open":open}));
            assert_eq!(response["windows"]["commandBrowser"], open);
            assert_eq!(state(&mut app)["windows"]["commandBrowser"], open);
        }
        assert_eq!(initial["windows"]["commandBrowser"], false);
        let unchanged = state(&mut app);
        for arguments in [json!({}), json!([]), json!({"open":null}), json!({"open":1}),
            json!({"open":"true"}), json!({"open":false,"extra":true})] {
            refused(&mut app, "editor_command_browser_set", arguments);
            assert_eq!(state(&mut app), unchanged);
        }
        let mut approval = HostApproval::default();
        let mut message = json!({"jsonrpc":"2.0","id":1,"method":"tools/call",
            "params":{"name":"editor_command_browser_set","arguments":{"open":false}}});
        assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], false);
        assert_eq!(state(&mut app)["windows"]["commandBrowser"], false);
        approval.set_active(true);
        let protected = json!({"jsonrpc":"2.0","id":2,"method":"tools/call",
            "params":{"name":"editor_settings_set","arguments":{"key":"NerdStats","value":true}}});
        assert_eq!(agent_rpc(&mut app, &mut approval, &protected).unwrap()["result"]["isError"], true);
        Harness::new().click(Role::Button, "Deny changes this turn", |ctx| approval.show(ctx, app.tools.store_path.as_deref()));
        message["params"]["arguments"]["open"] = json!(true);
        assert_eq!(agent_rpc(&mut app, &mut approval, &message).unwrap()["result"]["isError"], false);
        let after = state(&mut app);
        assert_eq!(after["windows"]["commandBrowser"], true);
        for key in ["guides", "viewport", "selection", "armed", "drafts", "camera", "panels"] {
            assert_eq!(after[key], initial[key], "{key}");
        }
        assert_eq!(app.controller.snapshot(), &before);
        assert_eq!(std::fs::read(path).ok(), settings);
    }

