    #[test]
    fn address_dialog_validates_actions_and_preserves_document_and_settings() {
        let mut app = app("editor-address-dialog");
        let before = document(&app);
        let path = app.tools.store_path.clone().unwrap();
        let settings = std::fs::read(&path).ok();
        assert_eq!(state(&mut app)["windows"]["addressDialog"], Value::Null);
        assert_eq!(refused(&mut app, "editor_address_dialog", json!({"action":"copy"})), "no address dialog is open");
        for target in soul2d_core::window_shell::AddressDialogTarget::ALL {
            let answer = call(&mut app, "editor_address_dialog", json!({"action":"open", "target":target.id()}));
            let dialog = answer["windows"]["addressDialog"].clone();
            assert_eq!(dialog["target"], target.id());
            assert!(dialog["title"].as_str().is_some_and(|title| !title.is_empty()));
            assert!(dialog["address"].is_string());
            assert_eq!(state(&mut app)["windows"]["addressDialog"], dialog);
            CTX.with(|ctx| ctx.output_mut(|output| output.commands.clear()));
            assert_eq!(call(&mut app, "editor_address_dialog", json!({"action":"copy"}))["windows"]["addressDialog"], dialog);
            CTX.with(|ctx| assert_eq!(ctx.output_mut(|output| std::mem::take(&mut output.commands)),
                vec![egui::OutputCommand::CopyText(dialog["address"].as_str().unwrap().to_owned())]));
        }
        let state_before = state(&mut app);
        for arguments in [json!({}), json!([]), json!({"action":null}), json!({"action":true}),
            json!({"action":"launch"}), json!({"action":"open"}), json!({"action":"open","target":"unknown"}),
            json!({"action":"open","target":null}), json!({"action":"open","target":1}),
            json!({"action":"copy","target":"bug_report"}), json!({"action":"close","target":null}),
            json!({"action":"open","target":"bug_report","url":"https://example.com"}),
            json!({"action":"close","title":"Override"}), json!({"action":"copy","path":"/tmp"})] {
            refused(&mut app, "editor_address_dialog", arguments);
            assert_eq!(state(&mut app), state_before);
            CTX.with(|ctx| assert!(ctx.output(|output| output.commands.is_empty())));
        }
        app.tools.store_path = None;
        assert_eq!(refused(&mut app, "editor_address_dialog", json!({"action":"open","target":"configuration"})),
            "the configuration folder is unavailable");
        assert_eq!(state(&mut app), state_before);
        for _ in 0..2 {
            assert_eq!(call(&mut app, "editor_address_dialog", json!({"action":"close"}))["windows"]["addressDialog"], Value::Null);
        }
        assert_eq!(document(&app), before);
        assert_eq!(std::fs::read(&path).ok(), settings);
    }

